window.SWMN_DATA=window.SWMN_DATA||{};window.SWMN_DATA["k2v2"]=[{"id":"k2v2-b01","courseId":"k2v2","order":1,"title":"Đi Bắc Kinh du lịch vào tháng 9 là tốt nhất","titleZh":"九月去北京旅游最好","vocab":[{"stt":1,"hanzi":"旅游","pinyin":"lǚyóu","hanviet":"Lữ du","pos":"Động từ","meaning":"Du lịch","comps":"去旅游 · 旅游最好 · 想去旅游","example":{"zh":"九月去北京旅游最好。","py":"Jiǔ yuè qù Běijīng lǚyóu zuì hǎo.","vi":"Tháng 9 đi Bắc Kinh du lịch là tốt nhất."}},{"stt":2,"hanzi":"觉得","pinyin":"juéde","hanviet":"Giác đắc","pos":"Động từ","meaning":"Cho rằng, cảm thấy, nghĩ rằng","comps":"我觉得 · 你觉得 · 觉得很好","example":{"zh":"你觉得什么时候去最好？","py":"Nǐ juéde shénme shíhou qù zuì hǎo?","vi":"Bạn nghĩ đi vào lúc nào là tốt nhất?"}},{"stt":3,"hanzi":"最","pinyin":"zuì","hanviet":"Tối","pos":"Phó từ","meaning":"Nhất (mức cao nhất)","comps":"最好 · 最大 · 最喜欢","example":{"zh":"九月去北京旅游最好。","py":"Jiǔ yuè qù Běijīng lǚyóu zuì hǎo.","vi":"Tháng 9 đi Bắc Kinh du lịch là tốt nhất."}},{"stt":4,"hanzi":"为什么","pinyin":"wèi shénme","hanviet":"Vị thập ma","pos":"Đại từ nghi vấn","meaning":"Tại sao, vì sao","comps":"为什么？ · 你为什么…… · 为什么不去？","example":{"zh":"为什么九月去最好？","py":"Wèi shénme jiǔ yuè qù zuì hǎo?","vi":"Tại sao tháng 9 đi là tốt nhất?"}},{"stt":5,"hanzi":"也","pinyin":"yě","hanviet":"Dã","pos":"Phó từ","meaning":"Cũng","comps":"我也…… · 也不…… · 也很好","example":{"zh":"九月的北京不冷也不热。","py":"Jiǔ yuè de Běijīng bù lěng yě bú rè.","vi":"Bắc Kinh tháng 9 không lạnh cũng không nóng."}},{"stt":6,"hanzi":"运动","pinyin":"yùndòng","hanviet":"Vận động","pos":"Danh từ / Động từ","meaning":"Môn thể thao; tập thể dục, vận động","comps":"什么运动 · 喜欢运动 · 去运动","example":{"zh":"你喜欢什么运动？","py":"Nǐ xǐhuan shénme yùndòng?","vi":"Bạn thích môn thể thao nào?"}},{"stt":7,"hanzi":"踢足球","pinyin":"tī zúqiú","hanviet":"Thích túc cầu","pos":"Cụm động từ","meaning":"Đá bóng, đá bóng đá","comps":"喜欢踢足球 · 去踢足球 · 一起踢足球","example":{"zh":"我最喜欢踢足球。","py":"Wǒ zuì xǐhuan tī zúqiú.","vi":"Mình thích đá bóng nhất."}},{"stt":8,"hanzi":"一起","pinyin":"yìqǐ","hanviet":"Nhất khởi","pos":"Phó từ","meaning":"Cùng, cùng nhau","comps":"一起去 · 一起吃 · 和朋友一起","example":{"zh":"下午我们一起去踢足球吧。","py":"Xiàwǔ wǒmen yìqǐ qù tī zúqiú ba.","vi":"Chiều nay chúng ta cùng đi đá bóng nhé."}},{"stt":9,"hanzi":"要","pinyin":"yào","hanviet":"Yếu","pos":"Trợ động từ","meaning":"Muốn, cần (làm gì)","comps":"要去 · 要买 · 要不要","example":{"zh":"我们要不要买几个新的椅子？","py":"Wǒmen yào bu yào mǎi jǐ ge xīn de yǐzi?","vi":"Chúng ta có cần mua mấy chiếc ghế mới không?"}},{"stt":10,"hanzi":"新","pinyin":"xīn","hanviet":"Tân","pos":"Tính từ","meaning":"Mới","comps":"新的 · 新椅子 · 新衣服","example":{"zh":"我要去买几个新的椅子。","py":"Wǒ yào qù mǎi jǐ ge xīn de yǐzi.","vi":"Mình muốn đi mua mấy chiếc ghế mới."}},{"stt":11,"hanzi":"它","pinyin":"tā","hanviet":"Tha","pos":"Đại từ","meaning":"Nó (chỉ vật, con vật)","comps":"它的 · 它叫…… · 它很漂亮","example":{"zh":"它很漂亮。","py":"Tā hěn piàoliang.","vi":"Nó rất đẹp."}},{"stt":12,"hanzi":"眼睛","pinyin":"yǎnjing","hanviet":"Nhãn tình","pos":"Danh từ","meaning":"Mắt","comps":"眼睛大 · 眼睛漂亮 · 它的眼睛","example":{"zh":"我觉得它的眼睛最漂亮。","py":"Wǒ juéde tā de yǎnjing zuì piàoliang.","vi":"Mình thấy đôi mắt của nó đẹp nhất."}},{"stt":13,"hanzi":"花花","pinyin":"Huāhua","hanviet":"Hoa Hoa","pos":"Danh từ riêng","meaning":"Hoa Hoa (tên con mèo)","comps":"它叫花花 · 花花在哪儿 · 花花多大了","example":{"zh":"那是我的猫，它叫花花。","py":"Nà shì wǒ de māo, tā jiào Huāhua.","vi":"Đó là con mèo của mình, nó tên là Hoa Hoa."}}],"hanzi":[{"char":"旅游","pinyin":"lǚyóu","hanviet":"Lữ du","chars":["旅","游"],"story":"旅 (đi xa) + 游 (bộ 氵 nước, rong chơi). Đi xa rong chơi = du lịch."},{"char":"觉得","pinyin":"juéde","hanviet":"Giác đắc","chars":["觉","得"],"story":"觉 (cảm giác) + 得 (đạt được). Trong lòng cảm thấy, nghĩ ra điều gì."},{"char":"最","pinyin":"zuì","hanviet":"Tối","chars":["最"],"story":"Bộ 曰 (nói) trên 取 (lấy). Phó từ chỉ mức độ cao nhất."},{"char":"为什么","pinyin":"wèi shénme","hanviet":"Vị thập ma","chars":["为","什","么"],"story":"为 (vì) + 什么 (cái gì) → hỏi “vì cái gì” = tại sao."},{"char":"也","pinyin":"yě","hanviet":"Dã","chars":["也"],"story":"也 hình dạng giống con rắn đầu nhọn mình dài; nay dùng làm phó từ “cũng”."},{"char":"运动","pinyin":"yùndòng","hanviet":"Vận động","chars":["运","动"],"story":"运 (vận chuyển) + 动 (chuyển động). Cơ thể chuyển động = vận động."},{"char":"踢足球","pinyin":"tī zúqiú","hanviet":"Thích túc cầu","chars":["踢","足","球"],"story":"踢 (bộ 足 chân, đá) + 足球 (quả bóng đá). Dùng chân đá bóng."},{"char":"一起","pinyin":"yìqǐ","hanviet":"Nhất khởi","chars":["一","起"],"story":"一 (một) + 起 (cùng dậy, cùng bắt đầu). Cùng nhau làm một việc."},{"char":"要","pinyin":"yào","hanviet":"Yếu","chars":["要"],"story":"Đặt trước động từ để nói lên nguyện vọng; phủ định thường dùng 不想."},{"char":"新","pinyin":"xīn","hanviet":"Tân","chars":["新"],"story":"Bên trái là 亲, bên phải bộ 斤 (rìu). Dùng rìu đẽo cây → cái mới."},{"char":"它","pinyin":"tā","hanviet":"Tha","chars":["它"],"story":"Bộ 宀 (mái nhà) trên 匕. Đại từ ngôi thứ ba chỉ đồ vật, con vật."},{"char":"眼睛","pinyin":"yǎnjing","hanviet":"Nhãn tình","chars":["眼","睛"],"story":"眼 (bộ 目 mắt) + 睛 (con ngươi). Hai chữ đều có bộ 目 → mắt."},{"char":"花花","pinyin":"Huāhua","hanviet":"Hoa Hoa","chars":["花","花"],"story":"花 (hoa) lặp lại hai lần thành tên gọi thân mật cho thú cưng."}],"grammar":[{"title":"Trợ động từ 要 (muốn / cần)","formula":"S + <span>要</span> + V + (O)   ·   phủ định: S + <span>不想</span> + V","summary":"要 đặt <b>trước động từ</b> để cho biết chủ ngữ có nguyện vọng, ý định làm việc gì đó. Khi nói về nguyện vọng, dạng phủ định thường <b>không</b> dùng 不要 mà dùng <b>不想</b> (không muốn).","note":"<strong>Lưu ý:</strong> Phủ định nguyện vọng của 要 là <b>不想</b>, không nói “不要 + V”. Dạng nghi vấn hay dùng <b>要不要</b> hoặc thêm <b>吗</b>.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Phó từ chỉ mức độ 最","formula":"S + <span>最</span> + Adj / V (喜欢…)","summary":"最 chỉ vị trí <b>cao nhất, đứng đầu</b> trong các sự vật cùng loại hoặc xét về một khía cạnh nào đó. 最 luôn đặt <b>trước</b> tính từ hoặc động từ tâm lý (喜欢, 觉得…). Dạng phủ định thường dùng “不是……最……的”.","note":"<strong>Lưu ý:</strong> 最 đứng <b>trước</b> tính từ/động từ, tuyệt đối không đặt cuối câu như chữ “nhất” trong tiếng Việt.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Số ước lượng: 几 và 多","formula":"几 + <span>量词</span> + 名词   ·   số + <span>多</span> (hơn…)","summary":"<b>几</b> chỉ con số không xác định nhỏ hơn 10 và <b>phải</b> kèm lượng từ phía sau (几 + lượng từ + danh từ). <b>多</b> kết hợp với số lượng để chỉ con số “dư, hơn”: số nhỏ hơn 10 thì 多 đứng sau lượng từ (六个多月), số chục tròn thì 多 đứng trước lượng từ (二十多块).","note":"<strong>Lưu ý:</strong> Sau 几 luôn phải có lượng từ. 几 hỏi/chỉ số nguyên; 多 chỉ phần lẻ dôi ra của một con số.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在学校","titleVi":"Ở trường","icon":"🏫","lines":[{"speaker":"A","zh":"我要去北京旅游，你觉得什么时候去最好？","py":"Wǒ yào qù Běijīng lǚyóu, nǐ juéde shénme shíhou qù zuì hǎo?","vi":"Mình sẽ đi Bắc Kinh du lịch, bạn thấy đi vào lúc nào là tốt nhất?"},{"speaker":"B","zh":"九月去北京旅游最好。","py":"Jiǔ yuè qù Běijīng lǚyóu zuì hǎo.","vi":"Tháng 9 đi Bắc Kinh du lịch là tốt nhất."},{"speaker":"A","zh":"为什么？","py":"Wèi shénme?","vi":"Tại sao vậy?"},{"speaker":"B","zh":"九月的北京天气不冷也不热。","py":"Jiǔ yuè de Běijīng tiānqì bù lěng yě bú rè.","vi":"Bắc Kinh tháng 9 thời tiết không lạnh cũng không nóng."}]},{"titleZh":"看照片","titleVi":"Xem ảnh","icon":"📷","lines":[{"speaker":"A","zh":"你喜欢什么运动？","py":"Nǐ xǐhuan shénme yùndòng?","vi":"Bạn thích môn thể thao nào?"},{"speaker":"B","zh":"我最喜欢踢足球。","py":"Wǒ zuì xǐhuan tī zúqiú.","vi":"Mình thích đá bóng nhất."},{"speaker":"A","zh":"下午我们一起去踢足球吧。","py":"Xiàwǔ wǒmen yìqǐ qù tī zúqiú ba.","vi":"Chiều nay chúng ta cùng đi đá bóng nhé."},{"speaker":"B","zh":"好啊！","py":"Hǎo a!","vi":"Được đấy!"}]},{"titleZh":"在家里","titleVi":"Ở nhà","icon":"🪑","lines":[{"speaker":"A","zh":"我们要不要买几个新的椅子？","py":"Wǒmen yào bu yào mǎi jǐ ge xīn de yǐzi?","vi":"Chúng ta có cần mua mấy chiếc ghế mới không?"},{"speaker":"B","zh":"好啊。什么时候去买？","py":"Hǎo a. Shénme shíhou qù mǎi?","vi":"Được thôi. Khi nào đi mua?"},{"speaker":"A","zh":"明天下午怎么样？你明天几点能回来？","py":"Míngtiān xiàwǔ zěnmeyàng? Nǐ míngtiān jǐ diǎn néng huílai?","vi":"Chiều mai được không? Ngày mai mấy giờ bạn về được?"},{"speaker":"B","zh":"三点多。","py":"Sān diǎn duō.","vi":"Hơn 3 giờ."}]},{"titleZh":"在家里","titleVi":"Ở nhà","icon":"🐱","lines":[{"speaker":"A","zh":"桌子下面有个猫。","py":"Zhuōzi xiàmiàn yǒu ge māo.","vi":"Ở dưới bàn có con mèo kìa."},{"speaker":"B","zh":"那是我的猫，它叫花花。","py":"Nà shì wǒ de māo, tā jiào Huāhua.","vi":"Đó là con mèo của mình, nó tên là Hoa Hoa."},{"speaker":"A","zh":"它很漂亮。","py":"Tā hěn piàoliang.","vi":"Nó đẹp quá."},{"speaker":"B","zh":"是啊，我觉得它的眼睛最漂亮。","py":"Shì a, wǒ juéde tā de yǎnjing zuì piàoliang.","vi":"Đúng vậy, mình thấy đôi mắt của nó đẹp nhất."},{"speaker":"A","zh":"它多大了？","py":"Tā duō dà le?","vi":"Nó được bao nhiêu tuổi rồi?"},{"speaker":"B","zh":"六个多月。","py":"Liù ge duō yuè.","vi":"Hơn 6 tháng."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Sau bài 1, học viên biết <em>hỏi đáp về sở thích, thời gian, nơi du lịch</em>, biết bày tỏ nguyện vọng và so sánh ở mức cao nhất, đồng thời nắm chắc 13 từ vựng và 3 điểm ngữ pháp trọng tâm.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi & nói thời điểm tốt nhất để làm việc gì: <b>什么时候……最好？</b></li>\n        <li>Hỏi đáp về sở thích, môn thể thao: <b>你最喜欢什么运动？</b></li>\n        <li>Hỏi lý do và miêu tả: <b>为什么？</b> · <b>它的眼睛最漂亮。</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>13 từ trọng tâm</li>\n        <li>Hoạt động: <b>旅游 · 运动 · 踢足球</b></li>\n        <li>Cảm nghĩ & mức độ: <b>觉得 · 最 · 也 · 为什么</b></li>\n        <li>Đồ vật & miêu tả: <b>要 · 新 · 它 · 眼睛</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Trợ động từ <b>要</b> (nguyện vọng), phủ định <b>不想</b></li>\n        <li>Phó từ chỉ mức độ <b>最</b></li>\n        <li>Số ước lượng <b>几</b> và <b>多</b></li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm: Số ước lượng 几 và 多</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Điểm đặc thù của bài 1 là <em>cách diễn tả số không xác định</em>: dùng <em>几</em> cho con số ước chừng (kèm lượng từ) và <em>多</em> để chỉ con số “dư, hơn”. Bên dưới là bảng tổng hợp, công thức và lỗi thường gặp.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học bài 1, liên quan đến <em>要 / 不想</em>, vị trí của <em>最 · 也</em> và lượng từ sau <em>几</em>.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Phủ định của 要</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">要 (muốn/cần) <b>không</b> phủ định bằng 不要 khi nói về nguyện vọng. Phủ định thường dùng <b>不想</b>.</p>\n        <p class=\"strike zh\">我不要去旅游。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我不想去旅游。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Vị trí của 最</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">最 phải đứng <b>trước</b> động từ / tính từ, không đặt sau như tiếng Việt “nhất”.</p>\n        <p class=\"strike zh\">我喜欢踢足球最。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我最喜欢踢足球。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Vị trí của 也</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">也 (cũng) đứng <b>trước</b> động từ/tính từ và sau chủ ngữ, không đặt ở cuối câu.</p>\n        <p class=\"strike zh\">九月的北京不冷不热也。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">九月的北京不冷也不热。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 4 · 几 thiếu lượng từ</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Sau 几 bắt buộc phải có <b>lượng từ</b> rồi mới đến danh từ.</p>\n        <p class=\"strike zh\">我想买几书。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我想买几本书。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn gom toàn bộ bài 1 theo cách dễ nhớ: từ chủ đề, cấu trúc vàng, mẫu câu thần chú đến cách chia nhóm từ vựng.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Hỏi đáp về sở thích, du lịch và thời điểm tốt nhất để làm việc gì đó.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Hỏi<br><span class=\"syn-keyhz\">什么时候？</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">So sánh<br><span class=\"syn-keyhz\">最好</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Lý do<br><span class=\"syn-keyhz\">为什么？</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> “Muốn đi đâu (要去哪儿) → lúc nào tốt nhất (什么时候最好) → tại sao (为什么)”.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">最 + Adj/V</span></h3>\n      <p>Đặt 最 ngay trước tính từ hoặc động từ tâm lý để chỉ mức cao nhất.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">S<br><small>我</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">最<br><small>zuì</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Adj/V<br><small>喜欢…</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> 最 luôn đứng <strong>trước</strong>, không bao giờ đặt cuối câu.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">什么时候去最好？</span></td><td>Hỏi thời điểm tốt nhất</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你最喜欢什么运动？</span></td><td>Hỏi sở thích</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我们要不要买…？</span></td><td>Rủ rê, đề nghị</td></tr>\n        <tr><td><span class=\"syn-keyhz\">它多大了？</span></td><td>Hỏi tuổi (con vật)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Hoạt động</td><td><span class=\"syn-keyhz\">旅游 · 运动 · 踢足球 · 一起</span></td></tr>\n        <tr><td>Cảm nghĩ & mức độ</td><td><span class=\"syn-keyhz\">觉得 · 最 · 也 · 为什么</span></td></tr>\n        <tr><td>Đồ vật & miêu tả</td><td><span class=\"syn-keyhz\">要 · 新 · 它 · 眼睛</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> “Mình <strong>muốn (要)</strong> rủ bạn <strong>cùng (一起)</strong> đi <strong>du lịch (旅游)</strong>, vì mình <strong>cho rằng (觉得)</strong> tháng 9 đẹp <strong>nhất (最)</strong>.”</div>\n    </div>\n  </div>"}],"cssId":"ce27c2e94"},{"id":"k2v2-b02","courseId":"k2v2","order":2,"title":"Hàng ngày tôi thức dậy lúc 6 giờ","titleZh":"我每天六点起床","vocab":[{"stt":1,"hanzi":"生病","pinyin":"shēng bìng","hanviet":"Sinh bệnh","pos":"Động từ","meaning":"Bị bệnh, bị ốm","comps":"生病了 · 很少生病 · 不生病","example":{"zh":"你很少生病，是不是喜欢运动？","py":"Nǐ hěn shǎo shēng bìng, shì bu shì xǐhuan yùndòng?","vi":"Bạn ít khi bị ốm, chắc là thích vận động phải không?"}},{"stt":2,"hanzi":"每","pinyin":"měi","hanviet":"Mỗi","pos":"Đại từ","meaning":"Mỗi, mọi","comps":"每天 · 每年 · 每个星期","example":{"zh":"我每天六点起床。","py":"Wǒ měi tiān liù diǎn qǐ chuáng.","vi":"Hàng ngày tôi thức dậy lúc 6 giờ."}},{"stt":3,"hanzi":"早上","pinyin":"zǎoshang","hanviet":"Tảo thượng","pos":"Danh từ","meaning":"Buổi sáng","comps":"早上好 · 每天早上 · 早上跑步","example":{"zh":"我每天早上都要出去跑步。","py":"Wǒ měi tiān zǎoshang dōu yào chūqu pǎo bù.","vi":"Mỗi buổi sáng tôi đều ra ngoài chạy bộ."}},{"stt":4,"hanzi":"跑步","pinyin":"pǎo bù","hanviet":"Bào bộ","pos":"Động từ","meaning":"Chạy bộ","comps":"去跑步 · 早上跑步 · 喜欢跑步","example":{"zh":"我每天早上都去跑步。","py":"Wǒ měi tiān zǎoshang dōu qù pǎo bù.","vi":"Sáng nào tôi cũng đi chạy bộ."}},{"stt":5,"hanzi":"起床","pinyin":"qǐ chuáng","hanviet":"Khởi sàng","pos":"Động từ","meaning":"Thức dậy, ngủ dậy","comps":"几点起床 · 早起床 · 起床了","example":{"zh":"你每天几点起床？","py":"Nǐ měi tiān jǐ diǎn qǐ chuáng?","vi":"Hàng ngày bạn thức dậy lúc mấy giờ?"}},{"stt":6,"hanzi":"药","pinyin":"yào","hanviet":"Dược","pos":"Danh từ","meaning":"Thuốc","comps":"吃药 · 买药 · 中药","example":{"zh":"吃药了吗？现在身体怎么样？","py":"Chī yào le ma? Xiànzài shēntǐ zěnmeyàng?","vi":"Uống thuốc chưa? Bây giờ sức khỏe thế nào?"}},{"stt":7,"hanzi":"身体","pinyin":"shēntǐ","hanviet":"Thân thể","pos":"Danh từ","meaning":"Sức khỏe, cơ thể","comps":"身体好 · 身体怎么样 · 身体不好","example":{"zh":"现在好多了。","py":"Xiànzài hǎo duō le.","vi":"Giờ thì khỏe hơn nhiều rồi."}},{"stt":8,"hanzi":"出院","pinyin":"chū yuàn","hanviet":"Xuất viện","pos":"Động từ","meaning":"Xuất viện, ra viện","comps":"什么时候出院 · 能出院 · 出院了","example":{"zh":"什么时候能出院？","py":"Shénme shíhou néng chū yuàn?","vi":"Khi nào có thể xuất viện?"}},{"stt":9,"hanzi":"出","pinyin":"chū","hanviet":"Xuất","pos":"Động từ","meaning":"Ra, ra ngoài","comps":"出去 · 出来 · 出院","example":{"zh":"我每天早上都要出去跑步。","py":"Wǒ měi tiān zǎoshang dōu yào chūqu pǎo bù.","vi":"Sáng nào tôi cũng phải ra ngoài chạy bộ."}},{"stt":10,"hanzi":"高","pinyin":"gāo","hanviet":"Cao","pos":"Tính từ","meaning":"Cao","comps":"多高 · 很高 · 高个子","example":{"zh":"他多高？","py":"Tā duō gāo?","vi":"Anh ấy cao bao nhiêu?"}},{"stt":11,"hanzi":"米","pinyin":"mǐ","hanviet":"Mễ","pos":"Lượng từ","meaning":"Mét (đơn vị đo)","comps":"一米八 · 一米七 · 多少米","example":{"zh":"一米八几。","py":"Yì mǐ bā jǐ.","vi":"Một mét tám mấy."}},{"stt":12,"hanzi":"知道","pinyin":"zhīdào","hanviet":"Tri đạo","pos":"Động từ","meaning":"Biết","comps":"我知道 · 不知道 · 你怎么知道","example":{"zh":"你怎么知道这么多啊？","py":"Nǐ zěnme zhīdào zhème duō a?","vi":"Sao bạn biết nhiều như vậy?"}},{"stt":13,"hanzi":"休息","pinyin":"xiūxi","hanviet":"Hưu tức","pos":"Động từ","meaning":"Nghỉ ngơi","comps":"休息一下 · 没时间休息 · 在家休息","example":{"zh":"他这几天很忙，没有时间休息。","py":"Tā zhè jǐ tiān hěn máng, méiyǒu shíjiān xiūxi.","vi":"Mấy ngày nay anh ấy rất bận, không có thời gian nghỉ ngơi."}},{"stt":14,"hanzi":"忙","pinyin":"máng","hanviet":"Mang","pos":"Tính từ","meaning":"Bận, bận rộn","comps":"很忙 · 忙不忙 · 这几天很忙","example":{"zh":"他这几天很忙。","py":"Tā zhè jǐ tiān hěn máng.","vi":"Mấy hôm nay anh ấy rất bận."}},{"stt":15,"hanzi":"时间","pinyin":"shíjiān","hanviet":"Thời gian","pos":"Danh từ","meaning":"Thời gian","comps":"没有时间 · 有时间 · 时间到了","example":{"zh":"他没有时间休息。","py":"Tā méiyǒu shíjiān xiūxi.","vi":"Anh ấy không có thời gian nghỉ ngơi."}}],"hanzi":[{"char":"生病","pinyin":"shēng bìng","hanviet":"Sinh bệnh","chars":["生","病"],"story":"生 (sinh ra) + 病 (bệnh, bộ 疒 ốm đau). Sinh ra bệnh = bị ốm."},{"char":"每","pinyin":"měi","hanviet":"Mỗi","chars":["每"],"story":"每 nghĩa là “mỗi”; sau 每 phải có lượng từ rồi đến danh từ."},{"char":"早上","pinyin":"zǎoshang","hanviet":"Tảo thượng","chars":["早","上"],"story":"早 (sớm) + 上 (lúc). Khoảng thời gian sớm trong ngày = buổi sáng."},{"char":"跑步","pinyin":"pǎo bù","hanviet":"Bào bộ","chars":["跑","步"],"story":"跑 (bộ 足 chân, chạy) + 步 (bước đi). Chạy từng bước = chạy bộ."},{"char":"起床","pinyin":"qǐ chuáng","hanviet":"Khởi sàng","chars":["起","床"],"story":"起 (đứng dậy) + 床 (giường). Rời khỏi giường = thức dậy."},{"char":"药","pinyin":"yào","hanviet":"Dược","chars":["药"],"story":"Bộ 艹 (cỏ) trên 约. Ngày xưa thuốc làm từ cây cỏ."},{"char":"身体","pinyin":"shēntǐ","hanviet":"Thân thể","chars":["身","体"],"story":"身 (thân mình) + 体 (thân thể, bộ 亻người). Thân thể = cơ thể, sức khỏe."},{"char":"出院","pinyin":"chū yuàn","hanviet":"Xuất viện","chars":["出","院"],"story":"出 (ra) + 院 (bệnh viện, 医院). Ra khỏi bệnh viện = xuất viện."},{"char":"出","pinyin":"chū","hanviet":"Xuất","chars":["出"],"story":"Chữ 出 giống hai ngọn núi chồng lên nhau, ý đi “ra” khỏi nơi nào đó."},{"char":"高","pinyin":"gāo","hanviet":"Cao","chars":["高"],"story":"Chữ 高 giống một tòa lầu gác cao, mang nghĩa “cao”."},{"char":"米","pinyin":"mǐ","hanviet":"Mễ","chars":["米"],"story":"米 vốn là hạt gạo; ở đây mượn làm đơn vị đo chiều dài “mét”."},{"char":"知道","pinyin":"zhīdào","hanviet":"Tri đạo","chars":["知","道"],"story":"知 (biết) + 道 (đạo lý, đường). Biết được đường đi, lẽ phải = biết."},{"char":"休息","pinyin":"xiūxi","hanviet":"Hưu tức","chars":["休","息"],"story":"休 (人 người dựa vào 木 cây) + 息 (nghỉ thở). Người dựa cây nghỉ ngơi."},{"char":"忙","pinyin":"máng","hanviet":"Mang","chars":["忙"],"story":"Bộ 忄 (tâm) + 亡. Trong lòng rối bời vì nhiều việc = bận."},{"char":"时间","pinyin":"shíjiān","hanviet":"Thời gian","chars":["时","间"],"story":"时 (giờ, thời) + 间 (khoảng giữa). Khoảng giữa các thời điểm = thời gian."}],"grammar":[{"title":"Câu hỏi xác nhận 是不是","formula":"S + <span>是不是</span> + vị ngữ？  (hoặc: 是不是…？ / …，是不是？)","summary":"Khi người hỏi đã <b>phỏng đoán khá chắc</b> về một sự việc và muốn xác nhận lại, ta dùng <b>是不是</b>. 是不是 thường đặt <b>trước vị ngữ</b>, cũng có thể đứng ở <b>đầu</b> hoặc <b>cuối</b> câu. Cột “Nghi vấn” dưới đây là câu hỏi 是不是; hai cột còn lại là câu trả lời.","note":"<strong>Lưu ý:</strong> Câu đã có 是不是 thì <b>không</b> thêm 吗 ở cuối. Trả lời khẳng định: 是 / 是的; phủ định: 不是.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Đại từ 每 (mỗi)","formula":"每 + (量词) + 名词 + <span>都</span> + V","summary":"每 dùng <b>trước lượng từ</b> để chỉ bất kỳ cá thể hay một nhóm nào trong tổng thể: 每天 (mỗi ngày), 每年 (mỗi năm), 每个月 (mỗi tháng), 每个星期 (mỗi tuần). 每 thường đi kèm phó từ <b>都</b> ở phía sau.","note":"<strong>Lưu ý:</strong> 每天 · 每年 <b>không</b> thêm 个; còn 每个月 · 每个星期 thì <b>phải</b> có 个.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Đại từ nghi vấn 多 (hỏi mức độ)","formula":"S + <span>多</span> + Adj？  →  trả lời: số + 岁 / 米","summary":"多 đặt <b>trước tính từ</b> để hỏi về mức độ, hay gặp nhất là <b>多大</b> (bao nhiêu tuổi) và <b>多高</b> (cao bao nhiêu). Khi trả lời <b>phải nêu con số cụ thể</b>. Cột “Nghi vấn” là câu hỏi với 多; hai cột còn lại là câu trả lời.","note":"<strong>Lưu ý:</strong> Trả lời câu hỏi 多大/多高 bằng <b>con số</b> (岁, 米), không trả lời 很大/很高.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在运动场","titleVi":"Ở sân vận động","icon":"🏃","lines":[{"speaker":"A","zh":"你很少生病，是不是喜欢运动？","py":"Nǐ hěn shǎo shēng bìng, shì bu shì xǐhuan yùndòng?","vi":"Bạn ít khi bị bệnh, chắc là thích vận động phải không?"},{"speaker":"B","zh":"是啊，我每天早上都要出去跑步。","py":"Shì a, wǒ měi tiān zǎoshang dōu yào chūqu pǎo bù.","vi":"Đúng vậy. Mỗi buổi sáng mình đều ra ngoài chạy bộ."},{"speaker":"A","zh":"你每天几点起床？","py":"Nǐ měi tiān jǐ diǎn qǐ chuáng?","vi":"Hàng ngày bạn thức dậy lúc mấy giờ?"},{"speaker":"B","zh":"我每天六点起床。","py":"Wǒ měi tiān liù diǎn qǐ chuáng.","vi":"Hàng ngày mình dậy lúc 6 giờ."}]},{"titleZh":"在医院","titleVi":"Trong bệnh viện","icon":"🏥","lines":[{"speaker":"A","zh":"吃药了吗？现在身体怎么样？","py":"Chī yào le ma? Xiànzài shēntǐ zěnmeyàng?","vi":"Uống thuốc chưa? Bây giờ sức khỏe thế nào?"},{"speaker":"B","zh":"吃了。现在好多了。","py":"Chī le. Xiànzài hǎo duō le.","vi":"Uống rồi. Giờ thì khỏe hơn nhiều rồi."},{"speaker":"A","zh":"什么时候能出院？","py":"Shénme shíhou néng chū yuàn?","vi":"Khi nào có thể xuất viện?"},{"speaker":"B","zh":"医生说下个星期。","py":"Yīshēng shuō xià ge xīngqī.","vi":"Bác sĩ nói là tuần sau."}]},{"titleZh":"在操场","titleVi":"Ở sân thể thao","icon":"🏀","lines":[{"speaker":"A","zh":"大卫今年多大？","py":"Dàwèi jīnnián duō dà?","vi":"Năm nay David bao nhiêu tuổi?"},{"speaker":"B","zh":"二十多岁。","py":"Èrshí duō suì.","vi":"Hơn 20 tuổi."},{"speaker":"A","zh":"他多高？","py":"Tā duō gāo?","vi":"Anh ấy cao bao nhiêu?"},{"speaker":"B","zh":"一米八几。","py":"Yì mǐ bā jǐ.","vi":"Trên một mét tám."},{"speaker":"A","zh":"你怎么知道这么多啊？","py":"Nǐ zěnme zhīdào zhème duō a?","vi":"Sao bạn biết nhiều như vậy?"},{"speaker":"B","zh":"他是我同学。","py":"Tā shì wǒ tóngxué.","vi":"Anh ấy học cùng lớp với mình mà."}]},{"titleZh":"在房间","titleVi":"Trong phòng","icon":"🛏️","lines":[{"speaker":"A","zh":"张老师星期六也不休息啊？","py":"Zhāng lǎoshī xīngqīliù yě bù xiūxi a?","vi":"Thứ Bảy mà thầy Trương cũng không nghỉ à?"},{"speaker":"B","zh":"是啊，他这几天很忙，没有时间休息。","py":"Shì a, tā zhè jǐ tiān hěn máng, méiyǒu shíjiān xiūxi.","vi":"Đúng vậy, mấy hôm nay thầy rất bận, không có thời gian nghỉ ngơi."},{"speaker":"A","zh":"那会很累吧？","py":"Nà huì hěn lèi ba?","vi":"Vậy chắc là mệt lắm nhỉ?"},{"speaker":"B","zh":"他每天回来都很累。","py":"Tā měi tiān huílai dōu hěn lèi.","vi":"Ngày nào về nhà thầy cũng rất mệt."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Sau bài 2, học viên biết <em>kể lịch sinh hoạt một ngày, hỏi về sức khỏe, tuổi và chiều cao</em>, biết hỏi xác nhận, đồng thời nắm chắc 15 từ vựng và 3 điểm ngữ pháp trọng tâm.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Kể thói quen hằng ngày: <b>我每天六点起床。</b></li>\n        <li>Hỏi sức khỏe & bệnh tật: <b>身体怎么样？吃药了吗？</b></li>\n        <li>Hỏi tuổi & chiều cao: <b>你多大？他多高？</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>15 từ trọng tâm</li>\n        <li>Sinh hoạt: <b>起床 · 早上 · 跑步 · 休息</b></li>\n        <li>Sức khỏe: <b>生病 · 药 · 身体 · 出院</b></li>\n        <li>Miêu tả: <b>高 · 米 · 忙 · 时间 · 知道</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Câu hỏi xác nhận <b>是不是</b></li>\n        <li>Đại từ <b>每</b> (mỗi) + 都</li>\n        <li>Đại từ nghi vấn <b>多</b> (多大 · 多高)</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm: Hỏi tuổi/chiều cao & thời gian biểu</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Hai kỹ năng ứng dụng nổi bật của bài 2: <em>hỏi tuổi và chiều cao</em> bằng 多大 · 多高 (trả lời bằng 岁 · 米), và <em>kể lịch sinh hoạt một ngày</em> với 每天 + thời điểm + 点 + động từ.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học bài 2, liên quan đến vị trí thời gian, câu hỏi <em>是不是</em>, đại từ <em>每</em> và cách hỏi <em>多</em>.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Vị trí của thời gian</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Từ chỉ thời gian (六点, 早上…) phải đứng <b>trước</b> động từ, không đặt sau như tiếng Việt.</p>\n        <p class=\"strike zh\">我每天起床六点。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我每天六点起床。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · 是不是 + 吗</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Câu đã có <b>是不是</b> thì <b>không</b> thêm 吗 ở cuối nữa.</p>\n        <p class=\"strike zh\">你是不是喜欢运动吗？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">你是不是喜欢运动？</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · 每 thiếu lượng từ</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">每个月 · 每个星期 cần có <b>个</b>; còn 每天 · 每年 thì không thêm 个.</p>\n        <p class=\"strike zh\">我每月去看他。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我每个月去看他。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 4 · Trả lời 多高/多大</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Hỏi bằng <b>多高/多大</b> thì phải trả lời bằng <b>con số cụ thể</b> (米, 岁), không trả lời 很高/很大.</p>\n        <p class=\"strike zh\">A：他多高？B：他很高。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">A：他多高？B：他一米八。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn gom toàn bộ bài 2 theo cách dễ nhớ: từ chủ đề, cấu trúc vàng, mẫu câu thần chú đến cách chia nhóm từ vựng.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Kể lịch sinh hoạt một ngày, hỏi đáp về sức khỏe, tuổi tác và chiều cao.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Thói quen<br><span class=\"syn-keyhz\">每天…起床</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Sức khỏe<br><span class=\"syn-keyhz\">身体怎么样</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Tuổi/cao<br><span class=\"syn-keyhz\">多大 · 多高</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> “Mỗi ngày làm gì (每天) → khỏe không (身体) → bao nhiêu tuổi, cao bao nhiêu (多大/多高)”.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">每天 + giờ + V</span></h3>\n      <p>Đặt thời điểm (mấy giờ, buổi nào) ngay trước động từ để kể thói quen.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">每天<br><small>měi tiān</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">六点<br><small>liù diǎn</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">起床<br><small>qǐ chuáng</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> Thời gian luôn đứng <strong>trước</strong> động từ, không đặt sau.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">你每天几点起床？</span></td><td>Hỏi thói quen</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你是不是喜欢运动？</span></td><td>Hỏi xác nhận</td></tr>\n        <tr><td><span class=\"syn-keyhz\">现在身体怎么样？</span></td><td>Hỏi sức khỏe</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你多大？他多高？</span></td><td>Hỏi tuổi/chiều cao</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Sinh hoạt</td><td><span class=\"syn-keyhz\">起床 · 早上 · 跑步 · 休息</span></td></tr>\n        <tr><td>Sức khỏe</td><td><span class=\"syn-keyhz\">生病 · 药 · 身体 · 出院 · 出</span></td></tr>\n        <tr><td>Miêu tả</td><td><span class=\"syn-keyhz\">高 · 米 · 忙 · 时间 · 知道 · 每</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> “<strong>Mỗi ngày (每天)</strong> dậy sớm <strong>(起床)</strong>, đi <strong>chạy bộ (跑步)</strong> nên ít <strong>bị bệnh (生病)</strong>, <strong>cơ thể (身体)</strong> khỏe; ai bận <strong>(忙)</strong> quá, không có <strong>thời gian (时间)</strong> nghỉ thì dễ ốm.”</div>\n    </div>\n  </div>"}],"cssId":"ce27c2e94"},{"id":"k2v2-b03","courseId":"k2v2","order":3,"title":"Cái màu đỏ ở bên trái là của tôi","titleZh":"左边那个红色的是我的","vocab":[{"stt":1,"hanzi":"手表","pinyin":"shǒubiǎo","hanviet":"Thủ biểu","pos":"Danh từ","meaning":"Đồng hồ đeo tay","comps":"这块手表 · 买手表 · 我的手表","example":{"zh":"这块手表是你的吗？","py":"Zhè kuài shǒubiǎo shì nǐ de ma?","vi":"Chiếc đồng hồ đeo tay này là của bạn phải không?"}},{"stt":2,"hanzi":"千","pinyin":"qiān","hanviet":"Thiên","pos":"Số từ","meaning":"Nghìn","comps":"三千 · 一千块 · 两千","example":{"zh":"三千多块。","py":"Sānqiān duō kuài.","vi":"Hơn ba nghìn tệ."}},{"stt":3,"hanzi":"报纸","pinyin":"bàozhǐ","hanviet":"Báo chỉ","pos":"Danh từ","meaning":"Báo, tờ báo","comps":"看报纸 · 今天的报纸 · 送报纸","example":{"zh":"这是今天早上的报纸吗？","py":"Zhè shì jīntiān zǎoshang de bàozhǐ ma?","vi":"Đây là báo ra sáng nay phải không?"}},{"stt":4,"hanzi":"送","pinyin":"sòng","hanviet":"Tống","pos":"Động từ","meaning":"Giao, đưa, tặng","comps":"送报纸 · 送牛奶 · 送你","example":{"zh":"是不是送报纸的来了？","py":"Shì bu shì sòng bàozhǐ de lái le?","vi":"Có phải người giao báo đến rồi không?"}},{"stt":5,"hanzi":"一下","pinyin":"yíxià","hanviet":"Nhất hạ","pos":"Trợ từ","meaning":"(làm) một chút, một lát","comps":"看一下 · 问一下 · 休息一下","example":{"zh":"我看一下。","py":"Wǒ kàn yíxià.","vi":"Để tôi xem một chút."}},{"stt":6,"hanzi":"牛奶","pinyin":"niúnǎi","hanviet":"Ngưu nãi","pos":"Danh từ","meaning":"Sữa bò","comps":"送牛奶 · 喝牛奶 · 买牛奶","example":{"zh":"不是，是送牛奶的。","py":"Bú shì, shì sòng niúnǎi de.","vi":"Không phải, là người giao sữa bò."}},{"stt":7,"hanzi":"房间","pinyin":"fángjiān","hanviet":"Phòng gian","pos":"Danh từ","meaning":"Phòng, căn phòng","comps":"我的房间 · 这个房间 · 房间很大","example":{"zh":"这是谁的房间？","py":"Zhè shì shéi de fángjiān?","vi":"Đây là phòng của ai?"}},{"stt":8,"hanzi":"丈夫","pinyin":"zhàngfu","hanviet":"Trượng phu","pos":"Danh từ","meaning":"Chồng","comps":"我丈夫 · 她的丈夫 · 好丈夫","example":{"zh":"这是我和我丈夫的房间。","py":"Zhè shì wǒ hé wǒ zhàngfu de fángjiān.","vi":"Đây là phòng của vợ chồng tôi."}},{"stt":9,"hanzi":"旁边","pinyin":"pángbiān","hanviet":"Bàng biên","pos":"Danh từ","meaning":"Bên cạnh","comps":"旁边那个 · 在旁边 · 我旁边","example":{"zh":"旁边那个小的房间是我女儿的。","py":"Pángbiān nàge xiǎo de fángjiān shì wǒ nǚ’ér de.","vi":"Căn phòng nhỏ bên cạnh là của con gái tôi."}},{"stt":10,"hanzi":"真","pinyin":"zhēn","hanviet":"Chân","pos":"Phó từ","meaning":"Thật, quả là","comps":"真漂亮 · 真好 · 真高","example":{"zh":"你女儿的房间真漂亮！","py":"Nǐ nǚ’ér de fángjiān zhēn piàoliang!","vi":"Phòng của con gái chị đẹp thật!"}},{"stt":11,"hanzi":"粉色","pinyin":"fěnsè","hanviet":"Phấn sắc","pos":"Danh từ","meaning":"Màu hồng (粉 fěn: có màu hồng)","comps":"粉色的 · 喜欢粉色 · 粉色房间","example":{"zh":"都是粉色的。","py":"Dōu shì fěnsè de.","vi":"Toàn là màu hồng."}},{"stt":12,"hanzi":"颜色","pinyin":"yánsè","hanviet":"Nhan sắc","pos":"Danh từ","meaning":"Màu, màu sắc","comps":"什么颜色 · 喜欢的颜色 · 这个颜色","example":{"zh":"粉色是我女儿最喜欢的颜色。","py":"Fěnsè shì wǒ nǚ’ér zuì xǐhuan de yánsè.","vi":"Màu hồng là màu con gái tôi thích nhất."}},{"stt":13,"hanzi":"左边","pinyin":"zuǒbian","hanviet":"Tả biên","pos":"Danh từ","meaning":"Bên trái","comps":"左边那个 · 在左边 · 左边的杯子","example":{"zh":"左边那个红色的是我的。","py":"Zuǒbian nàge hóngsè de shì wǒ de.","vi":"Cái màu đỏ ở bên trái là của tôi."}},{"stt":14,"hanzi":"红色","pinyin":"hóngsè","hanviet":"Hồng sắc","pos":"Danh từ","meaning":"Màu đỏ (红 hóng: có màu đỏ)","comps":"红色的 · 红色杯子 · 喜欢红色","example":{"zh":"左边那个红色的是我的。","py":"Zuǒbian nàge hóngsè de shì wǒ de.","vi":"Cái màu đỏ ở bên trái là của tôi."}}],"hanzi":[{"char":"手表","pinyin":"shǒubiǎo","hanviet":"Thủ biểu","chars":["手","表"],"story":"手 (tay) + 表 (đồng hồ). Chiếc đồng hồ đeo ở tay = đồng hồ đeo tay."},{"char":"千","pinyin":"qiān","hanviet":"Thiên","chars":["千"],"story":"千 là 十 (mười) thêm một nét phẩy trên đầu, chỉ số lớn = nghìn."},{"char":"报纸","pinyin":"bàozhǐ","hanviet":"Báo chỉ","chars":["报","纸"],"story":"报 (tin tức, báo) + 纸 (giấy, bộ 纟sợi). Tin tức in trên giấy = tờ báo."},{"char":"送","pinyin":"sòng","hanviet":"Tống","chars":["送"],"story":"Bộ 辶 (đi, bước) + 关. Mang đồ đi đưa cho người khác = giao, tặng."},{"char":"一下","pinyin":"yíxià","hanviet":"Nhất hạ","chars":["一","下"],"story":"一 (một) + 下 (lần). Đặt sau động từ, chỉ làm việc gì đó trong chốc lát."},{"char":"牛奶","pinyin":"niúnǎi","hanviet":"Ngưu nãi","chars":["牛","奶"],"story":"牛 (con bò) + 奶 (sữa). Sữa vắt từ con bò = sữa bò."},{"char":"房间","pinyin":"fángjiān","hanviet":"Phòng gian","chars":["房","间"],"story":"房 (nhà, bộ 户 cửa) + 间 (gian, khoảng). Một gian trong nhà = căn phòng."},{"char":"丈夫","pinyin":"zhàngfu","hanviet":"Trượng phu","chars":["丈","夫"],"story":"丈 (người lớn) + 夫 (đàn ông trưởng thành). Người đàn ông của gia đình = chồng."},{"char":"旁边","pinyin":"pángbiān","hanviet":"Bàng biên","chars":["旁","边"],"story":"旁 (bên) + 边 (phía, mép). Ở phía bên = bên cạnh."},{"char":"真","pinyin":"zhēn","hanviet":"Chân","chars":["真"],"story":"真 nghĩa là “thật”; đặt trước tính từ để khen ngợi, cảm thán."},{"char":"粉色","pinyin":"fěnsè","hanviet":"Phấn sắc","chars":["粉","色"],"story":"粉 (phấn, bột, bộ 米 gạo) + 色 (màu). Màu của phấn hồng = màu hồng."},{"char":"颜色","pinyin":"yánsè","hanviet":"Nhan sắc","chars":["颜","色"],"story":"颜 (sắc mặt, bộ 页 đầu/trang) + 色 (màu). Gộp lại = màu sắc."},{"char":"左边","pinyin":"zuǒbian","hanviet":"Tả biên","chars":["左","边"],"story":"左 (trái) + 边 (phía). Phía tay trái = bên trái."},{"char":"红色","pinyin":"hóngsè","hanviet":"Hồng sắc","chars":["红","色"],"story":"红 (đỏ, bộ 纟sợi tơ) + 色 (màu). Màu của tơ nhuộm đỏ = màu đỏ."}],"grammar":[{"title":"Cụm từ có 的 (的字短语)","formula":"代词 / 形容词 / 动词 + <span>的</span>  (= cụm danh từ, lược danh từ)","summary":"Đại từ, tính từ hay động từ kết hợp với <b>的</b> sẽ tạo thành một cụm mang tính chất như danh từ, trong đó <b>danh từ trung tâm được lược bỏ</b>. Ví dụ: 这本书是<b>我的</b> (= 我的书), 这个杯子是<b>昨天买的</b> (= 昨天买的杯子). Cột “Nghi vấn” là câu hỏi; hai cột còn lại là câu trả lời.","note":"<strong>Lưu ý:</strong> Có thể lược danh từ phía sau nhưng <b>không được bỏ 的</b>. Trả lời sở hữu: 是…的 / 不是…的.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Cấu trúc 动词 + 一下","formula":"动词 + <span>一下</span> (+ 宾语)","summary":"<b>一下</b> dùng <b>sau động từ</b> để diễn tả một động tác ngắn, thử làm việc gì đó trong thời gian ngắn, tương đương với dạng lặp lại động từ AA. Tân ngữ có thể được lược bỏ. Ví dụ: 我看一下 (để tôi xem một chút), 你休息一下吧 (bạn nghỉ một chút đi).","note":"<strong>Lưu ý:</strong> 一下 đứng <b>ngay sau động từ</b>, không đặt sau tân ngữ. Đúng: 看一下报纸; Sai: 看报纸一下.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Phó từ ngữ khí 真 (真 + tính từ)","formula":"真 + <span>形容词</span>！  (cảm thán)","summary":"<b>真 + tính từ</b> dùng để thể hiện cảm xúc, cảm thán; 真 có nghĩa là “đích thực, quả là”. Ví dụ: 你真好！ (bạn tốt thật!), 今天天气真好！ (hôm nay thời tiết đẹp thật!). Cột “Nghi vấn” là câu hỏi; hai cột còn lại là câu trả lời.","note":"<strong>Lưu ý:</strong> Sau 真 <b>không</b> thêm 很. Đúng: 真漂亮; Sai: 真很漂亮. Câu cảm thán thường có dấu “！”.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在房间","titleVi":"Trong phòng","icon":"⌚","lines":[{"speaker":"A","zh":"这块手表是你的吗？","py":"Zhè kuài shǒubiǎo shì nǐ de ma?","vi":"Chiếc đồng hồ đeo tay này là của anh phải không?"},{"speaker":"B","zh":"不是我的。是我爸爸的。","py":"Bú shì wǒ de. Shì wǒ bàba de.","vi":"Không phải của tôi. Là của bố tôi."},{"speaker":"A","zh":"多少钱买的？","py":"Duōshao qián mǎi de?","vi":"Mua hết bao nhiêu tiền vậy?"},{"speaker":"B","zh":"三千多块。","py":"Sānqiān duō kuài.","vi":"Hơn ba nghìn tệ."}]},{"titleZh":"在家里","titleVi":"Ở nhà","icon":"📰","lines":[{"speaker":"A","zh":"这是今天早上的报纸吗？","py":"Zhè shì jīntiān zǎoshang de bàozhǐ ma?","vi":"Đây là báo ra sáng nay phải không?"},{"speaker":"B","zh":"不是，是昨天的。","py":"Bú shì, shì zuótiān de.","vi":"Không phải, là báo hôm qua."},{"speaker":"A","zh":"你听，是不是送报纸的来了？","py":"Nǐ tīng, shì bu shì sòng bàozhǐ de lái le?","vi":"Em nghe thử xem, có phải người giao báo đến không?"},{"speaker":"B","zh":"我看一下。不是，是送牛奶的。","py":"Wǒ kàn yíxià. Bú shì, shì sòng niúnǎi de.","vi":"Để em xem nào. Không phải đâu, là người giao sữa."}]},{"titleZh":"在家里","titleVi":"Ở nhà","icon":"🏠","lines":[{"speaker":"A","zh":"这是谁的房间？","py":"Zhè shì shéi de fángjiān?","vi":"Đây là phòng của ai vậy?"},{"speaker":"B","zh":"这是我和我丈夫的，旁边那个小的房间是我女儿的。","py":"Zhè shì wǒ hé wǒ zhàngfu de, pángbiān nàge xiǎo de fángjiān shì wǒ nǚ’ér de.","vi":"Đây là phòng của vợ chồng tôi, còn căn phòng nhỏ bên cạnh là của con gái tôi."},{"speaker":"A","zh":"你女儿的房间真漂亮！都是粉色的。","py":"Nǐ nǚ’ér de fángjiān zhēn piàoliang! Dōu shì fěnsè de.","vi":"Phòng con gái chị đẹp thật! Toàn là màu hồng."},{"speaker":"B","zh":"是啊，粉色是我女儿最喜欢的颜色。","py":"Shì a, fěnsè shì wǒ nǚ’ér zuì xǐhuan de yánsè.","vi":"Đúng vậy, màu hồng là màu con gái tôi thích nhất."}]},{"titleZh":"在办公室","titleVi":"Trong văn phòng","icon":"☕","lines":[{"speaker":"A","zh":"你看见我的杯子了吗？","py":"Nǐ kànjiàn wǒ de bēizi le ma?","vi":"Anh có thấy cái cốc của tôi không?"},{"speaker":"B","zh":"这里有几个杯子，哪个是你的？","py":"Zhèlǐ yǒu jǐ ge bēizi, nǎge shì nǐ de?","vi":"Ở đây có mấy cái cốc, cái nào là của cô vậy?"},{"speaker":"A","zh":"左边那个红色的是我的。","py":"Zuǒbian nàge hóngsè de shì wǒ de.","vi":"Cái màu đỏ ở bên trái là của tôi."},{"speaker":"B","zh":"给你。","py":"Gěi nǐ.","vi":"Của cô đây."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Sau bài 3, học viên biết <em>hỏi đáp về sở hữu đồ vật, vị trí và màu sắc</em>, biết khen ngợi và hỏi giá tiền, đồng thời nắm chắc 14 từ vựng và 3 điểm ngữ pháp trọng tâm.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi đáp về sở hữu: <b>这是谁的？这是你的吗？</b></li>\n        <li>Hỏi giá & miêu tả: <b>多少钱买的？真漂亮！</b></li>\n        <li>Xác định đồ vật theo vị trí + màu: <b>左边那个红色的是我的。</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>14 từ trọng tâm</li>\n        <li>Đồ vật: <b>手表 · 报纸 · 牛奶 · 房间</b></li>\n        <li>Vị trí & màu: <b>左边 · 旁边 · 红色 · 粉色 · 颜色</b></li>\n        <li>Khác: <b>千 · 送 · 一下 · 丈夫 · 真</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Cụm từ có <b>的</b> (的字短语)</li>\n        <li>Cấu trúc <b>动词 + 一下</b></li>\n        <li>Phó từ ngữ khí <b>真</b> + tính từ</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm: Từ chỉ phương vị & màu sắc</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Ba mảng ứng dụng nổi bật của bài 3: <em>từ chỉ phương vị</em> (左边 · 右边 · 前边 · 后边 · 旁边 · 中间), <em>màu sắc</em> (红色 · 粉色 · 白色 · 黑色 · 蓝色), và cách <em>kết hợp vị trí + màu sắc + 的</em> để xác định một đồ vật.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học bài 3, liên quan đến <em>cụm từ có 的</em>, vị trí của <em>一下</em>, phó từ <em>真</em> và cách dùng từ chỉ phương vị + màu sắc.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Thiếu 的 khi nói sở hữu</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Nói sở hữu phải có <b>的</b>. Có thể lược danh từ phía sau nhưng <b>không được bỏ 的</b>.</p>\n        <p class=\"strike zh\">这块手表是我。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">这块手表是我的。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Vị trí của 一下</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\"><b>一下</b> phải đứng <b>ngay sau động từ</b>, không đặt sau tân ngữ.</p>\n        <p class=\"strike zh\">我看报纸一下。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我看一下报纸。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · 真 + 很</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Sau <b>真</b> đã là cảm thán, <b>không</b> dùng thêm 很 trước tính từ.</p>\n        <p class=\"strike zh\">你女儿的房间真很漂亮。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">你女儿的房间真漂亮！</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 4 · Thiếu 的 sau màu sắc</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khi lược danh từ trung tâm, sau màu sắc vẫn cần <b>的</b>: 红色<b>的</b> = cái màu đỏ.</p>\n        <p class=\"strike zh\">左边那个红色是我的。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">左边那个红色的是我的。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn gom toàn bộ bài 3 theo cách dễ nhớ: từ chủ đề, cấu trúc vàng, mẫu câu thần chú đến cách chia nhóm từ vựng.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Hỏi đáp về sở hữu đồ vật, xác định theo vị trí và màu sắc.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Của ai<br><span class=\"syn-keyhz\">谁的</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Màu gì<br><span class=\"syn-keyhz\">什么颜色</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Ở đâu<br><span class=\"syn-keyhz\">在哪边</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> “Của ai (谁的) → màu gì (什么颜色) → ở phía nào (哪边)”.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">phương vị + 那个 + màu + 的</span></h3>\n      <p>Ghép vị trí, từ chỉ định, màu sắc rồi thêm 的 để xác định đúng một đồ vật.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">左边<br><small>zuǒbian</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">那个<br><small>nàge</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">红色的<br><small>hóngsè de</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> Khi lược danh từ, vẫn phải giữ <strong>的</strong> ở cuối.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">这是谁的房间？</span></td><td>Hỏi sở hữu</td></tr>\n        <tr><td><span class=\"syn-keyhz\">多少钱买的？</span></td><td>Hỏi giá tiền</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你女儿的房间真漂亮！</span></td><td>Khen ngợi (真)</td></tr>\n        <tr><td><span class=\"syn-keyhz\">左边那个红色的是我的。</span></td><td>Xác định đồ vật</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Đồ vật</td><td><span class=\"syn-keyhz\">手表 · 报纸 · 牛奶 · 房间</span></td></tr>\n        <tr><td>Vị trí & màu</td><td><span class=\"syn-keyhz\">左边 · 旁边 · 红色 · 粉色 · 颜色</span></td></tr>\n        <tr><td>Khác</td><td><span class=\"syn-keyhz\">千 · 送 · 一下 · 丈夫 · 真</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> “<strong>Chồng (丈夫)</strong> đọc <strong>báo (报纸)</strong>, vợ uống <strong>sữa (牛奶)</strong>; <strong>phòng (房间)</strong> con gái toàn màu <strong>hồng (粉色)</strong>, còn cái <strong>đồng hồ (手表)</strong> màu <strong>đỏ (红色)</strong> ở <strong>bên trái (左边)</strong> là của tôi.”</div>\n    </div>\n  </div>"}],"cssId":"ce27c2e94"},{"id":"k2v2-b04","courseId":"k2v2","order":4,"title":"Ông ấy đã giới thiệu giúp tôi công việc này","titleZh":"这个工作是他帮我介绍的","vocab":[{"stt":1,"hanzi":"生日","pinyin":"shēngrì","hanviet":"Sinh nhật","pos":"Danh từ","meaning":"Sinh nhật","comps":"生日快乐 · 过生日 · 生日礼物","example":{"zh":"生日快乐！这是送给你的！","py":"Shēngrì kuàilè! Zhè shì sòng gěi nǐ de!","vi":"Chúc mừng sinh nhật! Đây là quà tặng bạn!"}},{"stt":2,"hanzi":"快乐","pinyin":"kuàilè","hanviet":"Khoái lạc","pos":"Tính từ","meaning":"Vui vẻ","comps":"生日快乐 · 快乐的一天 · 很快乐","example":{"zh":"生日快乐！","py":"Shēngrì kuàilè!","vi":"Chúc mừng sinh nhật (sinh nhật vui vẻ)!"}},{"stt":3,"hanzi":"给","pinyin":"gěi","hanviet":"Cấp","pos":"Giới từ","meaning":"Cho (dùng sau động từ)","comps":"送给你 · 给我 · 打电话给他","example":{"zh":"这是送给你的！","py":"Zhè shì sòng gěi nǐ de!","vi":"Đây là (đồ) tặng cho bạn!"}},{"stt":4,"hanzi":"接","pinyin":"jiē","hanviet":"Tiếp","pos":"Động từ","meaning":"Nhận, nghe (điện thoại)","comps":"接电话 · 接报纸 · 是谁接的","example":{"zh":"不知道，是儿子接的。","py":"Bù zhīdào, shì érzi jiē de.","vi":"Không biết nữa, là con trai nghe máy."}},{"stt":5,"hanzi":"晚上","pinyin":"wǎnshang","hanviet":"Vãn thượng","pos":"Danh từ","meaning":"Buổi tối","comps":"晚上好 · 今天晚上 · 晚上问","example":{"zh":"晚上我问一下儿子。","py":"Wǎnshang wǒ wèn yíxià érzi.","vi":"Tối nay tôi sẽ hỏi con trai một chút."}},{"stt":6,"hanzi":"问","pinyin":"wèn","hanviet":"Vấn","pos":"Động từ","meaning":"Hỏi","comps":"问一下 · 问老师 · 问问题","example":{"zh":"晚上我问一下儿子。","py":"Wǎnshang wǒ wèn yíxià érzi.","vi":"Tối nay tôi sẽ hỏi con trai một chút."}},{"stt":7,"hanzi":"非常","pinyin":"fēicháng","hanviet":"Phi thường","pos":"Phó từ","meaning":"Rất, vô cùng","comps":"非常喜欢 · 非常好 · 非常忙","example":{"zh":"非常喜欢。","py":"Fēicháng xǐhuan.","vi":"Rất thích."}},{"stt":8,"hanzi":"开始","pinyin":"kāishǐ","hanviet":"Khai thủy","pos":"Động từ","meaning":"Bắt đầu","comps":"开始工作 · 什么时候开始 · 开始上课","example":{"zh":"你是什么时候开始踢足球的？","py":"Nǐ shì shénme shíhou kāishǐ tī zúqiú de?","vi":"Bạn bắt đầu đá bóng từ khi nào vậy?"}},{"stt":9,"hanzi":"已经","pinyin":"yǐjīng","hanviet":"Dĩ kinh","pos":"Phó từ","meaning":"Đã (rồi)","comps":"已经…了 · 已经好了 · 已经两年了","example":{"zh":"已经踢了十年了。","py":"Yǐjīng tī le shí nián le.","vi":"Đã đá được mười năm rồi."}},{"stt":10,"hanzi":"长","pinyin":"cháng","hanviet":"Trường","pos":"Tính từ","meaning":"Dài, lâu","comps":"多长时间 · 很长 · 长时间","example":{"zh":"你在这儿工作多长时间了？","py":"Nǐ zài zhèr gōngzuò duō cháng shíjiān le?","vi":"Bạn làm việc ở đây được bao lâu rồi?"}},{"stt":11,"hanzi":"两","pinyin":"liǎng","hanviet":"Lưỡng","pos":"Số từ","meaning":"Hai","comps":"两年 · 两个 · 两个儿子","example":{"zh":"已经两年多了。","py":"Yǐjīng liǎng nián duō le.","vi":"Đã hơn hai năm rồi."}},{"stt":12,"hanzi":"帮","pinyin":"bāng","hanviet":"Bang","pos":"Động từ","meaning":"Giúp, giúp đỡ","comps":"帮我 · 帮你介绍 · 帮忙","example":{"zh":"这个工作是他帮我介绍的。","py":"Zhège gōngzuò shì tā bāng wǒ jièshào de.","vi":"Công việc này là anh ấy giúp tôi giới thiệu."}},{"stt":13,"hanzi":"介绍","pinyin":"jièshào","hanviet":"Giới thiệu","pos":"Động từ","meaning":"Giới thiệu","comps":"介绍工作 · 帮我介绍 · 介绍一下","example":{"zh":"这个工作是他帮我介绍的。","py":"Zhège gōngzuò shì tā bāng wǒ jièshào de.","vi":"Công việc này là anh ấy giúp tôi giới thiệu."}}],"hanzi":[{"char":"生日","pinyin":"shēngrì","hanviet":"Sinh nhật","chars":["生","日"],"story":"生 (sinh ra) + 日 (ngày). Ngày được sinh ra = sinh nhật."},{"char":"快乐","pinyin":"kuàilè","hanviet":"Khoái lạc","chars":["快","乐"],"story":"快 (vui, nhanh, bộ 忄tâm) + 乐 (vui mừng). Lòng vui = vui vẻ."},{"char":"给","pinyin":"gěi","hanviet":"Cấp","chars":["给"],"story":"Bộ 纟 (sợi tơ) + 合. Trao sợi/đồ vật cho người khác = cho."},{"char":"接","pinyin":"jiē","hanviet":"Tiếp","chars":["接"],"story":"Bộ 扌 (tay) + 妾. Dùng tay nhận lấy = nhận, nghe máy."},{"char":"晚上","pinyin":"wǎnshang","hanviet":"Vãn thượng","chars":["晚","上"],"story":"晚 (muộn, bộ 日 mặt trời) + 上 (lúc). Khoảng muộn trong ngày = buổi tối."},{"char":"问","pinyin":"wèn","hanviet":"Vấn","chars":["问"],"story":"Bộ 门 (cửa) bao ngoài 口 (miệng). Đứng ở cửa há miệng = hỏi."},{"char":"非常","pinyin":"fēicháng","hanviet":"Phi thường","chars":["非","常"],"story":"非 (không) + 常 (bình thường). Khác thường, vượt mức bình thường = rất, vô cùng."},{"char":"开始","pinyin":"kāishǐ","hanviet":"Khai thủy","chars":["开","始"],"story":"开 (mở) + 始 (khởi đầu, bộ 女). Mở ra điều khởi đầu = bắt đầu."},{"char":"已经","pinyin":"yǐjīng","hanviet":"Dĩ kinh","chars":["已","经"],"story":"已 (đã, rồi) + 经 (trải qua, bộ 纟). Đã trải qua = đã rồi."},{"char":"长","pinyin":"cháng","hanviet":"Trường","chars":["长"],"story":"长 vốn vẽ người tóc dài; khi đọc cháng mang nghĩa “dài, lâu”."},{"char":"两","pinyin":"liǎng","hanviet":"Lưỡng","chars":["两"],"story":"两 giống cái ách đôi mắc trên cổ ngựa, ý chỉ “hai, cặp đôi”."},{"char":"帮","pinyin":"bāng","hanviet":"Bang","chars":["帮"],"story":"封 (bên trên) + 巾 (khăn, bộ vải). Góp sức cho người khác = giúp đỡ."},{"char":"介绍","pinyin":"jièshào","hanviet":"Giới thiệu","chars":["介","绍"],"story":"介 (ở giữa, làm trung gian) + 绍 (nối, bộ 纟). Làm trung gian kết nối = giới thiệu."}],"grammar":[{"title":"Câu 是…的 (nhấn mạnh chủ thể)","formula":"宾语 + 是 + <span>谁 / 什么时候</span> + 动词 + 的","summary":"Khi đã biết rõ một việc <b>đã xảy ra</b>, ta dùng cấu trúc <b>是…的</b> để nhấn mạnh <b>người thực hiện</b> (hoặc thời gian, nơi chốn) hành động. Trật tự: 宾语 + 是 + (ai/khi nào) + 动词 + 的. Phủ định thêm <b>不</b> trước 是. Cột “Nghi vấn” là câu hỏi; hai cột còn lại là câu trả lời.","note":"<strong>Lưu ý:</strong> Cuối câu bắt buộc có <b>的</b>, không được bỏ. Phủ định: 不是…的.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Cấu trúc ……的时候 (diễn tả thời gian)","formula":"(数量 / 动词) + <span>的时候</span> + mệnh đề chính","summary":"<b>……的时候</b> dùng để chỉ thời điểm “khi/lúc”. Phía trước 的时候 có thể là <b>cụm số lượng</b> (十一岁的时候) hoặc <b>động từ/cụm động từ</b> (睡觉的时候). Cụm thời gian này luôn đứng <b>trước</b> mệnh đề chính. Cột “Nghi vấn” là câu hỏi; hai cột còn lại là câu trả lời.","note":"<strong>Lưu ý:</strong> 的时候 đặt ở <b>đầu</b> câu hoặc đầu vế, không đặt sau mệnh đề chính.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Phó từ thời gian 已经 (已经…了)","formula":"已经 + <span>动词 / 形容词</span> + 了","summary":"<b>已经</b> (đã) biểu thị hành động <b>đã hoàn thành</b> hoặc đã đạt đến một mức độ nào đó, thường đi cùng <b>了</b> ở cuối câu. Ví dụ: 王老师已经回家了 (cô Vương đã về nhà rồi), 已经踢了十年了 (đã đá được mười năm rồi). Cột “Nghi vấn” là câu hỏi; hai cột còn lại là câu trả lời.","note":"<strong>Lưu ý:</strong> 已经 hầu như luôn đi với <b>了</b>. Phủ định dùng <b>还没…</b> (chưa).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在教室","titleVi":"Trong lớp học","icon":"🎁","lines":[{"speaker":"A","zh":"生日快乐！这是送给你的！","py":"Shēngrì kuàilè! Zhè shì sòng gěi nǐ de!","vi":"Chúc mừng sinh nhật! Đây là món quà mình tặng bạn!"},{"speaker":"B","zh":"是什么？是一本书吗？","py":"Shì shénme? Shì yì běn shū ma?","vi":"Quà gì vậy? Có phải một quyển sách không?"},{"speaker":"A","zh":"对，这本书是我写的。","py":"Duì, zhè běn shū shì wǒ xiě de.","vi":"Đúng vậy, quyển sách này là do mình viết đấy."},{"speaker":"B","zh":"太谢谢你了！","py":"Tài xièxie nǐ le!","vi":"Cảm ơn bạn nhiều lắm!"}]},{"titleZh":"在家里","titleVi":"Ở nhà","icon":"📞","lines":[{"speaker":"A","zh":"早上有你一个电话。","py":"Zǎoshang yǒu nǐ yí ge diànhuà.","vi":"Buổi sáng có người gọi điện cho anh đó."},{"speaker":"B","zh":"电话是谁打的？","py":"Diànhuà shì shéi dǎ de?","vi":"Ai gọi vậy?"},{"speaker":"A","zh":"不知道，是儿子接的。","py":"Bù zhīdào, shì érzi jiē de.","vi":"Em không biết nữa, con trai nghe điện thoại."},{"speaker":"B","zh":"好，晚上我问一下儿子。","py":"Hǎo, wǎnshang wǒ wèn yíxià érzi.","vi":"Được rồi, để tối anh sẽ hỏi con."}]},{"titleZh":"在运动场","titleVi":"Ở sân vận động","icon":"⚽","lines":[{"speaker":"A","zh":"你喜欢踢足球吗？","py":"Nǐ xǐhuan tī zúqiú ma?","vi":"Anh có thích đá bóng không?"},{"speaker":"B","zh":"非常喜欢。","py":"Fēicháng xǐhuan.","vi":"Rất thích."},{"speaker":"A","zh":"你是什么时候开始踢足球的？","py":"Nǐ shì shénme shíhou kāishǐ tī zúqiú de?","vi":"Anh bắt đầu đá bóng từ khi nào vậy?"},{"speaker":"B","zh":"我十一岁的时候开始踢足球，已经踢了十年了。","py":"Wǒ shíyī suì de shíhou kāishǐ tī zúqiú, yǐjīng tī le shí nián le.","vi":"Từ lúc 11 tuổi. Tôi đá bóng được 10 năm rồi."}]},{"titleZh":"在公司","titleVi":"Trong công ty","icon":"🏢","lines":[{"speaker":"A","zh":"你在这儿工作多长时间了？","py":"Nǐ zài zhèr gōngzuò duō cháng shíjiān le?","vi":"Anh làm việc ở đây được bao lâu rồi?"},{"speaker":"B","zh":"已经两年多了，我是二〇一一年来的。","py":"Yǐjīng liǎng nián duō le, wǒ shì èr líng yī yī nián lái de.","vi":"Được hơn hai năm rồi. Tôi đến đây vào năm 2011."},{"speaker":"A","zh":"你认识谢先生吗？","py":"Nǐ rènshi Xiè xiānsheng ma?","vi":"Anh có quen ông Tạ không?"},{"speaker":"B","zh":"认识，我们是大学同学，这个工作是他帮我介绍的。","py":"Rènshi, wǒmen shì dàxué tóngxué, zhège gōngzuò shì tā bāng wǒ jièshào de.","vi":"Có quen, chúng tôi là bạn cùng lớp đại học. Ông ấy đã giới thiệu giúp tôi công việc này."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Sau bài 4, học viên biết <em>nhấn mạnh ai/khi nào thực hiện hành động</em>, kể chuyện công việc, chúc mừng sinh nhật và hỏi về thời gian, đồng thời nắm chắc 13 từ vựng và 3 điểm ngữ pháp trọng tâm.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Nhấn mạnh người thực hiện: <b>这本书是我写的。</b></li>\n        <li>Chúc mừng & cảm ơn: <b>生日快乐！太谢谢你了！</b></li>\n        <li>Hỏi thời gian: <b>什么时候开始的？工作多长时间了？</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>13 từ trọng tâm</li>\n        <li>Sự kiện: <b>生日 · 快乐 · 给 · 晚上</b></li>\n        <li>Hành động: <b>接 · 问 · 开始 · 帮 · 介绍</b></li>\n        <li>Phó từ & khác: <b>非常 · 已经 · 长 · 两</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Câu <b>是…的</b> (nhấn mạnh chủ thể)</li>\n        <li>Cấu trúc <b>……的时候</b> (diễn tả thời gian)</li>\n        <li>Phó từ thời gian <b>已经</b> (…了)</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm: Câu 是…的 & ……的时候</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Ba mảng ứng dụng nổi bật của bài 4: <em>câu 是…的</em> nhấn mạnh ai/khi nào/ở đâu thực hiện hành động, cấu trúc <em>……的时候</em> để nói thời điểm, và nhóm từ <em>công việc – nghề nghiệp</em> bổ trợ cho chủ đề bài học.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học bài 4, liên quan đến câu <em>是…的</em>, phó từ <em>已经</em>, cấu trúc <em>的时候</em> và phó từ <em>非常</em>.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Câu 是…的 thiếu 的</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Câu nhấn mạnh <b>是…的</b> bắt buộc có <b>的</b> ở cuối, không được bỏ.</p>\n        <p class=\"strike zh\">这本书是我写。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">这本书是我写的。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · 已经 thiếu 了</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\"><b>已经</b> (đã) thường đi cùng <b>了</b> ở cuối câu để chỉ việc đã hoàn thành.</p>\n        <p class=\"strike zh\">我已经吃饭。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我已经吃饭了。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Vị trí của …的时候</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Cụm <b>…的时候</b> chỉ thời điểm phải đứng <b>trước</b> mệnh đề chính.</p>\n        <p class=\"strike zh\">我开始踢足球十一岁的时候。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我十一岁的时候开始踢足球。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 4 · 非常 + 很</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\"><b>非常</b> và <b>很</b> đều là phó từ mức độ, <b>không</b> dùng cùng lúc.</p>\n        <p class=\"strike zh\">我非常很喜欢踢足球。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我非常喜欢踢足球。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn gom toàn bộ bài 4 theo cách dễ nhớ: từ chủ đề, cấu trúc vàng, mẫu câu thần chú đến cách chia nhóm từ vựng.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Nhấn mạnh ai/khi nào thực hiện hành động; kể chuyện công việc, sinh nhật, sở thích.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Ai làm<br><span class=\"syn-keyhz\">谁…的</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Khi nào<br><span class=\"syn-keyhz\">…的时候</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Đã xong<br><span class=\"syn-keyhz\">已经…了</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> “Ai làm (是…的) → lúc nào (的时候) → đã được bao lâu (已经…了)”.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">是 + ai + 动作 + 的</span></h3>\n      <p>Khi đã biết việc xảy ra, dùng 是…的 để nhấn mạnh người (hoặc lúc/nơi) thực hiện.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">是<br><small>shì</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">他帮我介绍<br><small>tā bāng wǒ jièshào</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">的<br><small>de</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> Phủ định thêm <strong>不</strong> trước 是; cuối câu luôn giữ <strong>的</strong>.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">这本书是谁写的？</span></td><td>Hỏi ai làm</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你是什么时候开始的？</span></td><td>Hỏi thời điểm</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你工作多长时间了？</span></td><td>Hỏi bao lâu</td></tr>\n        <tr><td><span class=\"syn-keyhz\">这个工作是他帮我介绍的。</span></td><td>Nhấn mạnh người</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Sự kiện</td><td><span class=\"syn-keyhz\">生日 · 快乐 · 给 · 晚上</span></td></tr>\n        <tr><td>Hành động</td><td><span class=\"syn-keyhz\">接 · 问 · 开始 · 帮 · 介绍</span></td></tr>\n        <tr><td>Phó từ & khác</td><td><span class=\"syn-keyhz\">非常 · 已经 · 长 · 两</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> “<strong>Sinh nhật (生日)</strong> được tặng sách, <strong>buổi tối (晚上)</strong> có người gọi điện mình <strong>nghe máy (接)</strong>; bạn đại học đã <strong>giúp (帮)</strong> mình <strong>giới thiệu (介绍)</strong> việc, mình làm <strong>đã (已经)</strong> hơn hai năm.”</div>\n    </div>\n  </div>"}],"cssId":"c69321c3f"},{"id":"k2v2-b05","courseId":"k2v2","order":5,"title":"Mua chiếc áo này đi","titleZh":"就买这件吧","vocab":[{"stt":1,"hanzi":"外面","pinyin":"wàimiàn","hanviet":"Ngoại diện","pos":"Danh từ","meaning":"Bên ngoài","comps":"去外面 · 在外面吃 · 外面下雨","example":{"zh":"我不想去外面吃，我想在家吃。","py":"Wǒ bù xiǎng qù wàimiàn chī, wǒ xiǎng zài jiā chī.","vi":"Em không muốn ăn ngoài, em muốn ăn ở nhà."}},{"stt":2,"hanzi":"准备","pinyin":"zhǔnbèi","hanviet":"Chuẩn bị","pos":"Động từ","meaning":"Định, dự định; chuẩn bị","comps":"准备做饭 · 准备考试 · 准备好了","example":{"zh":"那你准备做什么呢？","py":"Nà nǐ zhǔnbèi zuò shénme ne?","vi":"Vậy em định nấu món gì?"}},{"stt":3,"hanzi":"就","pinyin":"jiù","hanviet":"Tựu","pos":"Phó từ","meaning":"Thì, cứ (chỉ kết luận, dứt khoát)","comps":"就买这件 · 就在家吃 · 就做鱼吧","example":{"zh":"就做你爱吃的鱼吧。","py":"Jiù zuò nǐ ài chī de yú ba.","vi":"Thì nấu món cá mà anh thích ăn thôi."}},{"stt":4,"hanzi":"鱼","pinyin":"yú","hanviet":"Ngư","pos":"Danh từ","meaning":"Cá, món cá","comps":"吃鱼 · 做鱼 · 一条鱼","example":{"zh":"就做你爱吃的鱼吧。","py":"Jiù zuò nǐ ài chī de yú ba.","vi":"Thì nấu món cá mà anh thích ăn thôi."}},{"stt":5,"hanzi":"吧","pinyin":"ba","hanviet":"Ba","pos":"Trợ từ","meaning":"…đi, …nhé (đề nghị, thương lượng)","comps":"走吧 · 买这件吧 · 休息一下吧","example":{"zh":"就买这件吧。","py":"Jiù mǎi zhè jiàn ba.","vi":"Mua chiếc áo này đi."}},{"stt":6,"hanzi":"件","pinyin":"jiàn","hanviet":"Kiện","pos":"Lượng từ","meaning":"Cái, chiếc (dùng cho áo, việc)","comps":"一件衣服 · 这件 · 两件事","example":{"zh":"这件不错，就买这件吧。","py":"Zhè jiàn búcuò, jiù mǎi zhè jiàn ba.","vi":"Chiếc này khá đẹp, mua chiếc này đi."}},{"stt":7,"hanzi":"还","pinyin":"hái","hanviet":"Hoàn","pos":"Phó từ","meaning":"Cũng, khá (tàm tạm)","comps":"还可以 · 还好 · 还行","example":{"zh":"颜色还可以，就是有点儿大。","py":"Yánsè hái kěyǐ, jiùshì yǒudiǎnr dà.","vi":"Màu sắc cũng tạm được, nhưng hơi rộng."}},{"stt":8,"hanzi":"可以","pinyin":"kěyǐ","hanviet":"Khả dĩ","pos":"Tính từ","meaning":"Không tệ, tạm được; có thể","comps":"还可以 · 可以吗 · 不可以","example":{"zh":"颜色还可以。","py":"Yánsè hái kěyǐ.","vi":"Màu sắc cũng tạm được."}},{"stt":9,"hanzi":"不错","pinyin":"búcuò","hanviet":"Bất thác","pos":"Tính từ","meaning":"Khá tốt, tuyệt","comps":"很不错 · 这件不错 · 不错的工作","example":{"zh":"这件不错，就买这件吧。","py":"Zhè jiàn búcuò, jiù mǎi zhè jiàn ba.","vi":"Chiếc này khá đẹp, mua chiếc này đi."}},{"stt":10,"hanzi":"考试","pinyin":"kǎoshì","hanviet":"Khảo thí","pos":"Danh từ","meaning":"Cuộc thi, bài kiểm tra","comps":"考试怎么样 · 准备考试 · 考试了","example":{"zh":"是在想昨天的考试吗？","py":"Shì zài xiǎng zuótiān de kǎoshì ma?","vi":"Có phải đang nghĩ về bài kiểm tra hôm qua không?"}},{"stt":11,"hanzi":"意思","pinyin":"yìsi","hanviet":"Ý tứ","pos":"Danh từ","meaning":"Nghĩa, ý nghĩa","comps":"什么意思 · 不知道意思 · 有意思","example":{"zh":"很多字我都不知道是什么意思。","py":"Hěn duō zì wǒ dōu bù zhīdào shì shénme yìsi.","vi":"Có nhiều chữ tôi không biết nghĩa là gì."}},{"stt":12,"hanzi":"咖啡","pinyin":"kāfēi","hanviet":"Ca phi","pos":"Danh từ","meaning":"Cà phê","comps":"喝咖啡 · 一杯咖啡 · 咖啡馆","example":{"zh":"休息一下吧，喝咖啡吗？","py":"Xiūxi yíxià ba, hē kāfēi ma?","vi":"Nghỉ một chút đi, uống cà phê không?"}},{"stt":13,"hanzi":"对","pinyin":"duì","hanviet":"Đối","pos":"Giới từ","meaning":"Đối với, cho","comps":"对身体不好 · 对我说 · 对…好","example":{"zh":"咖啡喝多了对身体不好。","py":"Kāfēi hē duō le duì shēntǐ bù hǎo.","vi":"Uống nhiều cà phê không tốt cho sức khỏe."}},{"stt":14,"hanzi":"以后","pinyin":"yǐhòu","hanviet":"Dĩ hậu","pos":"Danh từ","meaning":"Sau này, về sau","comps":"以后 · 下课以后 · 三年以后","example":{"zh":"以后我少喝一点儿。","py":"Yǐhòu wǒ shǎo hē yìdiǎnr.","vi":"Sau này tôi sẽ uống ít đi một chút."}}],"hanzi":[{"char":"外面","pinyin":"wàimiàn","hanviet":"Ngoại diện","chars":["外","面"],"story":"外 (ngoài) + 面 (mặt, phía). Phía bên ngoài = bên ngoài."},{"char":"准备","pinyin":"zhǔnbèi","hanviet":"Chuẩn bị","chars":["准","备"],"story":"准 (chuẩn) + 备 (sẵn sàng). Làm cho sẵn sàng = chuẩn bị, dự định."},{"char":"就","pinyin":"jiù","hanviet":"Tựu","chars":["就"],"story":"就 dùng để nối với điều vừa nói, đưa ra kết luận hay quyết định dứt khoát."},{"char":"鱼","pinyin":"yú","hanviet":"Ngư","chars":["鱼"],"story":"Chữ 鱼 giống hình con cá có đầu, mình và đuôi đầy đủ."},{"char":"吧","pinyin":"ba","hanviet":"Ba","chars":["吧"],"story":"Bộ 口 (miệng) + 巴. Đặt cuối câu để đề nghị, thỉnh cầu hay ra lệnh nhẹ."},{"char":"件","pinyin":"jiàn","hanviet":"Kiện","chars":["件"],"story":"Bộ 亻 (người) + 牛 (con bò). Lượng từ đếm áo quần, sự việc."},{"char":"还","pinyin":"hái","hanviet":"Hoàn","chars":["还"],"story":"Bộ 辶 (đi) + 不. Ở đây 还 + tính từ = mức tàm tạm, chấp nhận được."},{"char":"可以","pinyin":"kěyǐ","hanviet":"Khả dĩ","chars":["可","以"],"story":"可 (được, có thể) + 以 (dùng). Ghép lại = có thể, tạm được."},{"char":"不错","pinyin":"búcuò","hanviet":"Bất thác","chars":["不","错"],"story":"不 (không) + 错 (sai). Không có gì sai = khá tốt, được lắm."},{"char":"考试","pinyin":"kǎoshì","hanviet":"Khảo thí","chars":["考","试"],"story":"考 (khảo, sát hạch) + 试 (thử, bộ 讠nói). Sát hạch thử = thi, kiểm tra."},{"char":"意思","pinyin":"yìsi","hanviet":"Ý tứ","chars":["意","思"],"story":"意 (ý, bộ 心 tim) + 思 (nghĩ). Điều trong ý nghĩ = nghĩa, ý nghĩa."},{"char":"咖啡","pinyin":"kāfēi","hanviet":"Ca phi","chars":["咖","啡"],"story":"咖 + 啡 đều có bộ 口 (miệng), là chữ phiên âm của “coffee”."},{"char":"对","pinyin":"duì","hanviet":"Đối","chars":["对"],"story":"对 đặt trước đối tượng để chỉ hướng tác động: 对身体 (đối với cơ thể)."},{"char":"以后","pinyin":"yǐhòu","hanviet":"Dĩ hậu","chars":["以","后"],"story":"以 (lấy mốc) + 后 (sau). Tính từ mốc về sau = sau này."}],"grammar":[{"title":"Phó từ 就 (kết luận, quyết định)","formula":"(tiền đề), <span>就</span> + 动词 + 吧","summary":"<b>就 + động từ</b> dùng để nối với nội dung vừa nói và <b>đưa ra kết luận hay giải pháp</b>. Ví dụ: 你不想去，就在家休息吧 (bạn không muốn đi thì ở nhà nghỉ đi). 就 luôn đứng <b>trước động từ</b>, thường kèm 吧 cuối câu. Cột “Nghi vấn” là câu hỏi gợi ra tình huống; hai cột còn lại là cách đáp.","note":"<strong>Lưu ý:</strong> Trong câu “颜色还可以，就是有点儿大”, <b>就是</b> mang nghĩa nhượng bộ (chỉ có điều…).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Phó từ ngữ khí 还 (还可以 — tàm tạm)","formula":"还 + <span>形容词</span>  (= tàm tạm, chấp nhận được)","summary":"<b>还 + tính từ</b> diễn tả ý “<b>tàm tạm, chấp nhận được</b>”, mức độ thấp hơn 不错/非常好. Hay gặp: 还好, 还行, 还可以. Cột “Nghi vấn” là câu hỏi; hai cột còn lại là câu trả lời (khẳng định mức tàm tạm / phủ định).","note":"<strong>Lưu ý:</strong> 还 ở đây chỉ mức <b>vừa phải</b>, không đi kèm 非常/很 để chỉ mức cao.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Phó từ mức độ 有点儿 (hơi — chưa vừa ý)","formula":"有点儿 + <span>形容词 / 动词</span>  (sắc thái chê nhẹ)","summary":"<b>有点儿 + tính từ/động từ</b> thường biểu thị <b>cảm xúc tiêu cực, không hài lòng</b> của người nói. Ví dụ: 今天天气有点儿冷 (hôm nay trời hơi lạnh). 有点儿 luôn đứng <b>trước</b> tính từ, khác với 一点儿. Cột “Nghi vấn” là câu hỏi; hai cột còn lại là câu trả lời.","note":"<strong>Lưu ý:</strong> Phân biệt 有点儿 (đứng <b>trước</b> tính từ, chê) với 一点儿 (đứng <b>sau</b> tính từ để so sánh: 大一点儿).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在家里","titleVi":"Ở nhà","icon":"🐟","lines":[{"speaker":"A","zh":"晚上我们去饭馆吃饭，怎么样？","py":"Wǎnshang wǒmen qù fànguǎn chī fàn, zěnmeyàng?","vi":"Tối nay chúng ta đến quán ăn cơm, được không em?"},{"speaker":"B","zh":"我不想去外面吃，我想在家吃。","py":"Wǒ bù xiǎng qù wàimiàn chī, wǒ xiǎng zài jiā chī.","vi":"Em không muốn ăn ngoài, em muốn ăn ở nhà."},{"speaker":"A","zh":"那你准备做什么呢？","py":"Nà nǐ zhǔnbèi zuò shénme ne?","vi":"Vậy em định nấu món gì?"},{"speaker":"B","zh":"就做你爱吃的鱼吧。","py":"Jiù zuò nǐ ài chī de yú ba.","vi":"Thì nấu món cá mà anh thích ăn thôi."}]},{"titleZh":"在商店","titleVi":"Ở cửa hàng","icon":"👕","lines":[{"speaker":"A","zh":"帮我看一下这件衣服怎么样。","py":"Bāng wǒ kàn yíxià zhè jiàn yīfu zěnmeyàng.","vi":"Xem giúp mình chiếc áo này thế nào."},{"speaker":"B","zh":"颜色还可以，就是有点儿大。","py":"Yánsè hái kěyǐ, jiùshì yǒudiǎnr dà.","vi":"Màu sắc cũng tạm được, nhưng hơi rộng."},{"speaker":"A","zh":"这件小的怎么样？","py":"Zhè jiàn xiǎo de zěnmeyàng?","vi":"Còn chiếc áo nhỏ này thì sao?"},{"speaker":"B","zh":"这件不错，就买这件吧。","py":"Zhè jiàn búcuò, jiù mǎi zhè jiàn ba.","vi":"Chiếc này khá đẹp đấy. Mua chiếc áo này đi."}]},{"titleZh":"在教室","titleVi":"Trong lớp học","icon":"📚","lines":[{"speaker":"A","zh":"今天去不去打球？","py":"Jīntiān qù bu qù dǎ qiú?","vi":"Hôm nay bạn đi chơi bóng không?"},{"speaker":"B","zh":"这两天有点儿累，不去打球了。","py":"Zhè liǎng tiān yǒudiǎnr lèi, bú qù dǎ qiú le.","vi":"Mấy ngày nay mình hơi mệt, không đi chơi bóng đâu."},{"speaker":"A","zh":"你在做什么呢？是在想昨天的考试吗？","py":"Nǐ zài zuò shénme ne? Shì zài xiǎng zuótiān de kǎoshì ma?","vi":"Bạn đang làm gì thế? Có phải đang nghĩ về bài kiểm tra hôm qua không?"},{"speaker":"B","zh":"是啊，我觉得听和说还可以，读和写不好，很多字我都不知道是什么意思。","py":"Shì a, wǒ juéde tīng hé shuō hái kěyǐ, dú hé xiě bù hǎo, hěn duō zì wǒ dōu bù zhīdào shì shénme yìsi.","vi":"Đúng vậy, mình thấy phần nghe và nói cũng tạm, đọc và viết thì không tốt, có nhiều chữ mình không biết nghĩa là gì."}]},{"titleZh":"在公司","titleVi":"Trong công ty","icon":"☕","lines":[{"speaker":"A","zh":"休息一下吧，喝咖啡吗？","py":"Xiūxi yíxià ba, hē kāfēi ma?","vi":"Nghỉ một chút đi, uống cà phê không?"},{"speaker":"B","zh":"不喝了，我已经喝两杯了。","py":"Bù hē le, wǒ yǐjīng hē liǎng bēi le.","vi":"Không uống nữa đâu, tôi đã uống hai ly rồi."},{"speaker":"A","zh":"是啊，咖啡喝多了对身体不好。","py":"Shì a, kāfēi hē duō le duì shēntǐ bù hǎo.","vi":"Đúng đấy, uống nhiều cà phê không tốt cho sức khỏe."},{"speaker":"B","zh":"以后我少喝一点儿，每天喝一杯。","py":"Yǐhòu wǒ shǎo hē yìdiǎnr, měi tiān hē yì bēi.","vi":"Sau này tôi sẽ uống ít một chút, mỗi ngày chỉ một ly thôi."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Sau bài 5, học viên biết <em>nhận xét, đánh giá người/đồ vật/sự việc</em>, đưa ra quyết định khi mua sắm và rủ rê đề nghị, đồng thời nắm chắc 14 từ vựng và 3 điểm ngữ pháp trọng tâm.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Rủ rê & đề nghị: <b>我们去饭馆吃饭，怎么样？</b></li>\n        <li>Nhận xét đánh giá: <b>还可以 · 不错 · 有点儿大</b></li>\n        <li>Đưa ra quyết định: <b>这件不错，就买这件吧。</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>14 từ trọng tâm</li>\n        <li>Đồ & nơi chốn: <b>外面 · 鱼 · 咖啡 · 考试</b></li>\n        <li>Nhận xét: <b>还 · 可以 · 不错</b></li>\n        <li>Khác: <b>准备 · 就 · 件 · 意思 · 对 · 以后 · 吧</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Phó từ <b>就</b> (kết luận, quyết định)</li>\n        <li>Phó từ ngữ khí <b>还</b> (还可以 — tàm tạm)</li>\n        <li>Phó từ mức độ <b>有点儿</b> (hơi — chưa vừa ý)</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm: Thang đánh giá & 就…吧</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Ba mảng ứng dụng nổi bật của bài 5: <em>thang đánh giá mức độ</em> (非常 → 不错/还可以 → 有点儿 → 不), cách <em>就…吧</em> để đưa ra quyết định, và nhóm từ <em>mua sắm – sinh hoạt</em> bổ trợ cho chủ đề bài học.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học bài 5, liên quan đến <em>有点儿</em>, vị trí của <em>就</em>, giới từ <em>对</em> và trợ từ <em>吧</em>.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · 有点儿 ≠ 一点儿</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Chê “hơi…” (chưa vừa ý) dùng <b>有点儿 + tính từ</b>, đứng <b>trước</b> tính từ. Không dùng 一点儿.</p>\n        <p class=\"strike zh\">这件衣服一点儿大。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">这件衣服有点儿大。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Vị trí của 就</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\"><b>就</b> là phó từ, phải đứng <b>trước động từ</b>, không đặt sau.</p>\n        <p class=\"strike zh\">买这件就吧。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">就买这件吧。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Vị trí của 对</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Giới từ <b>对</b> + đối tượng phải đứng <b>trước</b> phần nhận xét (对身体不好).</p>\n        <p class=\"strike zh\">咖啡喝多了不好对身体。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">咖啡喝多了对身体不好。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 4 · 吧 và 吗 dùng lẫn</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\"><b>吧</b> dùng để đề nghị/thương lượng, <b>吗</b> để hỏi. Không dùng cả hai cùng lúc.</p>\n        <p class=\"strike zh\">我们去吃饭吧吗？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我们去吃饭吧。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn gom toàn bộ bài 5 theo cách dễ nhớ: từ chủ đề, cấu trúc vàng, mẫu câu thần chú đến cách chia nhóm từ vựng.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Mua sắm, nhận xét – đánh giá đồ vật/sự việc và đưa ra quyết định.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Hỏi ý kiến<br><span class=\"syn-keyhz\">怎么样？</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Nhận xét<br><span class=\"syn-keyhz\">还可以 · 有点儿</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Quyết định<br><span class=\"syn-keyhz\">就…吧</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> “Hỏi (怎么样) → nhận xét (还可以/有点儿) → chốt (就…吧)”.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">就 + 动词 + 吧</span></h3>\n      <p>Dựa vào điều vừa nói, dùng 就…吧 để đưa ra kết luận/quyết định một cách dứt khoát.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">就<br><small>jiù</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">买这件<br><small>mǎi zhè jiàn</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">吧<br><small>ba</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> <strong>就</strong> đứng trước động từ; <strong>吧</strong> ở cuối câu để đề nghị/quyết định.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">这件衣服怎么样？</span></td><td>Hỏi ý kiến</td></tr>\n        <tr><td><span class=\"syn-keyhz\">还可以，就是有点儿大。</span></td><td>Nhận xét</td></tr>\n        <tr><td><span class=\"syn-keyhz\">这件不错，就买这件吧。</span></td><td>Quyết định</td></tr>\n        <tr><td><span class=\"syn-keyhz\">咖啡喝多了对身体不好。</span></td><td>Đánh giá / khuyên</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Đồ & nơi chốn</td><td><span class=\"syn-keyhz\">外面 · 鱼 · 咖啡 · 考试</span></td></tr>\n        <tr><td>Nhận xét</td><td><span class=\"syn-keyhz\">还 · 可以 · 不错</span></td></tr>\n        <tr><td>Khác</td><td><span class=\"syn-keyhz\">准备 · 就 · 件 · 意思 · 对 · 以后 · 吧</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> “Tối <strong>chuẩn bị (准备)</strong> nấu <strong>cá (鱼)</strong> ở nhà; ra <strong>cửa hàng</strong> thử <strong>áo (件)</strong> thấy <strong>còn (还)</strong> được, <strong>hơi (有点儿)</strong> rộng, <strong>thì (就)</strong> mua chiếc nhỏ <strong>thôi (吧)</strong>; uống <strong>cà phê (咖啡)</strong> nhiều, <strong>sau này (以后)</strong> uống ít lại.”</div>\n    </div>\n  </div>"}],"cssId":"c69321c3f"},{"id":"k2v2-b06","courseId":"k2v2","order":6,"title":"Sao anh không ăn nữa?","titleZh":"你怎么不吃了？","vocab":[{"stt":1,"hanzi":"门","pinyin":"mén","hanviet":"Môn","pos":"Danh từ","meaning":"Cửa, cổng","comps":"门外 · 开门 · 在门口","example":{"zh":"我在门外看见他的自行车了。","py":"Wǒ zài mén wài kànjiàn tā de zìxíngchē le.","vi":"Mình thấy xe đạp của cậu ấy ở ngoài cửa."}},{"stt":2,"hanzi":"外","pinyin":"wài","hanviet":"Ngoại","pos":"Danh từ","meaning":"Bên ngoài","comps":"门外 · 外面 · 在外面吃","example":{"zh":"外面下雨了，我们在家吃饭吧。","py":"Wàimiàn xià yǔ le, wǒmen zài jiā chī fàn ba.","vi":"Bên ngoài mưa rồi, chúng ta ăn cơm ở nhà thôi."}},{"stt":3,"hanzi":"自行车","pinyin":"zìxíngchē","hanviet":"Tự hành xa","pos":"Danh từ","meaning":"Xe đạp","comps":"一辆自行车 · 骑自行车 · 我的自行车","example":{"zh":"我在门外看见他的自行车了。","py":"Wǒ zài mén wài kànjiàn tā de zìxíngchē le.","vi":"Mình thấy xe đạp của cậu ấy ở ngoài cửa."}},{"stt":4,"hanzi":"羊肉","pinyin":"yángròu","hanviet":"Dương nhục","pos":"Danh từ","meaning":"Thịt dê / thịt cừu","comps":"吃羊肉 · 羊肉面 · 喜欢羊肉","example":{"zh":"今天的羊肉很好吃，你怎么不吃了？","py":"Jīntiān de yángròu hěn hǎochī, nǐ zěnme bù chī le?","vi":"Thịt cừu hôm nay rất ngon, sao anh không ăn nữa?"}},{"stt":5,"hanzi":"好吃","pinyin":"hǎochī","hanviet":"Hảo cật","pos":"Tính từ","meaning":"Ngon (đồ ăn)","comps":"很好吃 · 不好吃 · 好吃的菜","example":{"zh":"今天的羊肉很好吃。","py":"Jīntiān de yángròu hěn hǎochī.","vi":"Thịt cừu hôm nay rất ngon."}},{"stt":6,"hanzi":"面条","pinyin":"miàntiáo","hanviet":"Diện điều","pos":"Danh từ","meaning":"Mì sợi","comps":"吃面条 · 一点儿面条 · 做面条","example":{"zh":"来一点儿面条吧。","py":"Lái yìdiǎnr miàntiáo ba.","vi":"Cho một ít mì sợi đi."}},{"stt":7,"hanzi":"打篮球","pinyin":"dǎ lánqiú","hanviet":"Đả lam cầu","pos":"Cụm động từ","meaning":"Chơi bóng rổ","comps":"去打篮球 · 喜欢打篮球 · 打篮球了","example":{"zh":"昨天你们怎么都没去打篮球？","py":"Zuótiān nǐmen zěnme dōu méi qù dǎ lánqiú?","vi":"Hôm qua sao các cậu đều không đi chơi bóng rổ?"}},{"stt":8,"hanzi":"因为","pinyin":"yīnwèi","hanviet":"Nhân vị","pos":"Liên từ","meaning":"Bởi vì, do","comps":"因为下雨 · 因为……所以…… · 因为他","example":{"zh":"因为昨天下雨，所以我们都没去。","py":"Yīnwèi zuótiān xià yǔ, suǒyǐ wǒmen dōu méi qù.","vi":"Vì hôm qua trời mưa nên chúng tôi đều không đi."}},{"stt":9,"hanzi":"所以","pinyin":"suǒyǐ","hanviet":"Sở dĩ","pos":"Liên từ","meaning":"Cho nên, vì vậy","comps":"所以没去 · 因为……所以…… · 所以我","example":{"zh":"因为昨天下雨，所以我们都没去。","py":"Yīnwèi zuótiān xià yǔ, suǒyǐ wǒmen dōu méi qù.","vi":"Vì hôm qua trời mưa nên chúng tôi đều không đi."}},{"stt":10,"hanzi":"游泳","pinyin":"yóuyǒng","hanviet":"Du vịnh","pos":"Động từ","meaning":"Bơi, bơi lội","comps":"去游泳 · 天天游泳 · 喜欢游泳","example":{"zh":"我去游泳了。","py":"Wǒ qù yóuyǒng le.","vi":"Tôi đi bơi rồi."}},{"stt":11,"hanzi":"经常","pinyin":"jīngcháng","hanviet":"Kinh thường","pos":"Phó từ","meaning":"Thường xuyên","comps":"经常游泳 · 经常去 · 不经常","example":{"zh":"你经常游泳吗？","py":"Nǐ jīngcháng yóuyǒng ma?","vi":"Bạn có thường xuyên đi bơi không?"}},{"stt":12,"hanzi":"公斤","pinyin":"gōngjīn","hanviet":"Công cân","pos":"Lượng từ","meaning":"Kilôgram (kg)","comps":"七十公斤 · 一公斤 · 几公斤","example":{"zh":"我现在七十公斤了。","py":"Wǒ xiànzài qīshí gōngjīn le.","vi":"Bây giờ tôi nặng 70 kilôgram rồi."}},{"stt":13,"hanzi":"姐姐","pinyin":"jiějie","hanviet":"Tỷ tỷ","pos":"Danh từ","meaning":"Chị gái","comps":"我姐姐 · 他姐姐 · 看姐姐","example":{"zh":"听说他是去看他姐姐。","py":"Tīngshuō tā shì qù kàn tā jiějie.","vi":"Nghe nói anh ấy đi thăm chị gái của mình."}}],"hanzi":[{"char":"门","pinyin":"mén","hanviet":"Môn","chars":["门"],"story":"Chữ 门 (giản thể) mô phỏng hai cánh cửa; bản phồn thể 門 là hình hai cánh cửa khép vào nhau."},{"char":"外","pinyin":"wài","hanviet":"Ngoại","chars":["外"],"story":"夕 (chiều tối) + 卜 (bói). Việc bói toán buổi chiều thường làm ở ngoài → bên ngoài."},{"char":"自行车","pinyin":"zìxíngchē","hanviet":"Tự hành xa","chars":["自","行","车"],"story":"自 (tự) + 行 (đi) + 车 (xe). Chiếc xe tự đi bằng sức người = xe đạp."},{"char":"羊肉","pinyin":"yángròu","hanviet":"Dương nhục","chars":["羊","肉"],"story":"羊 (con dê/cừu) + 肉 (thịt). Thịt của con dê = thịt cừu."},{"char":"好吃","pinyin":"hǎochī","hanviet":"Hảo cật","chars":["好","吃"],"story":"好 (tốt) + 吃 (ăn). Ăn vào thấy tốt = ngon."},{"char":"面条","pinyin":"miàntiáo","hanviet":"Diện điều","chars":["面","条"],"story":"面 (bột mì) + 条 (sợi dài). Bột mì kéo thành sợi = mì sợi."},{"char":"打篮球","pinyin":"dǎ lánqiú","hanviet":"Đả lam cầu","chars":["打","篮","球"],"story":"打 (đánh, chơi) + 篮 (cái rổ) + 球 (quả bóng). Chơi ném bóng vào rổ = bóng rổ."},{"char":"因为","pinyin":"yīnwèi","hanviet":"Nhân vị","chars":["因","为"],"story":"因 (nguyên do) + 为 (vì). Nêu lý do của sự việc = bởi vì."},{"char":"所以","pinyin":"suǒyǐ","hanviet":"Sở dĩ","chars":["所","以"],"story":"所 (nơi) + 以 (do). Đặt sau để dẫn ra kết quả = cho nên."},{"char":"游泳","pinyin":"yóuyǒng","hanviet":"Du vịnh","chars":["游","泳"],"story":"游 (bơi, dạo) + 泳 (lội), cả hai đều có bộ 氵(nước). Hoạt động dưới nước = bơi."},{"char":"经常","pinyin":"jīngcháng","hanviet":"Kinh thường","chars":["经","常"],"story":"经 (trải qua) + 常 (thường). Việc lặp đi lặp lại = thường xuyên."},{"char":"公斤","pinyin":"gōngjīn","hanviet":"Công cân","chars":["公","斤"],"story":"公 (chung, chuẩn) + 斤 (cân). Đơn vị cân theo chuẩn quốc tế = kilôgram."},{"char":"姐姐","pinyin":"jiějie","hanviet":"Tỷ tỷ","chars":["姐","姐"],"story":"Bộ 女 (nữ) đi với 且, lặp lại hai lần 姐姐 — người nữ lớn hơn trong nhà = chị gái."}],"grammar":[{"title":"Đại từ nghi vấn 怎么 (hỏi nguyên nhân)","formula":"主语 + <span>怎么</span> + 动词 / 形容词 ？","summary":"<b>怎么 + động từ / tính từ</b> dùng để hỏi <b>nguyên nhân</b> của sự việc, thường mang sắc thái <b>ngạc nhiên, khó hiểu</b>. Ví dụ: 你怎么不吃了？(Sao anh không ăn nữa?). Cột “Nghi vấn” là câu hỏi bằng 怎么; cột “Khẳng định” là cách đáp có nêu lý do, cột “Phủ định” là cách đáp ngắn.","note":"<strong>Lưu ý:</strong> câu có <b>怎么</b> đã là câu hỏi nên <b>không thêm 吗</b>. Phân biệt 怎么 (tại sao) với 怎么样 (thế nào).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Lặp lại lượng từ 量词重叠 (mỗi / mọi)","formula":"主语 + <span>量词重叠</span>(个个 / 天天) + 都 + …","summary":"Lượng từ khi được <b>lặp lại</b> mang nghĩa “<b>mỗi / mọi</b>”, nhấn mạnh mọi thành viên trong nhóm đều có chung đặc điểm, phía sau <b>thường dùng 都</b>. Ví dụ: 个个, 件件, 天天. Cột “Nghi vấn” là câu hỏi; cột “Khẳng định” dùng lượng từ lặp + 都, cột “Phủ định” là cách đáp ngược lại.","note":"<strong>Lưu ý:</strong> sau lượng từ lặp lại thường có <b>都</b>; 天天 = 每天 (ngày nào cũng).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Quan hệ nhân quả 因为……，所以……","formula":"<span>因为</span> + nguyên nhân，<span>所以</span> + kết quả","summary":"Cặp liên từ <b>因为</b> (bởi vì) … <b>所以</b> (cho nên) … nối hai mệnh đề có quan hệ nhân quả: mệnh đề trước nêu <b>nguyên nhân</b>, mệnh đề sau nêu <b>kết quả</b>. Khi đặt câu có thể dùng cả cặp hoặc lược bớt một trong hai. Cột “Nghi vấn” là câu hỏi nguyên nhân; cột “Khẳng định” và “Phủ định” là hai cách trả lời.","note":"<strong>Lưu ý:</strong> 因为 ở mệnh đề nguyên nhân (trước), 所以 ở mệnh đề kết quả (sau); không đảo vị trí hai vế.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在学校","titleVi":"Ở trường","icon":"🚲","lines":[{"speaker":"A","zh":"你知道小王今天什么时候来学校吗？","py":"Nǐ zhīdào Xiǎo Wáng jīntiān shénme shíhou lái xuéxiào ma?","vi":"Bạn có biết hôm nay khi nào Tiểu Vương đến trường không?"},{"speaker":"B","zh":"他已经来了。","py":"Tā yǐjīng lái le.","vi":"Cậu ấy đã đến rồi."},{"speaker":"A","zh":"你怎么知道他来了？","py":"Nǐ zěnme zhīdào tā lái le?","vi":"Sao bạn biết cậu ấy đã đến?"},{"speaker":"B","zh":"我在门外看见他的自行车了。","py":"Wǒ zài mén wài kànjiàn tā de zìxíngchē le.","vi":"Mình thấy xe đạp của cậu ấy ở ngoài cửa."}]},{"titleZh":"在饭馆","titleVi":"Ở quán ăn","icon":"🍜","lines":[{"speaker":"A","zh":"今天的羊肉很好吃，你怎么不吃了？","py":"Jīntiān de yángròu hěn hǎochī, nǐ zěnme bù chī le?","vi":"Thịt cừu hôm nay rất ngon, sao anh không ăn nữa?"},{"speaker":"B","zh":"这个星期天天都吃羊肉，不想吃了。","py":"Zhège xīngqī tiāntiān dōu chī yángròu, bù xiǎng chī le.","vi":"Tuần này ngày nào cũng ăn thịt cừu nên chẳng muốn ăn nữa."},{"speaker":"A","zh":"那你还想吃什么？","py":"Nà nǐ hái xiǎng chī shénme?","vi":"Vậy anh còn muốn ăn món gì?"},{"speaker":"B","zh":"来一点儿面条吧。","py":"Lái yìdiǎnr miàntiáo ba.","vi":"Cho tôi một ít mì sợi đi."}]},{"titleZh":"在健身房","titleVi":"Ở phòng tập thể dục","icon":"🏊","lines":[{"speaker":"A","zh":"昨天你们怎么都没去打篮球？","py":"Zuótiān nǐmen zěnme dōu méi qù dǎ lánqiú?","vi":"Hôm qua sao các anh không đi chơi bóng rổ?"},{"speaker":"B","zh":"因为昨天下雨，所以我们都没去。我去游泳了。","py":"Yīnwèi zuótiān xià yǔ, suǒyǐ wǒmen dōu méi qù. Wǒ qù yóuyǒng le.","vi":"Vì hôm qua trời mưa nên chúng tôi đều không đi. Tôi đi bơi rồi."},{"speaker":"A","zh":"你经常游泳吗？","py":"Nǐ jīngcháng yóuyǒng ma?","vi":"Anh có đi bơi thường xuyên không?"},{"speaker":"B","zh":"这个月我天天游泳，我现在七十公斤了。","py":"Zhège yuè wǒ tiāntiān yóuyǒng, wǒ xiànzài qīshí gōngjīn le.","vi":"Tháng này ngày nào tôi cũng bơi, hiện giờ tôi đã 70 kg rồi."}]},{"titleZh":"在办公室","titleVi":"Trong văn phòng","icon":"🏢","lines":[{"speaker":"A","zh":"这两天怎么没看见小张？","py":"Zhè liǎng tiān zěnme méi kànjiàn Xiǎo Zhāng?","vi":"Mấy ngày nay sao tôi không thấy Tiểu Trương?"},{"speaker":"B","zh":"他去北京了。","py":"Tā qù Běijīng le.","vi":"Anh ấy đi Bắc Kinh rồi."},{"speaker":"A","zh":"去北京了？是去旅游吗？","py":"Qù Běijīng le? Shì qù lǚyóu ma?","vi":"Đi Bắc Kinh à? Có phải đi du lịch không?"},{"speaker":"B","zh":"不是，听说是去看他姐姐。","py":"Bú shì, tīngshuō shì qù kàn tā jiějie.","vi":"Không phải, nghe nói là đi thăm chị gái của anh ấy."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Sau bài 6, học viên biết <em>hỏi nguyên nhân</em> bằng 怎么 với thái độ ngạc nhiên, <em>giải thích quan hệ nhân quả</em> bằng 因为……，所以……, dùng cách <em>lặp lại lượng từ</em> để diễn đạt “mỗi/mọi”, đồng thời nắm chắc 13 từ vựng và 3 điểm ngữ pháp trọng tâm.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi lý do (ngạc nhiên): <b>你怎么不吃了？</b></li>\n        <li>Giải thích nguyên nhân: <b>因为下雨，所以没去。</b></li>\n        <li>Nói thói quen: <b>我天天都游泳。</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>13 từ trọng tâm</li>\n        <li>Nơi chốn & đồ vật: <b>门 · 外 · 自行车</b></li>\n        <li>Ăn uống: <b>羊肉 · 好吃 · 面条</b></li>\n        <li>Vận động & khác: <b>打篮球 · 游泳 · 经常 · 公斤 · 姐姐</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Đại từ nghi vấn <b>怎么</b> (hỏi nguyên nhân)</li>\n        <li>Lặp lại lượng từ <b>个个 · 天天</b> (mỗi/mọi)</li>\n        <li>Quan hệ nhân quả <b>因为……，所以……</b></li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm: Hỏi &amp; giải thích nguyên nhân</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Ba mảng ứng dụng nổi bật của bài 6: dùng <em>怎么</em> để hỏi nguyên nhân (kèm thái độ ngạc nhiên), nối câu <em>因为……，所以……</em> để giải thích nhân quả, và cách <em>lặp lại lượng từ</em> (天天、个个) kèm 都 để nói “mỗi/mọi”.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học bài 6, liên quan đến <em>怎么</em>, cặp <em>因为……，所以……</em>, lượng từ lặp lại và phân biệt <em>好吃 / 好喝</em>.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · 怎么 đã là câu hỏi</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Câu có <b>怎么</b> hỏi nguyên nhân đã là câu nghi vấn, <b>không thêm 吗</b> ở cuối.</p>\n        <p class=\"strike zh\">你怎么不吃了吗？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">你怎么不吃了？</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Đảo vị trí 因为 / 所以</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\"><b>因为</b> nêu nguyên nhân (đứng trước), <b>所以</b> nêu kết quả (đứng sau). Không đảo ngược.</p>\n        <p class=\"strike zh\">所以下雨，因为我们没去。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">因为下雨，所以我们没去。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Lượng từ lặp thiếu 都</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Lượng từ lặp lại (个个、天天…) chỉ “mỗi/mọi”, phía sau <b>thường phải có 都</b>.</p>\n        <p class=\"strike zh\">同学们个个很高兴。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">同学们个个都很高兴。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 4 · 好吃 và 好喝</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\"><b>好吃</b> chỉ dùng cho <b>đồ ăn</b>; thức uống ngon phải dùng <b>好喝</b>.</p>\n        <p class=\"strike zh\">这个牛奶很好吃。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">这个牛奶很好喝。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn gom toàn bộ bài 6 theo cách dễ nhớ: từ chủ đề, cấu trúc vàng, mẫu câu thần chú đến cách chia nhóm từ vựng.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Hỏi và giải thích nguyên nhân – kết quả của sự việc trong sinh hoạt thường ngày.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Hỏi lý do<br><span class=\"syn-keyhz\">怎么？</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Nguyên nhân<br><span class=\"syn-keyhz\">因为…</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Kết quả<br><span class=\"syn-keyhz\">所以…</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> “Hỏi (怎么) → Vì (因为) → Nên (所以)”.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">因为……，所以……</span></h3>\n      <p>Nối hai mệnh đề nhân quả: mệnh đề đầu nêu nguyên nhân (因为), mệnh đề sau nêu kết quả (所以).</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">因为<br><small>yīnwèi</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">下雨<br><small>xià yǔ</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">所以没去<br><small>suǒyǐ méi qù</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> có thể lược bớt 因为 <strong>hoặc</strong> 所以, nhưng không đảo vị trí hai vế.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">你怎么不吃了？</span></td><td>Hỏi lý do</td></tr>\n        <tr><td><span class=\"syn-keyhz\">因为昨天下雨，所以没去。</span></td><td>Nhân quả</td></tr>\n        <tr><td><span class=\"syn-keyhz\">这个星期我天天都吃羊肉。</span></td><td>Lặp lượng từ</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我现在七十公斤了。</span></td><td>Nói cân nặng</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Nơi chốn & đồ vật</td><td><span class=\"syn-keyhz\">门 · 外 · 自行车</span></td></tr>\n        <tr><td>Ăn uống</td><td><span class=\"syn-keyhz\">羊肉 · 好吃 · 面条</span></td></tr>\n        <tr><td>Vận động & nhân quả</td><td><span class=\"syn-keyhz\">打篮球 · 游泳 · 经常 · 公斤 · 姐姐 · 因为 · 所以</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> “Thấy <strong>xe đạp (自行车)</strong> ở <strong>ngoài cửa (门外)</strong> là biết bạn đến; <strong>vì (因为)</strong> ngày nào <strong>(天天)</strong> cũng ăn <strong>thịt cừu (羊肉)</strong> tuy <strong>ngon (好吃)</strong> nên đổi sang <strong>mì (面条)</strong>; <strong>vì (因为)</strong> mưa <strong>nên (所以)</strong> không <strong>chơi bóng rổ (打篮球)</strong>, đi <strong>bơi (游泳)</strong> <strong>thường xuyên (经常)</strong> nên giờ <strong>70 cân (公斤)</strong>; bạn đi thăm <strong>chị gái (姐姐)</strong>.”</div>\n    </div>\n  </div>"}],"cssId":"c69321c3f"},{"id":"k2v2-b07","courseId":"k2v2","order":7,"title":"Nhà chị có ở xa công ty không?","titleZh":"你家离公司远吗？","vocab":[{"stt":1,"hanzi":"教室","pinyin":"jiàoshì","hanviet":"Giáo thất","pos":"Danh từ","meaning":"Lớp học, phòng học","comps":"在教室 · 来教室 · 教室里","example":{"zh":"没有，他还在教室学习呢。","py":"Méiyǒu, tā hái zài jiàoshì xuéxí ne.","vi":"Chưa, anh ấy vẫn còn học trong lớp."}},{"stt":2,"hanzi":"机场","pinyin":"jīchǎng","hanviet":"Cơ trường","pos":"Danh từ","meaning":"Sân bay","comps":"去机场 · 在机场 · 到机场","example":{"zh":"在去机场的路上。","py":"Zài qù jīchǎng de lùshang.","vi":"Đang trên đường ra sân bay."}},{"stt":3,"hanzi":"路","pinyin":"lù","hanviet":"Lộ","pos":"Danh từ","meaning":"Đường, lối đi","comps":"路上 · 走路 · 在路上","example":{"zh":"开车也不快，路上车太多了！","py":"Kāi chē yě bú kuài, lùshang chē tài duō le!","vi":"Lái xe cũng chẳng nhanh, trên đường quá nhiều xe!"}},{"stt":4,"hanzi":"离","pinyin":"lí","hanviet":"Ly","pos":"Động từ","meaning":"Cách (chỉ khoảng cách)","comps":"离公司远 · 离这儿近 · 离生日","example":{"zh":"你家离公司远吗？","py":"Nǐ jiā lí gōngsī yuǎn ma?","vi":"Nhà chị có ở xa công ty không?"}},{"stt":5,"hanzi":"公司","pinyin":"gōngsī","hanviet":"Công ty","pos":"Danh từ","meaning":"Công ty","comps":"去公司 · 在公司 · 离公司远","example":{"zh":"你家离公司远吗？","py":"Nǐ jiā lí gōngsī yuǎn ma?","vi":"Nhà chị có ở xa công ty không?"}},{"stt":6,"hanzi":"远","pinyin":"yuǎn","hanviet":"Viễn","pos":"Tính từ","meaning":"Xa","comps":"很远 · 不远 · 离…远","example":{"zh":"很远，坐公共汽车要一个多小时呢！","py":"Hěn yuǎn, zuò gōnggòng qìchē yào yí ge duō xiǎoshí ne!","vi":"Rất xa, đi xe buýt phải mất hơn một tiếng đồng hồ!"}},{"stt":7,"hanzi":"公共汽车","pinyin":"gōnggòng qìchē","hanviet":"Công cộng khí xa","pos":"Danh từ","meaning":"Xe buýt","comps":"坐公共汽车 · 等公共汽车 · 公共汽车站","example":{"zh":"坐公共汽车太慢了，你怎么不开车？","py":"Zuò gōnggòng qìchē tài màn le, nǐ zěnme bù kāi chē?","vi":"Đi xe buýt thì chậm quá, sao chị không lái xe?"}},{"stt":8,"hanzi":"小时","pinyin":"xiǎoshí","hanviet":"Tiểu thời","pos":"Danh từ","meaning":"Giờ (đồng hồ), tiếng","comps":"一个小时 · 半个小时 · 两个小时","example":{"zh":"坐飞机一个半小时就到北京了。","py":"Zuò fēijī yí ge bàn xiǎoshí jiù dào Běijīng le.","vi":"Đi máy bay một tiếng rưỡi là tới Bắc Kinh."}},{"stt":9,"hanzi":"慢","pinyin":"màn","hanviet":"Mạn","pos":"Tính từ","meaning":"Chậm","comps":"太慢了 · 很慢 · 慢一点儿","example":{"zh":"坐公共汽车太慢了。","py":"Zuò gōnggòng qìchē tài màn le.","vi":"Đi xe buýt chậm quá."}},{"stt":10,"hanzi":"快","pinyin":"kuài","hanviet":"Khoái","pos":"Tính từ","meaning":"Nhanh","comps":"很快 · 快一点儿 · 不快","example":{"zh":"开车也不快，路上车太多了！","py":"Kāi chē yě bú kuài, lùshang chē tài duō le!","vi":"Lái xe cũng chẳng nhanh, trên đường quá nhiều xe!"}},{"stt":11,"hanzi":"过","pinyin":"guò","hanviet":"Quá","pos":"Động từ","meaning":"Ăn (mừng), trải qua, qua","comps":"过生日 · 过节 · 过来","example":{"zh":"今天晚上我们一起吃饭吧，给你过生日。","py":"Jīntiān wǎnshang wǒmen yìqǐ chī fàn ba, gěi nǐ guò shēngrì.","vi":"Tối nay chúng ta cùng đi ăn cơm nhé, mừng sinh nhật bạn."}},{"stt":12,"hanzi":"走","pinyin":"zǒu","hanviet":"Tẩu","pos":"Động từ","meaning":"Đi, đi bộ","comps":"走路 · 走几分钟 · 我们走吧","example":{"zh":"走几分钟就到了。","py":"Zǒu jǐ fēnzhōng jiù dào le.","vi":"Đi bộ vài phút là tới."}},{"stt":13,"hanzi":"到","pinyin":"dào","hanviet":"Đáo","pos":"Động từ","meaning":"Đến, tới","comps":"到了 · 到这儿 · 二十分钟就到","example":{"zh":"二十分钟就到。","py":"Èrshí fēnzhōng jiù dào.","vi":"20 phút là tới."}}],"hanzi":[{"char":"教室","pinyin":"jiàoshì","hanviet":"Giáo thất","chars":["教","室"],"story":"教 (dạy) + 室 (phòng). Căn phòng để dạy học = lớp học."},{"char":"机场","pinyin":"jīchǎng","hanviet":"Cơ trường","chars":["机","场"],"story":"机 (máy, ở đây là 飞机 máy bay) + 场 (sân, bãi). Bãi đỗ máy bay = sân bay."},{"char":"路","pinyin":"lù","hanviet":"Lộ","chars":["路"],"story":"Bộ 足 (chân) + 各. Nơi chân người đi qua lại = con đường."},{"char":"离","pinyin":"lí","hanviet":"Ly","chars":["离"],"story":"离 đặt giữa hai điểm A và B để chỉ khoảng cách giữa chúng: A 离 B 远/近."},{"char":"公司","pinyin":"gōngsī","hanviet":"Công ty","chars":["公","司"],"story":"公 (chung) + 司 (quản lý). Tổ chức kinh doanh chung = công ty."},{"char":"远","pinyin":"yuǎn","hanviet":"Viễn","chars":["远"],"story":"Bộ 辶 (đi) + 元. Đi một quãng dài mới tới = xa."},{"char":"公共汽车","pinyin":"gōnggòng qìchē","hanviet":"Công cộng khí xa","chars":["公","共","汽","车"],"story":"公共 (công cộng) + 汽车 (xe hơi). Xe hơi dùng chung cho mọi người = xe buýt."},{"char":"小时","pinyin":"xiǎoshí","hanviet":"Tiểu thời","chars":["小","时"],"story":"小 (nhỏ) + 时 (thời gian). Đơn vị thời gian nhỏ trong ngày = giờ đồng hồ."},{"char":"慢","pinyin":"màn","hanviet":"Mạn","chars":["慢"],"story":"Bộ 忄 (tâm) + 曼. Lề mề, không vội = chậm."},{"char":"快","pinyin":"kuài","hanviet":"Khoái","chars":["快"],"story":"Bộ 忄 (tâm) + 夬. Lòng nóng, làm gấp = nhanh."},{"char":"过","pinyin":"guò","hanviet":"Quá","chars":["过"],"story":"Bộ 辶 (đi) + 寸. Trải qua thời gian, tổ chức một dịp = ăn mừng, qua."},{"char":"走","pinyin":"zǒu","hanviet":"Tẩu","chars":["走"],"story":"Chữ 走 vẽ hình người đang sải bước chân = đi, đi bộ."},{"char":"到","pinyin":"dào","hanviet":"Đáo","chars":["到"],"story":"至 (tới nơi) + 刂 (đao). Đi tới đích = đến, tới."}],"grammar":[{"title":"Phó từ ngữ khí 还 (tiếp diễn / 还没)","formula":"还(没) + <span>动词</span> + (呢)","summary":"<b>还</b> chỉ sự <b>tiếp diễn</b> của hành động hay trạng thái (“vẫn còn”). Khẳng định thường là <b>还在 + động từ + 呢</b>; phủ định dùng <b>还没(有)</b> (“vẫn chưa”). Ví dụ: 八点了，他还在睡觉呢. Cột “Nghi vấn” là câu hỏi; cột “Khẳng định” = vẫn còn, cột “Phủ định” = vẫn chưa.","note":"<strong>Lưu ý:</strong> phủ định của 还 là <b>还没(有)</b>, không phải 没还; 还 đứng trước 没.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Phó từ thời gian 就 (sớm, nhanh)","formula":"主语 + (thời lượng) + <span>就</span> + 动词 + 了","summary":"<b>就</b> (phó từ chỉ thời gian) nhấn mạnh sự việc xảy ra <b>sớm, nhanh, thuận lợi</b> theo cảm nhận của người nói. Thường dùng <b>就 + động từ + 了</b>. Ví dụ: 二十分钟就到 (20 phút là tới). 就 đứng <b>trước động từ</b>. Cột “Nghi vấn” hỏi thời gian/khả năng; cột “Khẳng định” dùng 就…了, cột “Phủ định” đáp lại theo hướng chậm/lâu.","note":"<strong>Lưu ý:</strong> 就 nhấn “sớm/nhanh”; đứng trước động từ, ngược nghĩa với cảm giác “lâu/muộn”.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Động từ 离 (khoảng cách)","formula":"A + <span>离</span> + B + 远 / 近 / khoảng cách","summary":"Động từ <b>离</b> dùng để chỉ <b>khoảng cách</b> giữa hai điểm A và B (nơi chốn, thời gian, mục đích): <b>A 离 B + 远 / 近 / số liệu</b>. Ví dụ: 我家离学校很远. Phía sau B thường là 远, 近 hoặc số liệu. Cột “Nghi vấn” hỏi “…远吗?”; cột “Khẳng định” và “Phủ định” đáp xa/gần.","note":"<strong>Lưu ý:</strong> 离 đứng giữa A và B; phần khoảng cách (远/近/số km) đứng <b>sau</b> B.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Trợ từ ngữ khí 呢 (xác nhận, cường điệu)","formula":"主语 + 形容词 / 动词 + <span>呢</span>","summary":"Trợ từ ngữ khí <b>呢</b> đặt ở <b>cuối câu trần thuật</b> (sau vị ngữ là tính từ hoặc động từ) để <b>xác nhận sự việc, thuyết phục</b> người nghe, mang ý <b>cường điệu</b>. Ví dụ: 八点上课，时间还早呢 (8 giờ vào học, còn sớm chán). Cột “Nghi vấn” là câu hỏi; cột “Khẳng định” dùng …呢, cột “Phủ định” đáp ngược lại.","note":"<strong>Lưu ý:</strong> 呢 ở đây nhấn mạnh – cường điệu, đi với câu trần thuật; <b>không dùng kèm 吗</b>.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在家里","titleVi":"Ở nhà","icon":"📖","lines":[{"speaker":"A","zh":"大卫回来了吗？","py":"Dàwèi huílai le ma?","vi":"David về chưa vậy?"},{"speaker":"B","zh":"没有，他还在教室学习呢。","py":"Méiyǒu, tā hái zài jiàoshì xuéxí ne.","vi":"Chưa, anh ấy còn đang học trong lớp."},{"speaker":"A","zh":"已经九点多了，他怎么还在学习？","py":"Yǐjīng jiǔ diǎn duō le, tā zěnme hái zài xuéxí?","vi":"Đã hơn 9 giờ rồi, sao còn đang học?"},{"speaker":"B","zh":"明天有考试，他说今天要好好准备。","py":"Míngtiān yǒu kǎoshì, tā shuō jīntiān yào hǎohāo zhǔnbèi.","vi":"Ngày mai có bài kiểm tra, anh ấy nói hôm nay phải chuẩn bị thật tốt."}]},{"titleZh":"去机场的路上","titleVi":"Trên đường ra sân bay","icon":"✈️","lines":[{"speaker":"A","zh":"你现在在哪儿呢？","py":"Nǐ xiànzài zài nǎr ne?","vi":"Hiện giờ anh đang ở đâu vậy?"},{"speaker":"B","zh":"在去机场的路上。你已经到了吗？","py":"Zài qù jīchǎng de lùshang. Nǐ yǐjīng dào le ma?","vi":"Đang trên đường ra sân bay. Em đến chưa?"},{"speaker":"A","zh":"我下飞机了。你还有多长时间能到这儿？","py":"Wǒ xià fēijī le. Nǐ hái yǒu duō cháng shíjiān néng dào zhèr?","vi":"Em xuống máy bay rồi. Còn bao lâu nữa anh mới đến đây?"},{"speaker":"B","zh":"二十分钟就到。","py":"Èrshí fēnzhōng jiù dào.","vi":"20 phút nữa là tới."}]},{"titleZh":"在健身房","titleVi":"Ở phòng tập thể dục","icon":"🚌","lines":[{"speaker":"A","zh":"你家离公司远吗？","py":"Nǐ jiā lí gōngsī yuǎn ma?","vi":"Nhà chị có ở xa công ty không?"},{"speaker":"B","zh":"很远，坐公共汽车要一个多小时呢！","py":"Hěn yuǎn, zuò gōnggòng qìchē yào yí ge duō xiǎoshí ne!","vi":"Rất xa, đi xe buýt phải mất hơn một tiếng đồng hồ!"},{"speaker":"A","zh":"坐公共汽车太慢了，你怎么不开车？","py":"Zuò gōnggòng qìchē tài màn le, nǐ zěnme bù kāi chē?","vi":"Đi xe buýt thì chậm quá, sao chị không lái xe?"},{"speaker":"B","zh":"开车也不快，路上车太多了！","py":"Kāi chē yě bú kuài, lùshang chē tài duō le!","vi":"Lái xe cũng chẳng nhanh được, trên đường có quá nhiều xe!"}]},{"titleZh":"在路上","titleVi":"Trên đường","icon":"🎂","lines":[{"speaker":"A","zh":"今天晚上我们一起吃饭吧，给你过生日。","py":"Jīntiān wǎnshang wǒmen yìqǐ chī fàn ba, gěi nǐ guò shēngrì.","vi":"Tối nay chúng ta cùng đi ăn cơm nhé, mừng sinh nhật bạn đó."},{"speaker":"B","zh":"今天？离我的生日还有一个多星期呢！","py":"Jīntiān? Lí wǒ de shēngrì hái yǒu yí ge duō xīngqī ne!","vi":"Hôm nay à? Còn hơn một tuần nữa mới đến sinh nhật của mình mà!"},{"speaker":"A","zh":"下个星期我要去北京，今天过吧。","py":"Xià ge xīngqī wǒ yào qù Běijīng, jīntiān guò ba.","vi":"Tuần sau mình sẽ đi Bắc Kinh nên ăn mừng hôm nay đi."},{"speaker":"B","zh":"好吧，离这儿不远有一个中国饭馆，走几分钟就到了。","py":"Hǎo ba, lí zhèr bù yuǎn yǒu yí ge Zhōngguó fànguǎn, zǒu jǐ fēnzhōng jiù dào le.","vi":"Được thôi, gần đây có một quán ăn Trung Quốc, đi bộ vài phút là tới."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Sau bài 7, học viên biết <em>hỏi và nói khoảng cách</em> bằng 离 (A 离 B 远/近), diễn tả hành động <em>vẫn còn tiếp diễn</em> bằng 还…呢 / 还没, nhấn mạnh sự việc <em>xảy ra sớm/nhanh</em> bằng 就, dùng trợ từ 呢 để xác nhận – cường điệu, đồng thời nắm chắc 13 từ vựng và 4 điểm ngữ pháp trọng tâm.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi khoảng cách: <b>你家离公司远吗？</b></li>\n        <li>Nói thời gian/phương tiện: <b>坐飞机一个半小时就到了。</b></li>\n        <li>Diễn tả còn đang làm: <b>他还在教室学习呢。</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>13 từ trọng tâm</li>\n        <li>Nơi chốn & đường: <b>教室 · 机场 · 公司 · 路</b></li>\n        <li>Phương tiện & thời gian: <b>公共汽车 · 小时</b></li>\n        <li>Tính/động từ: <b>离 · 远 · 慢 · 快 · 过 · 走 · 到</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Phó từ ngữ khí <b>还</b> (tiếp diễn / 还没)</li>\n        <li>Phó từ thời gian <b>就</b> (sớm, nhanh)</li>\n        <li>Động từ <b>离</b> (khoảng cách)</li>\n        <li>Trợ từ ngữ khí <b>呢</b> (xác nhận, cường điệu)</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm: 离 (khoảng cách) &amp; 还 / 就</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Ba mảng ứng dụng nổi bật của bài 7: dùng <em>离</em> để diễn đạt khoảng cách (A 离 B 远/近), cặp phó từ <em>还 (tiếp diễn)</em> &amp; <em>就 (sớm/nhanh)</em>, và nhóm <em>phương tiện đi lại</em> (坐…去) bổ trợ cho chủ đề bài học.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học bài 7, liên quan đến cấu trúc <em>离</em>, phủ định <em>还没</em>, vị trí của <em>就</em> và trợ từ <em>呢 / 吗</em>.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Thiếu 离 khi nói khoảng cách</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Nói khoảng cách phải dùng <b>A 离 B + 远/近</b>; không bỏ 离.</p>\n        <p class=\"strike zh\">我家公司很远。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我家离公司很远。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · 没还 ≠ 还没</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Phủ định của 还 (vẫn còn) là <b>还没(有)</b>, 还 đứng <b>trước</b> 没.</p>\n        <p class=\"strike zh\">他没还吃饭。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">他还没吃饭。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Vị trí của 就</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\"><b>就</b> là phó từ, phải đứng <b>trước động từ</b>, không đặt sau.</p>\n        <p class=\"strike zh\">二十分钟到就。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">二十分钟就到。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 4 · 呢 và 吗 dùng lẫn</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\"><b>呢</b> đặt cuối câu trần thuật để xác nhận, cường điệu; <b>吗</b> để hỏi có/không. Không dùng cả hai cùng lúc.</p>\n        <p class=\"strike zh\">医院离这儿还远呢吗？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">医院离这儿还远呢。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn gom toàn bộ bài 7 theo cách dễ nhớ: từ chủ đề, cấu trúc vàng, mẫu câu thần chú đến cách chia nhóm từ vựng.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Hỏi và nói khoảng cách, thời gian và phương tiện đi lại.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Hỏi khoảng cách<br><span class=\"syn-keyhz\">离…远吗？</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Trả lời<br><span class=\"syn-keyhz\">很远 / 不远</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Cách đi & thời gian<br><span class=\"syn-keyhz\">坐…就到</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> “Hỏi (离…远吗) → Đáp (很远/不远) → Đi thế nào, bao lâu (坐…就到)”.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">A 离 B 远/近</span></h3>\n      <p>Động từ 离 đặt giữa hai điểm A và B; phần khoảng cách (远/近/số liệu) đứng sau B.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">我家<br><small>wǒ jiā</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">离<br><small>lí</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">公司很远<br><small>gōngsī hěn yuǎn</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> <strong>离</strong> đứng giữa A và B; 远/近 hoặc số km đứng <strong>sau</strong> B.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">你家离公司远吗？</span></td><td>Hỏi khoảng cách</td></tr>\n        <tr><td><span class=\"syn-keyhz\">他还在教室学习呢。</span></td><td>Tiếp diễn</td></tr>\n        <tr><td><span class=\"syn-keyhz\">二十分钟就到。</span></td><td>Sớm / nhanh</td></tr>\n        <tr><td><span class=\"syn-keyhz\">离我的生日还有一个多星期呢！</span></td><td>Khoảng cách thời gian</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Nơi chốn & đường</td><td><span class=\"syn-keyhz\">教室 · 机场 · 公司 · 路</span></td></tr>\n        <tr><td>Phương tiện & thời gian</td><td><span class=\"syn-keyhz\">公共汽车 · 小时</span></td></tr>\n        <tr><td>Tính / động từ</td><td><span class=\"syn-keyhz\">离 · 远 · 慢 · 快 · 过 · 走 · 到</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> “Nhà <strong>cách (离)</strong> <strong>công ty (公司)</strong> rất <strong>xa (远)</strong>; đi <strong>xe buýt (公共汽车)</strong> mất hơn một <strong>tiếng (小时)</strong> vì quá <strong>chậm (慢)</strong>; đi <strong>(走)</strong> ra <strong>sân bay (机场)</strong> rồi bay thì rất <strong>nhanh (快)</strong>, hai mươi phút là <strong>tới (到)</strong>; cuối tuần <strong>mừng (过)</strong> sinh nhật ở quán gần <strong>đường (路)</strong> cạnh <strong>lớp học (教室)</strong>.”</div>\n    </div>\n  </div>"}],"cssId":"c69321c3f"},{"id":"k2v2-b08","courseId":"k2v2","order":8,"title":"Để mình suy nghĩ rồi sẽ nói cho bạn biết.","titleZh":"让我想想再告诉你。","vocab":[{"stt":1,"hanzi":"再","pinyin":"zài","hanviet":"Tái","pos":"Phó từ","meaning":"Lại, lần nữa, hãy, sẽ","comps":"再见 · 再说 · 明天再去","example":{"zh":"我明天再来。","py":"Wǒ míngtiān zài lái.","vi":"Ngày mai tôi sẽ đến nữa."}},{"stt":2,"hanzi":"让","pinyin":"ràng","hanviet":"Nhượng","pos":"Động từ","meaning":"Để, bảo, nhường","comps":"让我去 · 让他看 · 让开","example":{"zh":"老师让我看书。","py":"Lǎoshī ràng wǒ kàn shū.","vi":"Thầy giáo bảo tôi đọc sách."}},{"stt":3,"hanzi":"告诉","pinyin":"gàosu","hanviet":"Cáo tố","pos":"Động từ","meaning":"Nói cho biết, bảo","comps":"告诉我 · 告诉大家 · 告诉他","example":{"zh":"我告诉你一件事。","py":"Wǒ gàosu nǐ yí jiàn shì.","vi":"Tôi nói cho bạn biết một chuyện."}},{"stt":4,"hanzi":"等","pinyin":"děng","hanviet":"Đẳng","pos":"Động từ","meaning":"Đợi, chờ","comps":"等等我 · 等一下 · 等人","example":{"zh":"你等等我。","py":"Nǐ děngdeng wǒ.","vi":"Bạn đợi mình một lát."}},{"stt":5,"hanzi":"找","pinyin":"zhǎo","hanviet":"Trảo","pos":"Động từ","meaning":"Tìm, kiếm, thối (tiền)","comps":"找人 · 找东西 · 找钱","example":{"zh":"你在找什么？","py":"Nǐ zài zhǎo shénme?","vi":"Bạn đang tìm gì vậy?"}},{"stt":6,"hanzi":"事情","pinyin":"shìqing","hanviet":"Sự tình","pos":"Danh từ","meaning":"Sự việc, chuyện","comps":"一件事情 · 有事情 · 找事情","example":{"zh":"找大卫有什么事情吗？","py":"Zhǎo Dàwèi yǒu shénme shìqing ma?","vi":"Tìm David có chuyện gì không?"}},{"stt":7,"hanzi":"服务员","pinyin":"fúwùyuán","hanviet":"Phục vụ viên","pos":"Danh từ","meaning":"Nhân viên phục vụ","comps":"叫服务员 · 服务员！","example":{"zh":"服务员，我们要点菜。","py":"Fúwùyuán, wǒmen yào diǎn cài.","vi":"Phục vụ ơi, chúng tôi muốn gọi món."}},{"stt":8,"hanzi":"白","pinyin":"bái","hanviet":"Bạch","pos":"Tính từ","meaning":"Trắng","comps":"白衣服 · 白天 · 白色","example":{"zh":"这件白的有点儿长。","py":"Zhè jiàn bái de yǒudiǎnr cháng.","vi":"Cái màu trắng này hơi dài."}},{"stt":9,"hanzi":"黑","pinyin":"hēi","hanviet":"Hắc","pos":"Tính từ","meaning":"Đen","comps":"黑衣服 · 黑夜 · 黑色","example":{"zh":"那件黑的有点儿贵。","py":"Nà jiàn hēi de yǒudiǎnr guì.","vi":"Cái màu đen kia hơi đắt."}},{"stt":10,"hanzi":"贵","pinyin":"guì","hanviet":"Quý","pos":"Tính từ","meaning":"Đắt, mắc, quý giá","comps":"太贵了 · 很贵 · 贵重","example":{"zh":"这个手机很贵。","py":"Zhège shǒujī hěn guì.","vi":"Cái điện thoại này rất đắt."}}],"hanzi":[{"char":"再","pinyin":"zài","hanviet":"Tái","chars":["再"],"story":"Chữ Nhất (一) và chữ Quynh (冂), bên trong có bộ Thổ (土). Nghĩa là \"lại làm gì đó\" trong tương lai."},{"char":"让","pinyin":"ràng","hanviet":"Nhượng","chars":["让"],"story":"Bộ Ngôn (讠) và chữ Thượng (上). Dùng lời nói để sai khiến hoặc nhường nhịn."},{"char":"告诉","pinyin":"gàosu","hanviet":"Cáo tố","chars":["告","诉"],"story":"Cáo (告) trong thông cáo + Tố (诉) trong tố tụng. Nghĩa là truyền đạt thông tin cho ai đó."},{"char":"等","pinyin":"děng","hanviet":"Đẳng","chars":["等"],"story":"Bộ Trúc (⺮) ở trên, chữ Tự (寺 - ngôi chùa) ở dưới. Cầm gậy trúc đứng đợi trước cửa chùa."},{"char":"找","pinyin":"zhǎo","hanviet":"Trảo","chars":["找"],"story":"Bộ Thủ (扌 - cái tay) và chữ Qua (戈 - vũ khí). Dùng tay cầm vũ khí đi lùng tìm."},{"char":"事情","pinyin":"shìqing","hanviet":"Sự tình","chars":["事","情"],"story":"Sự (事) ghép với Tình (情). Từ này dùng để chỉ công việc, sự việc nói chung."},{"char":"服务员","pinyin":"fúwùyuán","hanviet":"Phục vụ viên","chars":["服","务","员"],"story":"Phục vụ (服务) + Viên (员 - người làm nghề). Người làm công việc phục vụ."},{"char":"白","pinyin":"bái","hanviet":"Bạch","chars":["白"],"story":"Chữ Bạch (白). Hình ảnh giống hạt gạo màu trắng hoặc ánh sáng ban ngày."},{"char":"黑","pinyin":"hēi","hanviet":"Hắc","chars":["黑"],"story":"Chữ Hắc (黑) bên dưới có bộ Hỏa (灬 - lửa). Ngọn lửa thiêu cháy mọi thứ thành tro đen."},{"char":"贵","pinyin":"guì","hanviet":"Quý","chars":["贵"],"story":"Ở dưới có bộ Bối (贝 - vỏ sò, tiền tệ thời xưa). Nhắc tới tiền là liên quan đến sự đắt đỏ."}],"grammar":[{"title":"Câu hỏi gợi ý với “..., 好吗?”","formula":"Câu trần thuật + <span>好吗？</span>","summary":"Dùng ở cuối câu để đề nghị, hỏi ý kiến hoặc thương lượng với người khác một cách lịch sự.","note":"<strong>Lưu ý:</strong> Câu trả lời thường là 好 / 好的 (Đồng ý) hoặc 不好 / 不行 (Không đồng ý). Trong bảng ví dụ dưới đây là câu trần thuật gốc (KĐ, PĐ) và câu hỏi gợi ý (NV).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Phó từ “再” (Lại, hãy, sẽ)","formula":"S + <span>再</span> + V + (O)","summary":"Biểu thị một hành động hoặc trạng thái sẽ lặp lại, hoặc sẽ xảy ra sau khi một điều kiện nào đó được thỏa mãn (thường trong tương lai).","note":"<strong>Lưu ý:</strong> 再 luôn đứng TRƯỚC động từ.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Câu kiêm ngữ với “让 / 叫 / 请”","formula":"S + <span>让/叫/请</span> + O1/S2 + V2","summary":"Cấu trúc này có 2 động từ. Tân ngữ của động từ 1 (thường là 让/叫/请) đồng thời là Chủ ngữ của động từ 2.","note":"<strong>Lưu ý:</strong> Dùng để diễn đạt sự sai khiến, nhờ vả, hoặc yêu cầu người khác làm gì.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Lặp lại động từ","formula":"<span>AA</span> / <span>A一A</span> / <span>ABAB</span>","summary":"Lặp lại động từ mang ý nghĩa thời gian ngắn, số lượng ít, mức độ nhẹ hoặc làm thử việc gì đó. Dùng nhiều trong khẩu ngữ.","note":"<strong>Lưu ý:</strong> Thể phủ định thường loại bỏ hình thức lặp lại (ví dụ 别看 nữa thay vì 别看看).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在教室","titleVi":"Trong lớp học","icon":"🏫","lines":[{"speaker":"A","zh":"我们下午去看电影，好吗？","py":"Wǒmen xiàwǔ qù kàn diànyǐng, hǎo ma?","vi":"Buổi chiều chúng ta đi xem phim được không?"},{"speaker":"B","zh":"今天下午我没有时间，明天下午再去吧。","py":"Jīntiān xiàwǔ wǒ méiyǒu shíjiān, míngtiān xiàwǔ zài qù ba.","vi":"Chiều nay mình không rảnh rồi, chiều mai hãy đi vậy!"},{"speaker":"A","zh":"你想看什么电影？","py":"Nǐ xiǎng kàn shénme diànyǐng?","vi":"Bạn muốn xem phim gì?"},{"speaker":"B","zh":"让我想想再告诉你。","py":"Ràng wǒ xiǎngxiang zài gàosu nǐ.","vi":"Để mình suy nghĩ rồi sẽ nói cho bạn biết."}]},{"titleZh":"在宿舍","titleVi":"Ở ký túc xá","icon":"🛏️","lines":[{"speaker":"A","zh":"外边天气很好，我们出去运动运动吧！","py":"Wàibian tiānqì hěn hǎo, wǒmen chūqu yùndòng yùndòng ba!","vi":"Bên ngoài trời rất đẹp, chúng ta ra ngoài tập thể dục một chút đi!"},{"speaker":"B","zh":"你等等我，好吗？王老师让我给大卫打个电话。","py":"Nǐ děngdeng wǒ, hǎo ma? Wáng lǎoshī ràng wǒ gěi Dàwèi dǎ ge diànhuà.","vi":"Cậu đợi mình một lát được không? Cô Vương bảo mình gọi điện cho David."},{"speaker":"A","zh":"回来再打吧。找大卫有什么事情吗？","py":"Huílai zài dǎ ba. Zhǎo Dàwèi yǒu shénme shìqing ma?","vi":"Khi nào quay về hãy gọi. Cậu tìm David có chuyện gì không?"},{"speaker":"B","zh":"听说大卫病了，我想找时间去看看他。","py":"Tīngshuō Dàwèi bìng le, wǒ xiǎng zhǎo shíjiān qù kànkan tā.","vi":"Nghe nói David bị bệnh rồi. Mình định lúc nào rảnh sẽ đi thăm."}]},{"titleZh":"在宾馆的前台","titleVi":"Tại quầy lễ tân của khách sạn","icon":"🛎️","lines":[{"speaker":"A","zh":"服务员，我房间的门打不开了。","py":"Fúwùyuán, wǒ fángjiān de mén dǎ bu kāi le.","vi":"Anh phục vụ ơi, ở phòng tôi cửa không mở được."},{"speaker":"B","zh":"您住哪个房间？","py":"Nín zhù nǎge fángjiān?","vi":"Chị ở phòng nào ạ?"},{"speaker":"A","zh":"三一七。","py":"Sān yāo qī.","vi":"317."},{"speaker":"B","zh":"好的，我叫人去看看。","py":"Hǎo de, wǒ jiào rén qù kànkan.","vi":"Dạ được, tôi sẽ gọi người đến xem."}]},{"titleZh":"在商店","titleVi":"Ở cửa hàng","icon":"👗","lines":[{"speaker":"A","zh":"你看看这几件衣服怎么样。","py":"Nǐ kànkan zhè jǐ jiàn yīfu zěnmeyàng.","vi":"Cô xem xem mấy cái đầm này thế nào."},{"speaker":"B","zh":"这件白的有点儿长，那件黑的有点儿贵。","py":"Zhè jiàn bái de yǒudiǎnr cháng, nà jiàn hēi de yǒudiǎnr guì.","vi":"Cái màu trắng này hơi dài còn cái màu đen kia hơi đắt."},{"speaker":"A","zh":"这件红的呢？这是今天新来的。","py":"Zhè jiàn hóng de ne? Zhè shì jīntiān xīn lái de.","vi":"Vậy cái màu đỏ này thì sao? Đây là hàng mới về hôm nay đấy."},{"speaker":"B","zh":"让我再看看。","py":"Ràng wǒ zài kànkan.","vi":"Để tôi xem đã."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 8 giúp học viên biết cách rủ rê người khác, đưa ra một sự chờ đợi, và sai khiến ai đó làm việc gì.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Rủ rê, gợi ý (dùng 好吗)</li>\n        <li>Nói về hành động tiếp nối (dùng 再)</li>\n        <li>Nhờ vả, bảo ai làm gì (dùng 让)</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>10 từ vựng trọng điểm</li>\n        <li>Nhóm hành động: <b>等, 找, 让, 告诉</b></li>\n        <li>Nhóm tính từ: <b>白, 黑, 贵</b></li>\n        <li>Khác: <b>再, 事情, 服务员</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Câu hỏi gợi ý <b>..., 好吗?</b></li>\n        <li>Phó từ <b>再</b> (lại, hãy)</li>\n        <li>Câu kiêm ngữ với <b>让/叫/请</b></li>\n        <li>Lặp lại động từ (V V)</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Trong bài này chúng ta học cách mô tả màu sắc quần áo, cách so sánh tính chất và hình thức lặp lại của động từ.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học từ vựng và ngữ pháp của bài này.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Vị trí của phó từ 再</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong tiếng Việt ta thường nói \"đến sau\", \"nhìn lại\". Nhưng tiếng Trung, phó từ <b>再</b> phải đứng TRƯỚC động từ.</p>\n        <p class=\"strike zh\">我明天来再。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我明天再来。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Lặp lại động từ có 2 âm tiết</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Với động từ đơn (A), ta lặp là AA hoặc A一A (看一看). Nhưng với động từ kép (AB) như 运动, 学习, ta <b>KHÔNG</b> chèn \"一\" vào giữa, mà lặp nguyên thể ABAB.</p>\n        <p class=\"strike zh\">我们出去运动一运动吧！</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我们出去运动运动吧！</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Thiếu Tân ngữ 1 trong câu kiêm ngữ</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Cấu trúc 让 / 叫 / 请 yêu cầu bắt buộc phải có đối tượng tiếp nhận (ai đó) trước hành động. Không được lược bỏ tân ngữ chỉ người.</p>\n        <p class=\"strike zh\">老师让看书。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">老师让我看书。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn, gom toàn bộ bài theo cách dễ nhớ.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Sự rủ rê, nhờ vả và trì hoãn hành động.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Rủ rê<br><span class=\"syn-keyhz\">好吗？</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Từ chối khéo<br><span class=\"syn-keyhz\">再</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Sai bảo<br><span class=\"syn-keyhz\">让 / 叫</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> Chúng ta đi chơi nhé (好吗)? Thôi để mai đi (再). Mẹ bảo mình dọn dẹp (让).</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">Câu kiêm ngữ</span></h3>\n      <p>Dùng để diễn tả một người sai bảo, yêu cầu người khác làm gì.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Ai đó<br><small>Chủ ngữ 1</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">让 / 叫<br><small>Động từ 1</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Ai đó<br><small>Tân ngữ 1</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Làm gì<br><small>Động từ 2</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> Tân ngữ 1 vừa là đối tượng bị tác động, vừa là chủ thể của hành động 2.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">让我想想再告诉你。</span></td><td>Xin hoãn lại để suy nghĩ</td></tr>\n        <tr><td><span class=\"syn-keyhz\">我们去看电影，好吗？</span></td><td>Hỏi ý kiến, rủ rê</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你看看这件怎么样。</span></td><td>Nhờ xem giúp (lặp động từ)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Sai khiến, chờ</td><td><span class=\"syn-keyhz\">让, 叫, 请, 等</span></td></tr>\n        <tr><td>Hành động</td><td><span class=\"syn-keyhz\">找, 告诉</span></td></tr>\n        <tr><td>Màu sắc, giá cả</td><td><span class=\"syn-keyhz\">白, 黑, 贵</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> Đợi (等) mình đi tìm (找) áo Trắng (白), Đen (黑) rồi bảo (告诉) bạn nhé, áo hơi đắt (贵) đấy.</div>\n    </div>\n  </div>"}],"cssId":"c69321c3f"},{"id":"k2v2-b09","courseId":"k2v2","order":9,"title":"Câu hỏi quá nhiều nên mình không làm hết.","titleZh":"题太多，我没做完。","vocab":[{"stt":1,"hanzi":"错","pinyin":"cuò","hanviet":"Thác","pos":"Tính từ","meaning":"Sai, nhầm","comps":"打错 · 写错 · 没错","example":{"zh":"你打错了。","py":"Nǐ dǎ cuò le.","vi":"Bạn gọi nhầm số rồi."}},{"stt":2,"hanzi":"从","pinyin":"cóng","hanviet":"Tòng","pos":"Giới từ","meaning":"Từ","comps":"从小 · 从而 · 从北京到上海","example":{"zh":"您从几岁开始学习跳舞？","py":"Nín cóng jǐ suì kāishǐ xuéxí tiào wǔ?","vi":"Cô bắt đầu học múa từ lúc mấy tuổi?"}},{"stt":3,"hanzi":"跳舞","pinyin":"tiàowǔ","hanviet":"Khiêu vũ","pos":"Động từ","meaning":"Múa, khiêu vũ","comps":"学跳舞 · 喜欢跳舞 · 去跳舞","example":{"zh":"我第一次跳舞是在七岁的时候。","py":"Wǒ dì yī cì tiào wǔ shì zài qī suì de shíhou.","vi":"Lần đầu tiên tôi múa là vào năm lên bảy tuổi."}},{"stt":4,"hanzi":"第一","pinyin":"dìyī","hanviet":"Đệ nhất","pos":"Số từ","meaning":"Thứ nhất, đầu tiên","comps":"第一次 · 第一个 · 第一名","example":{"zh":"这是他的第一个工作。","py":"Zhè shì tā de dì yī ge gōngzuò.","vi":"Đây là công việc đầu tiên của anh ấy."}},{"stt":5,"hanzi":"希望","pinyin":"xīwàng","hanviet":"Hi vọng","pos":"Động từ","meaning":"Mong, hy vọng","comps":"有希望 · 希望你来 · 没希望","example":{"zh":"希望他能喜欢。","py":"Xīwàng tā néng xǐhuan.","vi":"Hy vọng anh ấy sẽ thích."}},{"stt":6,"hanzi":"问题","pinyin":"wèntí","hanviet":"Vấn đề","pos":"Danh từ","meaning":"Vấn đề, câu hỏi","comps":"没问题 · 有问题 · 回答问题","example":{"zh":"没问题，非常欢迎。","py":"Méi wèntí, fēicháng huānyíng.","vi":"Không vấn đề gì, rất hoan nghênh."}},{"stt":7,"hanzi":"欢迎","pinyin":"huānyíng","hanviet":"Hoan nghênh","pos":"Động từ","meaning":"Hoan nghênh, chào đón","comps":"非常欢迎 · 不欢迎 · 欢迎你","example":{"zh":"我们欢迎你来北京。","py":"Wǒmen huānyíng nǐ lái Běijīng.","vi":"Chúng tôi hoan nghênh bạn đến Bắc Kinh."}},{"stt":8,"hanzi":"上班","pinyin":"shàngbān","hanviet":"Thượng ban","pos":"Động từ","meaning":"Đi làm","comps":"开始上班 · 去上班 · 不上班","example":{"zh":"他从什么时候开始上班？","py":"Tā cóng shénme shíhou kāishǐ shàng bān?","vi":"Anh ấy bắt đầu đi làm từ khi nào?"}},{"stt":9,"hanzi":"懂","pinyin":"dǒng","hanviet":"Đổng","pos":"Động từ","meaning":"Hiểu, biết","comps":"听懂 · 看懂 · 不懂","example":{"zh":"你都听懂了吗？","py":"Nǐ dōu tīng dǒng le ma?","vi":"Bạn đã nghe hiểu hết chưa?"}},{"stt":10,"hanzi":"完","pinyin":"wán","hanviet":"Hoàn","pos":"Động từ","meaning":"Xong, hết","comps":"做完 · 吃完 · 看完","example":{"zh":"你都做完了没有？","py":"Nǐ dōu zuò wán le méiyǒu?","vi":"Bạn đã làm xong hết chưa?"}},{"stt":11,"hanzi":"题","pinyin":"tí","hanviet":"Đề","pos":"Danh từ","meaning":"Câu hỏi, bài tập","comps":"考试题 · 做题 · 题太多","example":{"zh":"题太多，我没做完。","py":"Tí tài duō, wǒ méi zuò wán.","vi":"Câu hỏi quá nhiều nên tôi không làm xong."}}],"hanzi":[{"char":"错","pinyin":"cuò","hanviet":"Thác","chars":["错"],"story":"Hình chữ Kim (钅) và Tích (昔). Lúc xưa dùng vàng bạc đong đếm dễ sai sót nhầm lẫn."},{"char":"从","pinyin":"cóng","hanviet":"Tòng","chars":["从"],"story":"Hai chữ Nhân (人) đi theo nhau. Nghĩa gốc là đi theo sau, từ đó phái sinh nghĩa \"từ (điểm xuất phát)\"."},{"char":"跳舞","pinyin":"tiàowǔ","hanviet":"Khiêu vũ","chars":["跳","舞"],"story":"跳 (nhảy) + 舞 (múa). Động tác chân tay uyển chuyển theo nhịp điệu."},{"char":"第一","pinyin":"dìyī","hanviet":"Đệ nhất","chars":["第","一"],"story":"第 chỉ thứ tự ghép với 一 (1). Để chỉ vị trí đầu tiên trong một chuỗi."},{"char":"希望","pinyin":"xīwàng","hanviet":"Hi vọng","chars":["希","望"],"story":"希 (hiếm có) + 望 (nhìn xa). Mong mỏi một điều gì đó tốt đẹp sẽ đến ở phía trước."},{"char":"问题","pinyin":"wèntí","hanviet":"Vấn đề","chars":["问","题"],"story":"问 (hỏi) + 题 (đề tài, câu hỏi). Chỉ những điều cần được giải đáp hoặc thảo luận."},{"char":"欢迎","pinyin":"huānyíng","hanviet":"Hoan nghênh","chars":["欢","迎"],"story":"欢 (vui vẻ) + 迎 (nghênh đón). Đón tiếp người khác một cách nồng nhiệt, vui vẻ."},{"char":"上班","pinyin":"shàngbān","hanviet":"Thượng ban","chars":["上","班"],"story":"上 (lên) + 班 (ca, kíp). Bước vào hoặc bắt đầu ca làm việc của mình."},{"char":"懂","pinyin":"dǒng","hanviet":"Đổng","chars":["懂"],"story":"Bộ Tâm (忄) ở bên trái chỉ ý nghĩ. Trái tim và tâm trí đã thấu hiểu được sự việc."},{"char":"完","pinyin":"wán","hanviet":"Hoàn","chars":["完"],"story":"Bộ Miên (宀 - mái nhà) và chữ Nguyên (元). Xây xong mái nhà cửa là coi như hoàn tất công trình."},{"char":"题","pinyin":"tí","hanviet":"Đề","chars":["题"],"story":"Bộ Hiệt (页 - trang, cái đầu) biểu thị liên quan đến đầu óc suy nghĩ để giải bài."}],"grammar":[{"title":"Bổ ngữ chỉ kết quả (结果补语)","formula":"S + <span>动词 (V)</span> + <span>补语</span> + (了) + O","summary":"Dùng để nói rõ hành động đó đã đạt được kết quả thế nào. Phủ định luôn dùng <b>没(有)</b>.","note":"<strong>Lưu ý:</strong> Câu hỏi thường dùng (了)没有？ ở cuối câu.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Giới từ “从” (Từ...)","formula":"<span>从</span> + Thời gian/Địa điểm + <span>(到...)</span> + V","summary":"Biểu thị điểm xuất phát về mặt thời gian, không gian, hoặc một quá trình/trình tự.","note":"<strong>Lưu ý:</strong> \"从\" thường đi kèm với \"到\" hoặc \"开始\" (bắt đầu).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Cách diễn tả thứ tự với “第”","formula":"<span>第</span> + Số đếm + <span>Lượng từ</span> + Danh từ","summary":"Để biểu đạt số thứ tự, ta đặt 第 trước cụm số lượng từ.","note":"<strong>Lưu ý:</strong> Bắt buộc phải có Lượng từ (như 个, 次, 本...) xen giữa Số đếm và Danh từ.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"打电话","titleVi":"Gọi điện thoại","icon":"📞","lines":[{"speaker":"A","zh":"你好！请问张欢在吗？","py":"Nǐ hǎo! Qǐngwèn Zhāng Huān zài ma?","vi":"Chào chị! Xin hỏi Trương Hoan có ở đó không?"},{"speaker":"B","zh":"你打错了，我们这儿没有叫张欢的。","py":"Nǐ dǎ cuò le, wǒmen zhèr méiyǒu jiào Zhāng Huān de.","vi":"Anh gọi nhầm số rồi, ở chỗ chúng tôi không có ai tên Trương Hoan cả."},{"speaker":"A","zh":"对不起。","py":"Duìbuqǐ.","vi":"Xin lỗi chị."}]},{"titleZh":"在学校","titleVi":"Ở trường","icon":"🏫","lines":[{"speaker":"A","zh":"您从几岁开始学习跳舞？","py":"Nín cóng jǐ suì kāishǐ xuéxí tiào wǔ?","vi":"Cô bắt đầu học múa từ lúc mấy tuổi vậy?"},{"speaker":"B","zh":"我第一次跳舞是在七岁的时候。","py":"Wǒ dì yī cì tiào wǔ shì zài qī suì de shíhou.","vi":"Lần đầu tiên tôi múa là vào năm lên bảy tuổi."},{"speaker":"A","zh":"我女儿今年也七岁了。我希望她能跟您学跳舞，可以吗？","py":"Wǒ nǚ'ér jīnnián yě qī suì le. Wǒ xīwàng tā néng gēn nín xué tiào wǔ, kěyǐ ma?","vi":"Con gái tôi năm nay cũng được bảy tuổi rồi. Tôi mong là nó có thể học múa với cô, được không cô?"},{"speaker":"B","zh":"没问题，非常欢迎。","py":"Méi wèntí, fēicháng huānyíng.","vi":"Không có vấn đề gì, tôi rất hoan nghênh."}]},{"titleZh":"在家里","titleVi":"Ở nhà","icon":"🏠","lines":[{"speaker":"A","zh":"你知道吗？大卫找到工作了。","py":"Nǐ zhīdào ma? Dàwèi zhǎo dào gōngzuò le.","vi":"Chị biết không? David đã tìm được việc rồi."},{"speaker":"B","zh":"太好了！他从什么时候开始上班？","py":"Tài hǎo le! Tā cóng shénme shíhou kāishǐ shàng bān?","vi":"Tốt quá! Vậy khi nào thì nó bắt đầu đi làm?"},{"speaker":"A","zh":"从下个星期一开始。","py":"Cóng xià ge xīngqī yī kāishǐ.","vi":"Thứ hai tuần sau."},{"speaker":"B","zh":"这是他的第一个工作，希望他能喜欢。","py":"Zhè shì tā de dì yī ge gōngzuò, xīwàng tā néng xǐhuan.","vi":"Đây là công việc đầu tiên của nó, hy vọng nó sẽ thích."}]},{"titleZh":"在教室","titleVi":"Trong lớp học","icon":"🏫","lines":[{"speaker":"A","zh":"昨天的考试怎么样？你都听懂了吗？","py":"Zuótiān de kǎoshì zěnmeyàng? Nǐ dōu tīng dǒng le ma?","vi":"Bài kiểm tra hôm qua thế nào rồi? Bạn có hiểu hết những gì đã nghe không?"},{"speaker":"B","zh":"听懂了。","py":"Tīng dǒng le.","vi":"Mình hiểu hết chứ."},{"speaker":"A","zh":"你都做完了没有？","py":"Nǐ dōu zuò wán le méiyǒu?","vi":"Vậy bạn có làm hết không?"},{"speaker":"B","zh":"题太多，我没做完。","py":"Tí tài duō, wǒ méi zuò wán.","vi":"Câu hỏi quá nhiều nên mình không làm hết."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 9 giúp học viên biết cách diễn đạt kết quả của một hành động, nêu thời gian bắt đầu và nói về thứ tự.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Nói về kết quả hành động (nghe hiểu, làm xong)</li>\n        <li>Nói về thời gian/địa điểm bắt đầu (từ lúc nào, từ đâu)</li>\n        <li>Biểu đạt số thứ tự (lần đầu tiên)</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>11 từ vựng trọng điểm</li>\n        <li>Động từ: <b>跳舞, 希望, 欢迎, 上班, 懂, 完</b></li>\n        <li>Danh từ: <b>问题, 题</b></li>\n        <li>Khác: <b>错, 从, 第一</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Bổ ngữ chỉ kết quả (结果补语)</li>\n        <li>Giới từ <b>从</b> (Từ...)</li>\n        <li>Cách diễn tả số thứ tự với <b>第</b></li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Trong bài này chúng ta tập trung vào \"Bổ ngữ chỉ kết quả\" – dùng để làm rõ kết quả của một hành động, và cách biểu đạt trình tự, điểm khởi đầu.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học từ vựng và ngữ pháp của bài này.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng sai từ phủ định cho Bổ ngữ kết quả</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Vì bổ ngữ kết quả dùng để diễn tả một việc đã có kết quả/xảy ra, ta BẮT BUỘC phải dùng <b>没(有)</b> để phủ định. Không được dùng <b>不</b>.</p>\n        <p class=\"strike zh\">我不听懂他说什么。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我没听懂他说什么。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Thiếu lượng từ khi dùng 第</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong cấu trúc 第 + Số từ, phải luôn có <b>Lượng từ</b> ở giữa rồi mới đến Danh từ. Không được ráp trực tiếp số vào danh từ giống tiếng Việt.</p>\n        <p class=\"strike zh\">这是他的第一工作。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">这是他的第一个工作。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Dùng thừa \"了\" trong câu phủ định</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khi đã dùng 没(有) để phủ định bổ ngữ kết quả, cuối câu <b>KHÔNG</b> được thêm 了 nữa.</p>\n        <p class=\"strike zh\">题太多，我没做完了。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">题太多，我没做完。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn, gom toàn bộ bài theo cách dễ nhớ.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Hỏi đáp về kết quả công việc và điểm khởi đầu.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Hành động<br><span class=\"syn-keyhz\">动词</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Kết quả<br><span class=\"syn-keyhz\">完/懂/见</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Trạng thái<br><span class=\"syn-keyhz\">了 / 没</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> Làm (做) phải Xong (完), Nghe (听) phải Hiểu (懂), Tìm (找) phải Thấy (到).</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">从 A 到 B</span></h3>\n      <p>Từ một mốc (thời gian/địa điểm) này đến mốc khác.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">从<br><small>Từ</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">A<br><small>Điểm đầu</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">到<br><small>Đến</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">B<br><small>Điểm cuối</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ví dụ:</strong> 从北京到上海 (Từ Bắc Kinh đến Thượng Hải).</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">题太多，我没做完。</span></td><td>Giải thích chưa xong việc</td></tr>\n        <tr><td><span class=\"syn-keyhz\">这是我的第一个工作。</span></td><td>Nhấn mạnh lần đầu tiên</td></tr>\n        <tr><td><span class=\"syn-keyhz\">您从几岁开始？</span></td><td>Hỏi mốc thời gian bắt đầu</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Động từ chính</td><td><span class=\"syn-keyhz\">跳舞, 希望, 欢迎, 上班</span></td></tr>\n        <tr><td>Bổ ngữ kết quả</td><td><span class=\"syn-keyhz\">懂, 完, 错</span></td></tr>\n        <tr><td>Liên từ, số</td><td><span class=\"syn-keyhz\">从, 第一</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> Từ (从) lần đầu tiên (第一) Đi làm (上班) đã Mong (希望) Nghe (听) là Hiểu (懂), Làm (做) là Xong (完) chứ không Sai (错).</div>\n    </div>\n  </div>"}],"cssId":"c69321c3f"},{"id":"k2v2-b10","courseId":"k2v2","order":10,"title":"Đừng tìm nữa, điện thoại di động ở trên bàn kìa.","titleZh":"别找了，手机在桌子上呢。","vocab":[{"stt":1,"hanzi":"课","pinyin":"kè","hanviet":"Khóa","pos":"Danh từ","meaning":"Giờ học, môn học, bài học","comps":"上课 · 下课 · 汉语课","example":{"zh":"明天上午还有汉语课呢。","py":"Míngtiān shàngwǔ hái yǒu Hànyǔ kè ne.","vi":"Sáng mai còn có giờ học tiếng Trung đấy."}},{"stt":2,"hanzi":"帮助","pinyin":"bāngzhù","hanviet":"Bang trợ","pos":"Động từ","meaning":"Giúp ích, giúp đỡ","comps":"互相帮助 · 帮助别人 · 有帮助","example":{"zh":"看电视对学汉语有帮助。","py":"Kàn diànshì duì xué Hànyǔ yǒu bāngzhù.","vi":"Xem tivi có ích cho việc học tiếng Trung."}},{"stt":3,"hanzi":"别","pinyin":"bié","hanviet":"Biệt","pos":"Phó từ","meaning":"Đừng","comps":"别去 · 别说 · 别看了","example":{"zh":"别找了，手机在桌子上呢。","py":"Bié zhǎo le, shǒujī zài zhuōzi shang ne.","vi":"Đừng tìm nữa, điện thoại ở trên bàn kìa."}},{"stt":4,"hanzi":"哥哥","pinyin":"gēge","hanviet":"Ca ca","pos":"Danh từ","meaning":"Anh trai","comps":"大哥 · 我哥哥 · 哥哥和弟弟","example":{"zh":"哥哥今天中午回来吃饭。","py":"Gēge jīntiān zhōngwǔ huílai chī fàn.","vi":"Trưa nay anh trai về ăn cơm."}},{"stt":5,"hanzi":"鸡蛋","pinyin":"jīdàn","hanviet":"Kê đản","pos":"Danh từ","meaning":"Trứng gà","comps":"吃鸡蛋 · 买鸡蛋 · 一个鸡蛋","example":{"zh":"我买了鸡蛋和西瓜。","py":"Wǒ mǎi le jīdàn hé xīguā.","vi":"Tôi đã mua trứng gà và dưa hấu."}},{"stt":6,"hanzi":"西瓜","pinyin":"xīguā","hanviet":"Tây qua","pos":"Danh từ","meaning":"Dưa hấu","comps":"吃西瓜 · 大西瓜 · 买西瓜","example":{"zh":"这个西瓜很大。","py":"Zhège xīguā hěn dà.","vi":"Quả dưa hấu này rất to."}},{"stt":7,"hanzi":"正在","pinyin":"zhèngzài","hanviet":"Chính tại","pos":"Phó từ","meaning":"Đang (làm gì đó)","comps":"正在吃饭 · 正在看书 · 正在准备","example":{"zh":"妈妈正在准备午饭呢。","py":"Māma zhèngzài zhǔnbèi wǔfàn ne.","vi":"Mẹ đang chuẩn bị bữa trưa đấy."}},{"stt":8,"hanzi":"手机","pinyin":"shǒujī","hanviet":"Thủ cơ","pos":"Danh từ","meaning":"Điện thoại di động","comps":"看手机 · 买手机 · 玩手机","example":{"zh":"你看见我的手机了吗？","py":"Nǐ kànjiàn wǒ de shǒujī le ma?","vi":"Em có thấy điện thoại của anh không?"}},{"stt":9,"hanzi":"洗","pinyin":"xǐ","hanviet":"Tẩy","pos":"Động từ","meaning":"Giặt, rửa, gội","comps":"洗衣服 · 洗手 · 洗脸","example":{"zh":"那件衣服我帮你洗了。","py":"Nà jiàn yīfu wǒ bāng nǐ xǐ le.","vi":"Cái áo đó em đã giặt giúp anh rồi."}},{"stt":10,"hanzi":"准备","pinyin":"zhǔnbèi","hanviet":"Chuẩn bị","pos":"Động từ","meaning":"Chuẩn bị","comps":"准备午饭 · 准备好了 · 去准备","example":{"zh":"明天的课你都准备好了吗？","py":"Míngtiān de kè nǐ dōu zhǔnbèi hǎo le ma?","vi":"Bài ngày mai con đã chuẩn bị xong chưa?"}},{"stt":11,"hanzi":"休息","pinyin":"xiūxi","hanviet":"Hưu tức","pos":"Động từ","meaning":"Nghỉ ngơi","comps":"多休息 · 休息一下 · 去休息","example":{"zh":"医生说你要多休息。","py":"Yīshēng shuō nǐ yào duō xiūxi.","vi":"Bác sĩ nói anh phải nghỉ ngơi nhiều hơn."}}],"hanzi":[{"char":"课","pinyin":"kè","hanviet":"Khóa","chars":["课"],"story":"Bộ Ngôn (讠) và chữ Quả (果). Lời nói mang lại kết quả (kiến thức) chính là bài học."},{"char":"帮助","pinyin":"bāngzhù","hanviet":"Bang trợ","chars":["帮","助"],"story":"Chữ Bang (帮) có bộ Cân (khăn), chữ Trợ (助) có bộ Lực (sức). Dùng sức lực ra tay giúp đỡ."},{"char":"别","pinyin":"bié","hanviet":"Biệt","chars":["别"],"story":"Có bộ Đao (刀 - dao) bên phải. Dùng dao cắt đứt, ngăn cản hành động tiếp tục."},{"char":"哥哥","pinyin":"gēge","hanviet":"Ca ca","chars":["哥","哥"],"story":"Hai chữ Khả (可) xếp chồng lên nhau tạo thành chữ Ca."},{"char":"鸡蛋","pinyin":"jīdàn","hanviet":"Kê đản","chars":["鸡","蛋"],"story":"鸡 là con gà, 蛋 (đản) là trứng. Trứng của con gà."},{"char":"西瓜","pinyin":"xīguā","hanviet":"Tây qua","chars":["西","瓜"],"story":"Tây (西) là phía Tây, Qua (瓜) là quả dưa. Loại dưa có nguồn gốc từ phương Tây truyền vào."},{"char":"正在","pinyin":"zhèngzài","hanviet":"Chính tại","chars":["正","在"],"story":"Biểu thị một hành động đang xảy ra tại chính thời điểm nói. Thường đi kèm với \"呢\" ở cuối câu."},{"char":"手机","pinyin":"shǒujī","hanviet":"Thủ cơ","chars":["手","机"],"story":"手 (tay) + 机 (máy móc). Cái máy nhỏ gọn cầm trên tay."},{"char":"洗","pinyin":"xǐ","hanviet":"Tẩy","chars":["洗"],"story":"Bên trái có bộ Thủy (氵 - nước), bên phải là chữ Tiên (先). Dùng nước để làm sạch."},{"char":"准备","pinyin":"zhǔnbèi","hanviet":"Chuẩn bị","chars":["准","备"],"story":"Làm sẵn sàng các bước trước khi bắt đầu một việc gì đó."},{"char":"休息","pinyin":"xiūxi","hanviet":"Hưu tức","chars":["休","息"],"story":"Chữ Hưu (休) là người (亻) tựa vào cái cây (木) để nghỉ ngơi."}],"grammar":[{"title":"Câu cầu khiến: 别...了 / 不要...了","formula":"<span>别/不要</span> + Động từ + (Tân ngữ) + <span>了</span>","summary":"Biểu thị sự khuyên can hoặc cấm đoán làm một việc gì đó.","note":"<strong>Lưu ý:</strong> Bảng dưới đây xếp theo cấp độ: Việc nên làm (Cứ làm) · Khuyên dừng lại (Đừng làm) · Gợi ý dừng lại (Đừng làm được không).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Giới từ “对” (Đối với...)","formula":"A + <span>对</span> B + Tính từ / Động từ","summary":"Biểu thị mối quan hệ đối xử hoặc sự tác động giữa người với người, người với sự vật, sự vật với sự vật.","note":"<strong>Lưu ý:</strong> Dịch sang tiếng Việt thường là \"tốt CHO sức khỏe\", \"có ích CHO việc học\", nhưng tiếng Trung luôn dùng 对 (đối với).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在家里","titleVi":"Ở nhà","icon":"🏠","lines":[{"speaker":"A","zh":"不要看电视了，明天上午还有汉语课呢。","py":"Búyào kàn diànshì le, míngtiān shàngwǔ hái yǒu Hànyǔ kè ne.","vi":"Đừng xem tivi nữa, sáng mai các con còn có giờ học tiếng Trung Quốc đấy."},{"speaker":"B","zh":"看电视对学汉语有帮助。","py":"Kàn diànshì duì xué Hànyǔ yǒu bāngzhù.","vi":"Xem tivi cũng có ích cho việc học tiếng Trung Quốc mà."},{"speaker":"A","zh":"明天的课你都准备好了吗？","py":"Míngtiān de kè nǐ dōu zhǔnbèi hǎo le ma?","vi":"Các con đã chuẩn bị xong bài ngày mai chưa?"},{"speaker":"B","zh":"都准备好了。","py":"Dōu zhǔnbèi hǎo le.","vi":"Xong rồi ạ."}]},{"titleZh":"在医院","titleVi":"Trong bệnh viện","icon":"🏥","lines":[{"speaker":"A","zh":"别看报纸了，医生说你要多休息。","py":"Bié kàn bàozhǐ le, yīshēng shuō nǐ yào duō xiūxi.","vi":"Đừng đọc báo nữa, bác sĩ nói anh cần nghỉ ngơi nhiều hơn."},{"speaker":"B","zh":"好，不看了。给我一杯茶吧。","py":"Hǎo, bú kàn le. Gěi wǒ yì bēi chá ba.","vi":"Được rồi, anh không đọc nữa. Cho anh một ly trà đi."},{"speaker":"A","zh":"医生说吃药后两个小时不要喝茶。","py":"Yīshēng shuō chī yào hòu liǎng ge xiǎoshí búyào hē chá.","vi":"Bác sĩ nói anh không được uống trà trong vòng hai giờ sau khi uống thuốc."},{"speaker":"B","zh":"医生还说什么了？","py":"Yīshēng hái shuō shénme le?","vi":"Bác sĩ còn dặn gì nữa không?"},{"speaker":"A","zh":"医生让你听我的。","py":"Yīshēng ràng nǐ tīng wǒ de.","vi":"Bác sĩ bảo anh nghe lời em."}]},{"titleZh":"在家里","titleVi":"Ở nhà","icon":"🏠","lines":[{"speaker":"A","zh":"你怎么买了这么多东西啊？","py":"Nǐ zěnme mǎi le zhème duō dōngxi a?","vi":"Sao anh mua nhiều thứ vậy?"},{"speaker":"B","zh":"哥哥今天中午回来吃饭。","py":"Gēge jīntiān zhōngwǔ huílai chī fàn.","vi":"Trưa nay anh trai về ăn cơm."},{"speaker":"A","zh":"我看看买什么了。羊肉、鸡蛋、面条、西瓜……真不少！妈妈呢？","py":"Wǒ kànkan mǎi shénme le. Yángròu, jīdàn, miàntiáo, xīguā...... zhēn bù shǎo! Māma ne?","vi":"Để em xem anh mua gì nào. Thịt cừu, trứng gà, mì sợi, dưa hấu... Nhiều thật! Mẹ đâu rồi?"},{"speaker":"B","zh":"正在准备午饭呢！","py":"Zhèngzài zhǔnbèi wǔfàn ne!","vi":"Mẹ đang chuẩn bị bữa trưa!"}]},{"titleZh":"在家里","titleVi":"Ở nhà","icon":"🏠","lines":[{"speaker":"A","zh":"你在找什么？","py":"Nǐ zài zhǎo shénme?","vi":"Anh đang tìm gì vậy?"},{"speaker":"B","zh":"你看见我的手机了吗？白色的。","py":"Nǐ kànjiàn wǒ de shǒujī le ma? Báisè de.","vi":"Em có thấy điện thoại di động của anh không? Điện thoại màu trắng đó."},{"speaker":"A","zh":"别找了，手机在桌子上呢，电脑旁边。","py":"Bié zhǎo le, shǒujī zài zhuōzi shang ne, diànnǎo pángbiān.","vi":"Đừng tìm nữa, nó ở trên bàn kìa, bên cạnh máy vi tính."},{"speaker":"B","zh":"你看见我的衣服了吗？红色的那件。","py":"Nǐ kànjiàn wǒ de yīfu le ma? Hóngsè de nà jiàn.","vi":"Còn cái áo màu đỏ của anh, em có thấy không vậy?"},{"speaker":"A","zh":"那件衣服我帮你洗了，在外边呢。","py":"Nà jiàn yīfu wǒ bāng nǐ xǐ le, zài wàibian ne.","vi":"Em đã giặt giúp anh rồi, đang để bên ngoài."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 10 giúp học viên biết cách đưa ra lời khuyên ngăn cản, và nói về lợi ích/tác hại của một việc đối với ai đó hoặc cái gì đó.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Ngăn cản, cấm đoán (Đừng làm gì đó nữa)</li>\n        <li>Nói về mối quan hệ tác động (Cái này tốt cho cái kia)</li>\n        <li>Hỏi và chỉ vị trí đồ vật</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>11 từ vựng trọng điểm</li>\n        <li>Hành động: <b>帮助, 洗, 准备, 休息</b></li>\n        <li>Danh từ thiết yếu: <b>课, 哥哥, 鸡蛋, 西瓜, 手机</b></li>\n        <li>Từ hư/Phó từ: <b>别, 正在</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Câu cầu khiến: <b>不要/别...了</b></li>\n        <li>Giới từ <b>对</b> (đối với) chỉ sự tác động</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Trong bài này chúng ta học cách yêu cầu ai đó dừng một hành động lại, và cách diễn đạt sự tác động, ảnh hưởng của một việc đối với người hoặc vật khác.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học từ vựng và ngữ pháp của bài này.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng thiếu chữ \"了\" trong câu cấm đoán</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khi muốn khuyên ai đó <b>dừng lại</b> việc họ ĐANG làm, ta phải dùng cấu trúc <b>别 / 不要 ... 了</b>. Nếu bỏ chữ \"了\", câu sẽ mang nghĩa \"đừng làm việc đó (nói chung/trong tương lai)\".</p>\n        <p class=\"strike zh\">你别看手机！（Người đó đang bấm điện thoại）</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">你别看手机了！</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Đặt sai vị trí của giới từ \"对\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tiếng Việt nói \"Rất tốt đối với sức khỏe\". Nhưng trong tiếng Trung, cụm giới từ (对 + Tân ngữ) phải làm <b>Trạng ngữ</b> và đặt TRƯỚC Động từ / Tính từ chính.</p>\n        <p class=\"strike zh\">跑步很好对身体。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">跑步对身体很好。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Dùng sai cấu trúc đang tiếp diễn</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Để nói \"đang làm gì\", ta dùng phó từ <b>正在</b> (hoặc 正, 在) trước động từ, và thường thêm trợ từ <b>呢</b> ở cuối câu. Không được bê nguyên chữ \"đang\" tiếng Việt.</p>\n        <p class=\"strike zh\">妈妈当准备午饭。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">妈妈正在准备午饭呢。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn, gom toàn bộ bài theo cách dễ nhớ.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Khuyên răn, ngăn cản, và nói về sức khỏe/chuẩn bị.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Ngăn cản<br><span class=\"syn-keyhz\">别...了</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Giải thích<br><span class=\"syn-keyhz\">对...好</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Kết quả<br><span class=\"syn-keyhz\">多休息</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> Thấy ai làm việc xấu -> Cản lại -> Giải thích lý do tác động tốt/xấu.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">A 对 B + Adj/V</span></h3>\n      <p>Nhấn mạnh tác động, thái độ của A lên B.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">A<br><small>Hành động/Người</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">对 B<br><small>Đối tượng bị tđ</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">好/不好...<br><small>Đánh giá</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> \"对 B\" luôn phải đứng trước tính từ/động từ nhận xét.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">别找了，手机在桌子上呢。</span></td><td>Bảo ai đó dừng việc tìm kiếm</td></tr>\n        <tr><td><span class=\"syn-keyhz\">正在准备午饭呢！</span></td><td>Nói ai đó ĐANG làm gì</td></tr>\n        <tr><td><span class=\"syn-keyhz\">看电视对学汉语有帮助。</span></td><td>Nhận xét tác động tích cực</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Hành động</td><td><span class=\"syn-keyhz\">洗, 准备, 休息, 帮助</span></td></tr>\n        <tr><td>Đồ vật, thức ăn</td><td><span class=\"syn-keyhz\">手机, 鸡蛋, 西瓜</span></td></tr>\n        <tr><td>Từ nối, phó từ</td><td><span class=\"syn-keyhz\">别, 正在, 课</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> Đang (正在) Chuẩn bị (准备) Rửa (洗) Dưa hấu (西瓜) và Trứng gà (鸡蛋) cho Anh trai (哥哥), Đừng (别) Bấm điện thoại (手机) nữa, đi Nghỉ ngơi (休息) đi!</div>\n    </div>\n  </div>"}],"cssId":"cb7f9621b"},{"id":"k2v2-b11","courseId":"k2v2","order":11,"title":"Anh ấy lớn hơn mình ba tuổi.","titleZh":"他比我大三岁。","vocab":[{"stt":1,"hanzi":"唱歌","pinyin":"chàng gē","hanviet":"Xướng ca","pos":"Động từ","meaning":"Hát","comps":"喜欢唱歌 · 唱歌的人 · 去唱歌","example":{"zh":"昨天和你一起唱歌的人是谁？","py":"Zuótiān hé nǐ yìqǐ chàng gē de rén shì shéi?","vi":"Người hát cùng bạn hôm qua là ai thế?"}},{"stt":2,"hanzi":"男","pinyin":"nán","hanviet":"Nam","pos":"Tính từ","meaning":"Nam, đàn ông","comps":"男孩子 · 男朋友 · 男人","example":{"zh":"他是不是你的男朋友？","py":"Tā shì bu shì nǐ de nánpéngyou?","vi":"Anh ấy có phải là bạn trai của bạn không?"}},{"stt":3,"hanzi":"女","pinyin":"nǚ","hanviet":"Nữ","pos":"Tính từ","meaning":"Nữ, phụ nữ","comps":"女孩子 · 女朋友 · 女人","example":{"zh":"左边看报纸的女孩子是谁？","py":"Zuǒbian kàn bàozhǐ de nǚ háizi shì shéi?","vi":"Cô gái đọc báo bên tay trái là ai vậy?"}},{"stt":4,"hanzi":"孩子","pinyin":"háizi","hanviet":"Hài tử","pos":"Danh từ","meaning":"Trẻ con, con cái","comps":"男孩子 · 女孩子 · 小孩子","example":{"zh":"那个女孩子是你姐姐吗？","py":"Nàge nǚ háizi shì nǐ jiějie ma?","vi":"Cô gái đó là chị của bạn phải không?"}},{"stt":5,"hanzi":"右边","pinyin":"yòubian","hanviet":"Hữu biên","pos":"Danh từ","meaning":"Bên phải","comps":"右边的门 · 在右边 · 右手","example":{"zh":"右边写字的那个人是我哥哥。","py":"Yòubian xiě zì de nàge rén shì wǒ gēge.","vi":"Người viết chữ ở bên tay phải là anh tôi."}},{"stt":6,"hanzi":"比","pinyin":"bǐ","hanviet":"Tỷ","pos":"Giới từ","meaning":"Hơn (so sánh)","comps":"比我大 · 比昨天便宜 · 比一比","example":{"zh":"他比我大三岁。","py":"Tā bǐ wǒ dà sān suì.","vi":"Anh ấy lớn hơn tôi ba tuổi."}},{"stt":7,"hanzi":"便宜","pinyin":"piányi","hanviet":"Tiện nghi","pos":"Tính từ","meaning":"Rẻ","comps":"很便宜 · 便宜一点儿 · 太便宜了","example":{"zh":"今天的西瓜比昨天便宜。","py":"Jīntiān de xīguā bǐ zuótiān piányi.","vi":"Dưa hấu hôm nay rẻ hơn hôm qua."}},{"stt":8,"hanzi":"说话","pinyin":"shuō huà","hanviet":"Thuyết thoại","pos":"Động từ","meaning":"Nói chuyện","comps":"别说话 · 说话的人 · 和他说话","example":{"zh":"前边说话的那个人是我的老师。","py":"Qiánbian shuō huà de nàge rén shì wǒ de lǎoshī.","vi":"Người đang nói chuyện ở phía trước là giáo viên của tôi."}},{"stt":9,"hanzi":"可能","pinyin":"kěnéng","hanviet":"Khả năng","pos":"Phó/Trợ đt","meaning":"Có thể, có lẽ","comps":"不可能 · 可能会来 · 可能不认识","example":{"zh":"你可能不认识她。","py":"Nǐ kěnéng bú rènshi tā.","vi":"Có lẽ bạn không biết cô ấy."}},{"stt":10,"hanzi":"去年","pinyin":"qùnián","hanviet":"Khứ niên","pos":"Danh từ","meaning":"Năm ngoái","comps":"去年买的 · 去年来的 · 明天和去年","example":{"zh":"她是去年来的。","py":"Tā shì qùnián lái de.","vi":"Cô ấy đến vào năm ngoái."}},{"stt":11,"hanzi":"姓","pinyin":"xìng","hanviet":"Tính","pos":"Động/Danh từ","meaning":"Mang họ / Họ","comps":"姓王 · 您贵姓 · 姓名","example":{"zh":"她姓王，今年二十八岁。","py":"Tā xìng Wáng, jīnnián èrshíbā suì.","vi":"Cô ấy họ Vương, năm nay 28 tuổi."}}],"hanzi":[{"char":"唱歌","pinyin":"chàng gē","hanviet":"Xướng ca","chars":["唱","歌"],"story":"唱 có bộ Khẩu (口 - miệng). 歌 có bộ Khiếm (欠 - ngáp, há miệng). Há miệng cất lên giai điệu là hát."},{"char":"男","pinyin":"nán","hanviet":"Nam","chars":["男"],"story":"Bộ Điền (田 - ruộng) ở trên, bộ Lực (力 - sức) ở dưới. Người dùng sức cày ruộng là nam giới."},{"char":"女","pinyin":"nǚ","hanviet":"Nữ","chars":["女"],"story":"Hình dáng một người phụ nữ đang ngồi vắt chéo chân."},{"char":"孩子","pinyin":"háizi","hanviet":"Hài tử","chars":["孩","子"],"story":"孩 có bộ Tử (子) chỉ trẻ con, và chữ Hợi (亥 - giờ hợi/con lợn)."},{"char":"右边","pinyin":"yòubian","hanviet":"Hữu biên","chars":["右","边"],"story":"Chữ Hữu (右) có bộ Khẩu (口) ở dưới cái tay. Tay phải thường dùng để đưa thức ăn vào miệng."},{"char":"比","pinyin":"bǐ","hanviet":"Tỷ","chars":["比"],"story":"Hai cái thìa (匕) đặt cạnh nhau để so sánh kích thước."},{"char":"便宜","pinyin":"piányi","hanviet":"Tiện nghi","chars":["便","宜"],"story":"宜 (nghi) có bộ Miên (宀 - mái nhà) và chữ Thả (且). Đồ mua về nhà với giá hời thì rất tiện nghi."},{"char":"说话","pinyin":"shuō huà","hanviet":"Thuyết thoại","chars":["说","话"],"story":"Cả hai chữ đều có bộ Ngôn (讠) liên quan đến lời nói."},{"char":"可能","pinyin":"kěnéng","hanviet":"Khả năng","chars":["可","能"],"story":"可 (có thể) ghép với 能 (khả năng). Dự đoán một việc có khả năng xảy ra."},{"char":"去年","pinyin":"qùnián","hanviet":"Khứ niên","chars":["去","年"],"story":"去 (khứ) nghĩa là đã qua, đi qua. Năm đã qua là năm ngoái."},{"char":"姓","pinyin":"xìng","hanviet":"Tính","chars":["姓"],"story":"Bộ Nữ (女) và chữ Sinh (生). Thời xưa, họ của con cái được lấy theo người phụ nữ sinh ra nó."}],"grammar":[{"title":"Động từ / Cụm động từ làm Định ngữ","formula":"<span>Động từ/Cụm động từ</span> + <span>的</span> + Danh từ","summary":"Khi động từ hoặc cụm động từ dùng để bổ nghĩa cho danh từ, ta BẮT BUỘC phải thêm <b>的</b> vào giữa định ngữ và danh từ trung tâm.","note":"<strong>Lưu ý:</strong> Tiếng Việt nói \"Người hát\" (Danh từ trước, động từ sau). Tiếng Trung phải nói ngược lại: 唱歌的人 (Động từ + 的 + Danh từ).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Câu so sánh với “比”","formula":"A + <span>比 / 没有</span> + B + <span>Tính từ</span> + (Số lượng)","summary":"Dùng để so sánh tính chất giữa A và B. Nếu có mức chênh lệch cụ thể, số lượng phải để sau tính từ.","note":"<strong>Lưu ý:</strong> Dùng \"没有\" để nói A không bằng B.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Trợ động từ “可能” (Có thể, có lẽ)","formula":"(S) + <span>可能 / 可能不</span> + V / Mệnh đề","summary":"Biểu thị sự phỏng đoán, dự tính về một khả năng. Thường đứng trước động từ hoặc trước cả chủ ngữ.","note":"<strong>Lưu ý:</strong> Dùng khi người nói không chắc chắn 100% về sự việc.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在歌厅","titleVi":"Ở quán karaoke","icon":"🎤","lines":[{"speaker":"A","zh":"王方，昨天和你一起唱歌的人是谁？","py":"Wáng Fāng, zuótiān hé nǐ yìqǐ chàng gē de rén shì shéi?","vi":"Vương Phương, người hát cùng với cậu ngày hôm qua là ai thế?"},{"speaker":"B","zh":"一个朋友。","py":"Yí ge péngyou.","vi":"Một người bạn."},{"speaker":"A","zh":"什么朋友？是不是男朋友？","py":"Shénme péngyou? Shì bu shì nánpéngyou?","vi":"Bạn thế nào vậy? Có phải là bạn trai không?"},{"speaker":"B","zh":"不是不是，我同学介绍的，昨天第一次见。","py":"Bú shì bú shì, wǒ tóngxué jièshào de, zuótiān dì yī cì jiàn.","vi":"Không, không phải đâu. Anh ấy là người mà bạn học tớ giới thiệu. Hôm qua là lần đầu tiên tớ gặp anh ấy đấy."}]},{"titleZh":"在宿舍","titleVi":"Ở ký túc xá","icon":"🛏️","lines":[{"speaker":"A","zh":"左边这个看报纸的女孩子是你姐姐吗？","py":"Zuǒbian zhège kàn bàozhǐ de nǚ háizi shì nǐ jiějie ma?","vi":"Cô gái bên tay trái đang đọc báo là chị của cậu phải không?"},{"speaker":"B","zh":"是，右边写字的那个人是我哥哥。","py":"Shì, yòubian xiě zì de nàge rén shì wǒ gēge.","vi":"Đúng thế, còn người bên tay phải đang viết chữ là anh mình."},{"speaker":"A","zh":"你哥哥多大？","py":"Nǐ gēge duō dà?","vi":"Anh cậu bao nhiêu tuổi vậy?"},{"speaker":"B","zh":"二十五岁，他比我大三岁。","py":"Èrshíwǔ suì, tā bǐ wǒ dà sān suì.","vi":"25 tuổi, anh ấy lớn hơn mình ba tuổi."}]},{"titleZh":"在商店","titleVi":"Ở cửa hàng","icon":"🛒","lines":[{"speaker":"A","zh":"今天的西瓜怎么卖？","py":"Jīntiān de xīguā zěnme mài?","vi":"Dưa hấu hôm nay bán thế nào vậy?"},{"speaker":"B","zh":"三块五一斤。","py":"Sān kuài wǔ yì jīn.","vi":"Ba đồng năm hào nửa kí."},{"speaker":"A","zh":"比昨天便宜。","py":"Bǐ zuótiān piányi.","vi":"Vậy là rẻ hơn hôm qua."},{"speaker":"B","zh":"是，苹果也比昨天便宜一些。您来点儿吧。","py":"Shì, píngguǒ yě bǐ zuótiān piányi yìxiē. Nín lái diǎnr ba.","vi":"Vâng, táo cũng rẻ hơn hôm qua một chút. Chú mua một ít đi."}]},{"titleZh":"在学校","titleVi":"Ở trường học","icon":"🏫","lines":[{"speaker":"A","zh":"前边说话的那个人就是我的汉语老师。你可能不认识她。","py":"Qiánbian shuō huà de nàge rén jiù shì wǒ de Hànyǔ lǎoshī. Nǐ kěnéng bú rènshi tā.","vi":"Người đang nói chuyện ở phía trước chính là cô giáo dạy tớ tiếng Trung. Có lẽ cậu không biết cô ấy."},{"speaker":"B","zh":"是新来的汉语老师吗？","py":"Shì xīn lái de Hànyǔ lǎoshī ma?","vi":"Có phải đó là cô giáo dạy tiếng Trung mới đến không?"},{"speaker":"A","zh":"是去年来的，她姓王，二十八岁。","py":"Shì qùnián lái de, tā xìng Wáng, èrshíbā suì.","vi":"Cô đến vào năm ngoái, cô ấy họ Vương, 28 tuổi."},{"speaker":"B","zh":"她比我们老师小两岁。","py":"Tā bǐ wǒmen lǎoshī xiǎo liǎng suì.","vi":"Vậy là cô ấy nhỏ hơn cô giáo của bọn mình hai tuổi."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 11 giúp học viên biết cách so sánh sự khác biệt giữa hai sự vật/con người và diễn đạt cụm từ làm định ngữ.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>So sánh hơn (cao hơn, rẻ hơn, lớn hơn...)</li>\n        <li>Hỏi và nói về sự chênh lệch tuổi tác</li>\n        <li>Miêu tả đặc điểm của một người/vật cụ thể</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>11 từ vựng trọng điểm</li>\n        <li>Người & Hành động: <b>男, 女, 孩子, 唱歌, 说话, 姓</b></li>\n        <li>So sánh: <b>比, 便宜, 右边</b></li>\n        <li>Khác: <b>可能, 去年</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Cấu trúc động từ làm định ngữ (V + 的 + N)</li>\n        <li>Câu chữ <b>比</b> (so sánh hơn)</li>\n        <li>Trợ động từ <b>可能</b> (có thể, có lẽ)</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Trong bài này chúng ta tập trung vào \"Câu so sánh với 比\", dùng để so sánh đặc điểm, tính chất giữa hai đối tượng.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học câu so sánh và cụm từ làm định ngữ của bài này.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Thêm \"很\", \"非常\" vào câu chữ 比</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong câu so sánh với 比, ta <b>KHÔNG ĐƯỢC</b> thêm các phó từ chỉ mức độ tuyệt đối như 很, 非常, 特别 trước tính từ. (Chỉ được dùng 更 hoặc 还).</p>\n        <p class=\"strike zh\">今天比昨天很热。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">今天比昨天热。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Dùng \"不比\" thay vì \"没有\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khi muốn nói \"A không bằng B\", ta phải dùng <b>没有</b>. Dùng \"不比\" mang ý nghĩa phản bác \"không hẳn là hơn\", ít dùng trong giao tiếp cơ bản.</p>\n        <p class=\"strike zh\">我不比他高。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我没有他高。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Thiếu \"的\" khi động từ làm định ngữ</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khác với tiếng Việt (\"người hát\"), trong tiếng Trung, khi động từ/cụm động từ đứng trước bổ nghĩa cho danh từ, ta <b>BẮT BUỘC</b> phải thêm <b>的</b> ở giữa.</p>\n        <p class=\"strike zh\">昨天唱歌人是谁？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">昨天唱歌的人是谁？</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn, gom toàn bộ bài theo cách dễ nhớ.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Miêu tả đặc điểm và so sánh sự chênh lệch.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Miêu tả<br><span class=\"syn-keyhz\">V + 的 + N</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">So sánh<br><span class=\"syn-keyhz\">A 比 B</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Chênh lệch<br><span class=\"syn-keyhz\">Adj + Số</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> Muốn chỉ rõ \"Ai\" thì dùng <b>的</b>. Muốn cân đo đong đếm thì dùng <b>比</b>.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">A 比 B + Adj + Số lượng</span></h3>\n      <p>So sánh và đưa ra mức độ chênh lệch cụ thể.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">A 比 B<br><small>So sánh</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">大/贵...<br><small>Tính chất</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">三岁/一点儿<br><small>Chênh lệch</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> Số lượng chênh lệch luôn đứng SAU tính từ.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">他比我大三岁。</span></td><td>Nói về sự chênh lệch tuổi tác</td></tr>\n        <tr><td><span class=\"syn-keyhz\">昨天和你一起唱歌的人是谁？</span></td><td>Hỏi thăm người (dùng V + 的)</td></tr>\n        <tr><td><span class=\"syn-keyhz\">苹果也比昨天便宜一些。</span></td><td>So sánh giá cả thay đổi theo thời gian</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Con người</td><td><span class=\"syn-keyhz\">男, 女, 孩子, 姓</span></td></tr>\n        <tr><td>Hành động</td><td><span class=\"syn-keyhz\">唱歌, 说话</span></td></tr>\n        <tr><td>So sánh & Thời gian</td><td><span class=\"syn-keyhz\">比, 便宜, 去年, 可能</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> Người <b>Hát (唱歌)</b> Bên <b>phải (右边)</b> mang <b>Họ (姓)</b> Vương, anh ấy là <b>Nam (男)</b>, <b>Năm ngoái (去年)</b> Mua dưa hấu <b>Rẻ (便宜) Hơn (比) Trẻ con (孩子)</b>. <b>Có lẽ (可能)</b> là đang <b>Nói chuyện (说话)</b>.</div>\n    </div>\n  </div>"}],"cssId":"cb7f9621b"},{"id":"k2v2-b12","courseId":"k2v2","order":12,"title":"Anh mặc ít quần áo quá","titleZh":"你穿得太少了","vocab":[{"stt":1,"hanzi":"得","pinyin":"de","hanviet":"Đắc","pos":"Trợ từ kết cấu","meaning":"Được (đứng sau động từ/tính từ)","comps":"跑得快 · 做得好","example":{"zh":"他跑得很快。","py":"Tā pǎo de hěn kuài.","vi":"Anh ấy chạy rất nhanh."}},{"stt":2,"hanzi":"妻子","pinyin":"qīzi","hanviet":"Thê tử","pos":"Danh từ","meaning":"Vợ","comps":"我妻子 · 他的妻子","example":{"zh":"我妻子比我做得好。","py":"Wǒ qīzi bǐ wǒ zuò de hǎo.","vi":"Vợ tôi nấu ăn ngon hơn tôi."}},{"stt":3,"hanzi":"雪","pinyin":"xuě","hanviet":"Tuyết","pos":"Danh từ","meaning":"Tuyết","comps":"下雪 · 大雪","example":{"zh":"下雪了，今天真冷。","py":"Xià xuě le, jīntiān zhēn lěng.","vi":"Tuyết rơi rồi, hôm nay lạnh thật."}},{"stt":4,"hanzi":"零","pinyin":"líng","hanviet":"Linh","pos":"Số từ","meaning":"Số không (0)","comps":"零下 · 零度","example":{"zh":"今天零下十度。","py":"Jīntiān líng xià shí dù.","vi":"Hôm nay âm 10 độ."}},{"stt":5,"hanzi":"度","pinyin":"dù","hanviet":"Độ","pos":"Lượng từ / Danh từ","meaning":"Độ (nhiệt độ)","comps":"十度 · 零度","example":{"zh":"今天天气有三十度。","py":"Jīntiān tiānqì yǒu sānshí dù.","vi":"Thời tiết hôm nay 30 độ."}},{"stt":6,"hanzi":"穿","pinyin":"chuān","hanviet":"Xuyên","pos":"Động từ","meaning":"Mặc, mang","comps":"穿衣服 · 穿得少","example":{"zh":"你穿得太少了。","py":"Nǐ chuān de tài shǎo le.","vi":"Anh mặc ít quần áo quá."}},{"stt":7,"hanzi":"进","pinyin":"jìn","hanviet":"Tiến","pos":"Động từ","meaning":"Vào","comps":"进房间 · 进来","example":{"zh":"我们进房间吧。","py":"Wǒmen jìn fángjiān ba.","vi":"Chúng ta vào nhà đi."}},{"stt":8,"hanzi":"弟弟","pinyin":"dìdi","hanviet":"Đệ đệ","pos":"Danh từ","meaning":"Em trai","comps":"我弟弟 · 弟弟的家","example":{"zh":"我弟弟很高。","py":"Wǒ dìdi hěn gāo.","vi":"Em trai tôi rất cao."}},{"stt":9,"hanzi":"近","pinyin":"jìn","hanviet":"Cận","pos":"Tính từ","meaning":"Gần","comps":"很近 · 离得很近","example":{"zh":"他希望能住得近一点儿。","py":"Tā xīwàng néng zhù de jìn yìdiǎnr.","vi":"Cậu ấy mong có thể ở gần hơn một chút."}}],"hanzi":[{"char":"得","pinyin":"de","hanviet":"Đắc","chars":["得"],"story":"Đứng sau động từ để nối với tính từ đánh giá phía sau."},{"char":"妻子","pinyin":"qīzi","hanviet":"Thê tử","chars":["妻","子"],"story":"Chữ 妻 có bộ Nữ (女) ở dưới. Người phụ nữ trong nhà là vợ."},{"char":"雪","pinyin":"xuě","hanviet":"Tuyết","chars":["雪"],"story":"Có bộ Vũ (雨 - mưa) ở trên, phần dưới giống dấu chân. Mưa rơi đọng lại thành tuyết."},{"char":"零","pinyin":"líng","hanviet":"Linh","chars":["零"],"story":"Bộ Vũ (雨) ở trên, chữ Lệnh (令) ở dưới. Hạt mưa lạnh lẽo rơi xuống dưới không độ."},{"char":"度","pinyin":"dù","hanviet":"Độ","chars":["度"],"story":"Có bộ Nghiễm (广 - mái nhà). Nhiệt độ đo dưới mái hiên."},{"char":"穿","pinyin":"chuān","hanviet":"Xuyên","chars":["穿"],"story":"Bộ Huyệt (穴 - cái lỗ) và Nha (牙 - răng, giống con chuột). Cắn thủng lỗ để xỏ tay qua (mặc)."},{"char":"进","pinyin":"jìn","hanviet":"Tiến","chars":["进"],"story":"Bộ Xước (辶 - bước đi) và chữ Tỉnh (井 - cái giếng). Bước vào gần cái giếng."},{"char":"弟弟","pinyin":"dìdi","hanviet":"Đệ đệ","chars":["弟","弟"],"story":"Bộ Cung (弓 - cây cung). Em trai đang tập bắn cung."},{"char":"近","pinyin":"jìn","hanviet":"Cận","chars":["近"],"story":"Bộ Xước (辶) và chữ Cân (斤). Bước đi một đoạn bằng cái búa (Cân) là tới nơi = Rất gần."}],"grammar":[{"title":"Bổ ngữ chỉ trạng thái (得)","formula":"V + <span>得</span> + (不) + Adj","summary":"Được dùng để mô tả hay đánh giá kết quả, mức độ hoặc trạng thái của hành động. Nó đứng sau động từ, nối bằng <b>得</b>.","note":"<strong>Lưu ý:</strong> Từ phủ định \"不\" phải nằm <b>sau</b> \"得\", không được đặt trước động từ. Nếu có tân ngữ, phải lặp lại động từ hoặc đưa tân ngữ lên trước.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Câu chữ 比 (có bổ ngữ trạng thái)","formula":"A + <span>比</span> + B + V + <span>得</span> + Adj","summary":"Kết hợp câu so sánh <b>比</b> với bổ ngữ trạng thái để so sánh mức độ của một hành động giữa 2 đối tượng.","note":"<strong>Lưu ý:</strong> Cũng có thể nói: <b>A + V + 得 + 比 + B + Adj</b> (VD: 哥哥跑得比我快。). Phủ định ta dùng cấu trúc <b>没有</b>.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在教室","titleVi":"Trong lớp học","icon":"🏫","lines":[{"speaker":"A","zh":"你每天早上几点起床？","py":"Nǐ měitiān zǎoshang jǐ diǎn qǐchuáng?","vi":"Mỗi sáng bạn thức dậy lúc mấy giờ vậy?"},{"speaker":"B","zh":"六点多。","py":"Liù diǎn duō.","vi":"Hơn 6 giờ."},{"speaker":"A","zh":"你比我早起一个小时。","py":"Nǐ bǐ wǒ zǎo qǐ yí ge xiǎoshí.","vi":"Bạn dậy sớm hơn mình một giờ rồi."},{"speaker":"B","zh":"我睡得也早，我每天晚上十点就睡觉。早睡早起身体好。","py":"Wǒ shuì de yě zǎo, wǒ měitiān wǎnshang shí diǎn jiù shuìjiào. Zǎo shuì zǎo qǐ shēntǐ hǎo.","vi":"Mình đi ngủ cũng sớm, vào lúc 10 giờ mỗi tối. Ngủ sớm dậy sớm tốt cho sức khỏe mà."}]},{"titleZh":"在朋友家","titleVi":"Ở nhà bạn","icon":"🏠","lines":[{"speaker":"A","zh":"再来点儿米饭吧，你吃得太少了。","py":"Zài lái diǎnr mǐfàn ba, nǐ chī de tài shǎo le.","vi":"Ăn thêm chút cơm đi, anh ăn ít quá."},{"speaker":"B","zh":"不少了，今天吃得很好，太谢谢你了。","py":"Bù shǎo le, jīntiān chī de hěn hǎo, tài xièxie nǐ le.","vi":"Không ít đâu, hôm nay tôi ăn rất ngon miệng, cám ơn chị rất nhiều."},{"speaker":"A","zh":"你做饭做得怎么样？","py":"Nǐ zuò fàn zuò de zěnmeyàng?","vi":"Anh nấu ăn thế nào?"},{"speaker":"B","zh":"不怎么样，我妻子比我做得好。","py":"Bù zěnmeyàng, wǒ qīzi bǐ wǒ zuò de hǎo.","vi":"Chẳng ra làm sao, vợ tôi nấu ngon hơn tôi."}]},{"titleZh":"在家门口","titleVi":"Ở trước cửa nhà","icon":"🚪","lines":[{"speaker":"A","zh":"下雪了，今天真冷。","py":"Xià xuě le, jīntiān zhēn lěng.","vi":"Tuyết rơi rồi, hôm nay lạnh thật."},{"speaker":"B","zh":"有零下10度吧？","py":"Yǒu líng xià 10 dù ba?","vi":"Chắc là tới âm 10 độ phải không?"},{"speaker":"A","zh":"是啊，你穿得太少了，我们进房间吧。","py":"Shì a, nǐ chuān de tài shǎo le, wǒmen jìn fángjiān ba.","vi":"Đúng vậy, anh mặc ít quần áo quá, chúng ta vào nhà đi."},{"speaker":"B","zh":"好吧。","py":"Hǎo ba.","vi":"Được thôi."}]},{"titleZh":"在家里","titleVi":"Ở nhà","icon":"🛋️","lines":[{"speaker":"A","zh":"你在忙什么呢？","py":"Nǐ zài máng shénme ne?","vi":"Bạn đang bận việc gì vậy?"},{"speaker":"B","zh":"我弟弟让我帮他找个房子，现在他家离公司有点儿远。","py":"Wǒ dìdi ràng wǒ bāng tā zhǎo ge fángzi, xiànzài tā jiā lí gōngsī yǒudiǎnr yuǎn.","vi":"Cậu em trai nhờ mình tìm giúp một căn nhà, hiện giờ nhà nó hơi xa công ty."},{"speaker":"A","zh":"住得远真的很累！","py":"Zhù de yuǎn zhēn de hěn lèi!","vi":"Ở xa quả là rất mệt!"},{"speaker":"B","zh":"是啊，他也希望能住得近一点儿。","py":"Shì a, tā yě xīwàng néng zhù de jìn yīdiǎnr.","vi":"Đúng vậy, nó cũng mong có thể ở gần hơn một chút."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Nắm vững cách diễn đạt mức độ của hành động và thực hiện các phép so sánh trong sinh hoạt đời thường.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Đánh giá mức độ, trạng thái của hành động</li>\n        <li>So sánh mức độ giữa hai đối tượng</li>\n        <li>Nói về thời tiết, nhiệt độ âm</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>9 từ trọng tâm</li>\n        <li>Nhóm sinh hoạt: <b>穿, 妻子, 弟弟</b></li>\n        <li>Nhóm thời tiết: <b>雪, 零, 度</b></li>\n        <li>Nhóm vị trí: <b>近, 进</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Bổ ngữ chỉ trạng thái với <b>得</b></li>\n        <li>Câu so sánh chữ <b>比</b> mở rộng (có bổ ngữ trạng thái)</li>\n        <li>Câu hỏi lựa chọn với <b>还是</b></li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Cách diễn đạt nhiệt độ trong tiếng Trung và ngữ điệu của câu hỏi lựa chọn.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi học câu Bổ ngữ trạng thái và Câu so sánh.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Sai vị trí tân ngữ với \"得\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong tiếng Trung, tân ngữ không được đứng ngay trước <b>得</b>. Nếu có tân ngữ, phải đưa tân ngữ lên đầu hoặc lặp lại động từ.</p>\n        <p class=\"strike zh\">我说汉语得很好。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我说汉语说得很好。<br><span style=\"font-size:0.9em; font-weight:normal\">(hoặc: 汉语我说得很好。)</span></p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Dùng sai cấu trúc câu \"比\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khi kết hợp câu chữ 比 với bổ ngữ trạng thái, \"比\" phải đứng <b>trước động từ</b> hoặc <b>trước tính từ</b>. Không để ở cuối câu như tiếng Việt.</p>\n        <p class=\"strike zh\">我跑得快比他。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我比他跑得快。<br><span style=\"font-size:0.9em; font-weight:normal\">(hoặc: 我跑得比他快。)</span></p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Dùng từ \"很\" trong câu so sánh</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong câu so sánh hơn với \"比\", chúng ta <b>không được dùng \"很\", \"非常\"</b> trước tính từ.</p>\n        <p class=\"strike zh\">我比他跑得很快。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我比他跑得快。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Hệ thống lại các cấu trúc cốt lõi của bài học theo cách dễ nhớ.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Cách mô tả trạng thái, mức độ của hành động và thời tiết.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Hành động<br><span class=\"syn-keyhz\">做, 穿, 睡</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Đánh giá<br><span class=\"syn-keyhz\">得 + (Adj)</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">So sánh<br><span class=\"syn-keyhz\">比</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> Làm gì (V) ĐƯỢC (得) như thế nào (Adj).</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">得</span></h3>\n      <p>Vị trí của 得 luôn nằm sau động từ, trước tính từ đánh giá.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Khẳng định<br><small>跑 <b>得</b> 快</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Phủ định<br><small>跑 <b>得</b> 不快</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Nghi vấn<br><small>跑 <b>得</b> 快不快</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> Từ phủ định \"不\" nằm ở cụm tính từ phía sau, không đứng trước động từ.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">说得很好</span></td><td>Khen ngợi mức độ</td></tr>\n        <tr><td><span class=\"syn-keyhz\">你比我早起</span></td><td>So sánh hành động</td></tr>\n        <tr><td><span class=\"syn-keyhz\">零下十度</span></td><td>Báo nhiệt độ âm</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là giao tiếp thành thạo bài 12.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Đánh giá</td><td><span class=\"syn-keyhz\">得, 穿, 近</span></td></tr>\n        <tr><td>Gia đình</td><td><span class=\"syn-keyhz\">妻子, 弟弟</span></td></tr>\n        <tr><td>Thời tiết</td><td><span class=\"syn-keyhz\">雪, 零, 度</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> Vợ (妻子) dặn em trai (弟弟) mặc (穿) nhiều vào vì tuyết rơi (雪) âm (零下) mười độ (度).</div>\n    </div>\n  </div>"}],"cssId":"cb7f9621b"},{"id":"k2v2-b13","courseId":"k2v2","order":13,"title":"Cửa đang mở","titleZh":"门开着呢","vocab":[{"stt":1,"hanzi":"着","pinyin":"zhe","hanviet":"Trợ","pos":"Trợ từ động thái","meaning":"Đang (chỉ trạng thái duy trì)","comps":"开着 · 笑着","example":{"zh":"门开着呢。","py":"Mén kāizhe ne.","vi":"Cửa đang mở."}},{"stt":2,"hanzi":"手","pinyin":"shǒu","hanviet":"Thủ","pos":"Danh từ","meaning":"Tay","comps":"手里 · 手机","example":{"zh":"那个手里拿着铅笔的呢？","py":"Nàge shǒu lǐ názhe qiānbǐ de ne?","vi":"Còn cô gái đang cầm bút chì trong tay thì sao?"}},{"stt":3,"hanzi":"拿","pinyin":"ná","hanviet":"Nã","pos":"Động từ","meaning":"Cầm, lấy","comps":"拿着 · 拿钱","example":{"zh":"她手里拿着铅笔。","py":"Tā shǒu lǐ názhe qiānbǐ.","vi":"Trong tay cô ấy đang cầm bút chì."}},{"stt":4,"hanzi":"铅笔","pinyin":"qiānbǐ","hanviet":"Duyên bút","pos":"Danh từ","meaning":"Bút chì","comps":"一支铅笔 · 拿铅笔","example":{"zh":"我买了两支铅笔。","py":"Wǒ mǎi le liǎng zhī qiānbǐ.","vi":"Tôi đã mua hai cây bút chì."}},{"stt":5,"hanzi":"班","pinyin":"bān","hanviet":"Ban","pos":"Danh từ","meaning":"Lớp học, ca làm","comps":"我们班 · 上班","example":{"zh":"她是我们班的同学。","py":"Tā shì wǒmen bān de tóngxué.","vi":"Cô ấy là bạn học lớp chúng tôi."}},{"stt":6,"hanzi":"长","pinyin":"zhǎng","hanviet":"Trưởng","pos":"Động từ","meaning":"Sinh ra, mọc, lớn lên","comps":"长着 · 长大","example":{"zh":"她长着大眼睛。","py":"Tā zhǎngzhe dà yǎnjing.","vi":"Cô ấy có đôi mắt to."}},{"stt":7,"hanzi":"笑","pinyin":"xiào","hanviet":"Tiếu","pos":"Động từ","meaning":"Cười","comps":"爱笑 · 笑着","example":{"zh":"那个非常爱笑的女孩儿。","py":"Nàge fēicháng ài xiào de nǚháir.","vi":"Cô gái rất hay cười đó."}},{"stt":8,"hanzi":"宾馆","pinyin":"bīnguǎn","hanviet":"Tân quán","pos":"Danh từ","meaning":"Khách sạn","comps":"新京宾馆 · 去宾馆","example":{"zh":"这儿离新京宾馆远吗？","py":"Zhèr lí Xīnjīng bīnguǎn yuǎn ma?","vi":"Ở đây cách khách sạn Tân Kinh có xa không?"}},{"stt":9,"hanzi":"一直","pinyin":"yìzhí","hanviet":"Nhất trực","pos":"Phó từ","meaning":"Thẳng, liên tục","comps":"一直往前走 · 一直下雨","example":{"zh":"从这儿一直往前走。","py":"Cóng zhèr yìzhí wǎng qián zǒu.","vi":"Từ đây cứ đi thẳng về phía trước."}},{"stt":10,"hanzi":"往","pinyin":"wǎng","hanviet":"Vãng","pos":"Giới từ","meaning":"Về phía, hướng tới","comps":"往前走 · 往右看","example":{"zh":"到了路口再往右走。","py":"Dào le lùkǒu zài wǎng yòu zǒu.","vi":"Đến giao lộ thì rẽ phải (đi về bên phải)."}},{"stt":11,"hanzi":"路口","pinyin":"lùkǒu","hanviet":"Lộ khẩu","pos":"Danh từ","meaning":"Giao lộ, ngã ba/tư","comps":"前面的路口 · 十字路口","example":{"zh":"我们在路口见。","py":"Wǒmen zài lùkǒu jiàn.","vi":"Chúng ta gặp nhau ở ngã tư nhé."}},{"stt":12,"hanzi":"杨笑笑","pinyin":"Yáng Xiàoxiao","hanviet":"Dương Tiếu Tiếu","pos":"Danh từ riêng","meaning":"Dương Tiếu Tiếu (tên người)","comps":"杨笑笑 · 杨小姐","example":{"zh":"杨笑笑在门口等你。","py":"Yáng Xiàoxiao zài ménkǒu děng nǐ.","vi":"Dương Tiếu Tiếu đang đợi bạn ở cửa."}}],"hanzi":[{"char":"着","pinyin":"zhe","hanviet":"Trợ","chars":["着"],"story":"Phần trên là bộ Dương (con dê), phần dưới là bộ Mục (mắt). Con dê đang mở mắt nhìn."},{"char":"手","pinyin":"shǒu","hanviet":"Thủ","chars":["手"],"story":"Hình ảnh bàn tay với các ngón tay xòe ra."},{"char":"拿","pinyin":"ná","hanviet":"Nã","chars":["拿"],"story":"Chữ Hợp (合 - gộp lại) ở trên chữ Thủ (手 - tay). Gộp các ngón tay lại để cầm, lấy vật gì đó."},{"char":"铅笔","pinyin":"qiānbǐ","hanviet":"Duyên bút","chars":["铅","笔"],"story":"铅 (chì) + 笔 (bút có bộ Trúc, tức làm từ tre). Bút làm bằng chì."},{"char":"班","pinyin":"bān","hanviet":"Ban","chars":["班"],"story":"Hai chữ Vương (王) kẹp chữ Đao (刀) ở giữa. Ngày xưa chia ngọc làm hai nửa cho hai lớp người."},{"char":"长","pinyin":"zhǎng","hanviet":"Trưởng","chars":["长"],"story":"Chữ này có hai âm đọc (cháng: dài, zhǎng: lớn lên/mọc). Ở đây là động từ chỉ sự phát triển, sinh trưởng."},{"char":"笑","pinyin":"xiào","hanviet":"Tiếu","chars":["笑"],"story":"Bộ Trúc (竹 - tre) ở trên chữ Yêu (夭 - người trẻ). Gió thổi qua khóm tre nghe như tiếng cười của người trẻ."},{"char":"宾馆","pinyin":"bīnguǎn","hanviet":"Tân quán","chars":["宾","馆"],"story":"宾 (khách) + 馆 (quán, nơi chốn có bộ Thực 饣 liên quan đến ăn uống). Quán cho khách ở = khách sạn."},{"char":"一直","pinyin":"yìzhí","hanviet":"Nhất trực","chars":["一","直"],"story":"一 (một) + 直 (thẳng). Làm việc gì đó một mạch, thẳng tắp không dừng lại."},{"char":"往","pinyin":"wǎng","hanviet":"Vãng","chars":["往"],"story":"Bộ Xích (彳 - bước ngắn) kết hợp chữ Chủ (主). Bước chân hướng về phía người chủ."},{"char":"路口","pinyin":"lùkǒu","hanviet":"Lộ khẩu","chars":["路","口"],"story":"路 (đường) + 口 (cái miệng, lối ra vào). Miệng của con đường = ngã tư/giao lộ."}],"grammar":[{"title":"Trợ từ động thái 着 (zhe)","formula":"V + <span>着</span> + O","summary":"Động từ kết hợp với \"着\" dùng để chỉ sự kéo dài (duy trì) của một trạng thái nào đó.","note":"<strong>Lưu ý:</strong> Dạng phủ định là thêm <b>没</b> vào trước động từ, KHÔNG dùng 不.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Câu phản vấn \"不是……吗\"","formula":"<span>不是</span> + Nội dung + <span>吗？</span>","summary":"Dùng để nhắc nhở ai đó điều gì hoặc bày tỏ sự khó hiểu, thái độ không hài lòng (Chẳng phải... sao?). Đây là câu hỏi tu từ, người nói thường đã biết đáp án.","note":"<strong>Bảng dưới đây chia theo ý nghĩa:</strong> Cột Khẳng định (sự thật ban đầu), Phủ định (sự thật bị bác bỏ), và Nghi vấn (chính là Câu phản vấn dùng để nhắc nhở).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Giới từ 往 (wǎng)","formula":"<span>往</span> + Phương hướng (前/后/左/右) + V","summary":"Giới từ 往 thường được dùng để chỉ phương hướng của một hành động.","note":"<strong>Lưu ý:</strong> Cấu trúc này ngược với tiếng Việt. Trong tiếng Trung, hướng đi phải đứng trước hành động.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在办公室","titleVi":"Trong văn phòng","icon":"🏢","lines":[{"speaker":"A","zh":"门开着呢，请进。","py":"Mén kāizhe ne, qǐng jìn.","vi":"Cửa đang mở, mời vào."},{"speaker":"B","zh":"请问，张先生在吗？","py":"Qǐngwèn, Zhāng xiānsheng zài ma?","vi":"Cho tôi hỏi là ông Trương có ở đây không."},{"speaker":"A","zh":"他出去了。你下午再来吧。","py":"Tā chūqù le. Nǐ xiàwǔ zài lái ba.","vi":"Ông ấy ra ngoài rồi. Cô hãy quay lại vào buổi chiều nhé."},{"speaker":"B","zh":"好的，谢谢！","py":"Hǎo de, xièxie!","vi":"Được, cám ơn cô!"}]},{"titleZh":"在办公室","titleVi":"Trong văn phòng (2)","icon":"🏢","lines":[{"speaker":"A","zh":"那个正在说话的女孩儿是谁？","py":"Nàge zhèngzài shuōhuà de nǚháir shì shéi?","vi":"Cô gái đang nói chuyện là ai vậy?"},{"speaker":"B","zh":"我知道她的名字，她姓杨，叫杨笑笑，她姐姐是我同学。","py":"Wǒ zhīdào tā de míngzi, tā xìng Yáng, jiào Yáng Xiàoxiào, tā jiějie shì wǒ tóngxué.","vi":"Mình biết tên cô ấy. Cô ấy họ Dương, tên là Dương Tiếu Tiếu. Chị cô ấy là bạn học của mình."},{"speaker":"A","zh":"那个手里拿着铅笔的呢？","py":"Nàge shǒu lǐ názhe qiānbǐ de ne?","vi":"Còn cô gái đang cầm bút chì trong tay thì sao?"},{"speaker":"B","zh":"我不认识。","py":"Wǒ bú rènshi.","vi":"Mình không biết cô ấy."}]},{"titleZh":"在运动场","titleVi":"Ở sân vận động","icon":"⚽","lines":[{"speaker":"A","zh":"听说你有女朋友了？我认识她吗？","py":"Tīngshuō nǐ yǒu nǚpéngyou le? Wǒ rènshi tā ma?","vi":"Nghe nói cậu đã có bạn gái rồi, phải vậy không? Mình có biết cô ấy không nhỉ?"},{"speaker":"B","zh":"就是我们班那个长着两个大眼睛，非常爱笑的女孩儿。","py":"Jiù shì wǒmen bān nàge zhǎngzhe liǎng ge dà yǎnjing, fēicháng ài xiào de nǚháir.","vi":"Đó là cô gái có đôi mắt to và rất hay cười. Cô ấy học ở lớp bọn mình đấy."},{"speaker":"A","zh":"她不是有男朋友吗？","py":"Tā bú shì yǒu nánpéngyou ma?","vi":"Chẳng phải cô ấy đã có bạn trai rồi sao?"},{"speaker":"B","zh":"那个已经是她的前男友了。","py":"Nàge yǐjīng shì tā de qián nányǒu le.","vi":"Người đó là bạn trai cũ rồi."}]},{"titleZh":"在路上","titleVi":"Trên đường","icon":"🛣️","lines":[{"speaker":"A","zh":"请问，这儿离新京宾馆远吗？","py":"Qǐngwèn, zhèr lí Xīnjīng Bīnguǎn yuǎn ma?","vi":"Cho tôi hỏi là khách sạn Tân Kinh có ở xa chỗ này không."},{"speaker":"B","zh":"不远，走路二十分钟就到。","py":"Bù yuǎn, zǒulù èrshí fēnzhōng jiù dào.","vi":"Không xa đâu, đi bộ 20 phút là đến rồi."},{"speaker":"A","zh":"你能告诉我怎么走吗？","py":"Nǐ néng gàosu wǒ zěnme zǒu ma?","vi":"Anh có thể cho tôi biết đi thế nào không?"},{"speaker":"B","zh":"从这儿一直往前走，到了前面的路口再往右走。","py":"Cóng zhèr yìzhí wǎng qián zǒu, dào le qiánmiàn de lùkǒu zài wǎng yòu zǒu.","vi":"Từ đây đi thẳng về phía trước, đến giao lộ thì rẽ phải."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Nắm vững cách mô tả trạng thái của sự vật/hành động đang được duy trì và cách hỏi đường, chỉ đường cơ bản.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Mô tả trạng thái đang diễn ra và duy trì</li>\n        <li>Hỏi đường và chỉ dẫn phương hướng</li>\n        <li>Dùng câu phản vấn để xác nhận lại thông tin</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>11 từ trọng tâm</li>\n        <li>Nhóm hành động, ngoại hình: <b>拿, 笑, 长</b></li>\n        <li>Nhóm chỉ đường: <b>一直, 往, 路口, 宾馆</b></li>\n        <li>Nhóm khác: <b>手, 铅笔, 班, 着</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Trợ từ động thái <b>着</b></li>\n        <li>Giới từ <b>往</b> chỉ phương hướng</li>\n        <li>Câu hỏi phản vấn <b>不是……吗</b></li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Cách đưa ra lời khuyên, yêu cầu với ngữ điệu nhẹ nhàng và cách chỉ đường cơ bản.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi dùng trợ từ \"着\" và giới từ \"往\".</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Nhầm lẫn \"着\" và \"正在\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">\"正在\" (đang) dùng cho <b>hành động</b> đang tiếp diễn (như đang ăn, đang hát). \"着\" dùng để chỉ <b>trạng thái</b> đang được duy trì (như cửa đang mở, đang mặc áo đỏ).</p>\n        <p class=\"strike zh\">门正在开呢。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">门开着呢。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Đặt sai vị trí của \"往\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong tiếng Việt ta nói \"đi về phía phải\", động từ \"đi\" đứng trước. Nhưng trong tiếng Trung, giới từ \"往\" và phương hướng phải đứng <b>trước động từ</b>.</p>\n        <p class=\"strike zh\">走往右。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">往右走。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Lạm dụng câu phản vấn</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Cấu trúc <b>不是...吗？</b> là câu hỏi tu từ, dùng khi người nói đã biết đáp án và muốn nhắc nhở hoặc tỏ ý ngạc nhiên. Không dùng nó để hỏi thông tin mình chưa biết.</p>\n        <p class=\"strike zh\">A: 请问，那是你的书吗？<br>B: 这不是我的书吗？</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">B: 这是我的书。<br><span style=\"font-size:0.9em; font-weight:normal\">(Chỉ dùng \"这不是我的书吗？\" khi ai đó định lấy sách của bạn và bạn muốn nhắc họ).</span></p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn, gom toàn bộ bài theo cách dễ nhớ.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Trạng thái hành động, câu hỏi phản vấn và chỉ đường.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Trạng thái<br><span class=\"syn-keyhz\">开着</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Phản vấn<br><span class=\"syn-keyhz\">不是...吗</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Chỉ đường<br><span class=\"syn-keyhz\">往...走</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> Cửa đang mở (开着), chẳng phải em nói đi thẳng (一直往前走) sao (不是...吗)?</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng chỉ đường: <span class=\"syn-keyhz\">往</span></h3>\n      <p>Luôn đặt phương hướng lên trước động từ.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Giới từ<br><small>往</small></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Hướng<br><small>前 / 左 / 右</small></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Động từ<br><small>走 / 看</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> 一直往前走 (Cứ đi thẳng về phía trước).</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">门开着呢。</span></td><td>Mô tả trạng thái duy trì</td></tr>\n        <tr><td><span class=\"syn-keyhz\">她不是有男朋友吗？</span></td><td>Hỏi ngược lại (Phản vấn)</td></tr>\n        <tr><td><span class=\"syn-keyhz\">一直往前走。</span></td><td>Chỉ đường</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Trạng thái</td><td><span class=\"syn-keyhz\">拿, 笑, 长, 着</span></td></tr>\n        <tr><td>Chỉ đường</td><td><span class=\"syn-keyhz\">一直, 往, 路口, 宾馆</span></td></tr>\n        <tr><td>Danh từ</td><td><span class=\"syn-keyhz\">手, 铅笔, 班</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> Tay (手) cầm (拿) bút chì (铅笔), luôn (一直) cười (笑) đi về phía (往) khách sạn (宾馆).</div>\n    </div>\n  </div>"}],"cssId":"cb7f9621b"},{"id":"k2v2-b14","courseId":"k2v2","order":14,"title":"Cậu đã từng xem phim đó chưa?","titleZh":"你看过那个电影吗","vocab":[{"stt":1,"hanzi":"有意思","pinyin":"yǒuyìsi","hanviet":"Hữu ý tư","pos":"Tính từ","meaning":"Thú vị, hay","comps":"很有意思 · 没意思","example":{"zh":"没看过，听说很有意思。","py":"Méi kànguo, tīngshuō hěn yǒu yìsi.","vi":"Chưa xem, nghe nói rất thú vị."}},{"stt":2,"hanzi":"但是","pinyin":"dànshì","hanviet":"Đãn thị","pos":"Liên từ","meaning":"Nhưng, nhưng mà","comps":"虽然...但是...","example":{"zh":"可以，但是我女朋友也想去。","py":"Kěyǐ, dànshì wǒ nǚpéngyou yě xiǎng qù.","vi":"Được, nhưng bạn gái của mình cũng muốn đi."}},{"stt":3,"hanzi":"虽然","pinyin":"suīrán","hanviet":"Tuy nhiên","pos":"Liên từ","meaning":"Mặc dù, tuy","comps":"虽然...但是...","example":{"zh":"虽然是晴天，但是很冷。","py":"Suīrán shì qíngtiān, dànshì hěn lěng.","vi":"Dù là ngày nắng ráo nhưng trời rất lạnh."}},{"stt":4,"hanzi":"次","pinyin":"cì","hanviet":"Thứ","pos":"Lượng từ","meaning":"Lần","comps":"一次 · 好几次","example":{"zh":"买过一次。","py":"Mǎiguo yí cì.","vi":"Đã mua một lần rồi."}},{"stt":5,"hanzi":"玩儿","pinyin":"wánr","hanviet":"Ngoạn nhi","pos":"Động từ","meaning":"Chơi, đi chơi","comps":"出去玩儿 · 玩儿玩儿","example":{"zh":"但是还想再去玩儿玩儿。","py":"Dànshì hái xiǎng zài qù wánrwanr.","vi":"Nhưng em vẫn muốn đến đó chơi nữa."}},{"stt":6,"hanzi":"晴","pinyin":"qíng","hanviet":"Tình","pos":"Tính từ","meaning":"Nắng, quang đãng","comps":"晴天","example":{"zh":"虽然是晴天，但是很冷。","py":"Suīrán shì qíngtiān, dànshì hěn lěng.","vi":"Dù là ngày nắng ráo nhưng trời rất lạnh."}},{"stt":7,"hanzi":"百","pinyin":"bǎi","hanviet":"Bách","pos":"Số từ","meaning":"Trăm","comps":"一百 · 两百块","example":{"zh":"两百块还可以。","py":"Liǎng bǎi kuài hái kěyǐ.","vi":"Hai trăm đồng cũng được mà."}},{"stt":8,"hanzi":"电影院","pinyin":"diànyǐngyuàn","hanviet":"Điện ảnh viện","pos":"Danh từ","meaning":"Rạp chiếu phim","comps":"去电影院 · 在电影院","example":{"zh":"昨天我去电影院了。","py":"Zuótiān wǒ qù diànyǐngyuàn le.","vi":"Hôm qua tôi đã đi rạp chiếu phim."}},{"stt":9,"hanzi":"打电话","pinyin":"dǎ diànhuà","hanviet":"Đả điện thoại","pos":"Động từ","meaning":"Gọi điện thoại","comps":"打电话给你","example":{"zh":"到时候我给你打电话。","py":"Dào shíhou wǒ gěi nǐ dǎ diànhuà.","vi":"Đến lúc ấy em sẽ gọi điện cho anh."}},{"stt":10,"hanzi":"等","pinyin":"děng","hanviet":"Đẳng","pos":"Động từ","meaning":"Đợi, chờ","comps":"等一下 · 等我","example":{"zh":"请等一下。","py":"Qǐng děng yíxià.","vi":"Xin đợi một lát."}}],"hanzi":[{"char":"有意思","pinyin":"yǒuyìsi","hanviet":"Hữu ý tư","chars":["有","意","思"],"story":"Có ý nghĩa (ý tứ), tức là thú vị, hấp dẫn."},{"char":"但是","pinyin":"dànshì","hanviet":"Đãn thị","chars":["但","是"],"story":"Dùng để biểu thị sự chuyển ý hoặc đối lập."},{"char":"虽然","pinyin":"suīrán","hanviet":"Tuy nhiên","chars":["虽","然"],"story":"Thường kết hợp với \"但是\" để tạo thành câu nhượng bộ."},{"char":"次","pinyin":"cì","hanviet":"Thứ","chars":["次"],"story":"Bộ Băng (冫) và chữ Khiếm (欠). Dùng để đếm số lần của hành động."},{"char":"玩儿","pinyin":"wánr","hanviet":"Ngoạn nhi","chars":["玩","儿"],"story":"Chữ Vương (王 - ngọc) và chữ Nguyên (元). Cầm ngọc đi chơi."},{"char":"晴","pinyin":"qíng","hanviet":"Tình","chars":["晴"],"story":"Bộ Nhật (日 - mặt trời) chiếu sáng tạo ra màu xanh (青 - thanh) của bầu trời ráo."},{"char":"百","pinyin":"bǎi","hanviet":"Bách","chars":["百"],"story":"Chữ Nhất (一) nằm trên chữ Bạch (白). Một trăm."},{"char":"电影院","pinyin":"diànyǐngyuàn","hanviet":"Điện ảnh viện","chars":["电","影","院"],"story":"Điện ảnh (phim) chiếu ở viện (nơi chốn) = rạp chiếu phim."},{"char":"打电话","pinyin":"dǎ diànhuà","hanviet":"Đả điện thoại","chars":["打","电","话"],"story":"Dùng tay (đả) bấm điện thoại để nói chuyện."},{"char":"等","pinyin":"děng","hanviet":"Đẳng","chars":["等"],"story":"Bộ Trúc (竹 - tre) nằm trên chữ Tự (寺 - chùa). Cầm gậy tre đứng đợi ở cổng chùa."}],"grammar":[{"title":"Trợ từ động thái 过 (guò)","formula":"S + V + <span>过</span> + (O)","summary":"Động từ + \"过\" được dùng để chỉ một trải nghiệm hoặc hành động <b>đã từng xảy ra</b> trong quá khứ, nhưng không còn kéo dài đến hiện tại.","note":"<strong>Lưu ý:</strong> Dạng phủ định bắt buộc phải dùng <b>没(有)</b> đứng trước động từ.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Cấu trúc 虽然…但是… (suīrán…dànshì…)","formula":"<span>虽然</span> A，<span>但是</span> B","summary":"Cấu trúc \"Mặc dù... nhưng...\" được dùng để nối hai mệnh đề nhằm thể hiện quan hệ đối lập (nhượng bộ).","note":"<strong>Lưu ý:</strong> Dưới đây, ví dụ ở cột Khẳng định - Phủ định - Nghi vấn sẽ được xoay quanh <b>nội dung của vế sau (vế B)</b> để dễ đối chiếu.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Bổ ngữ chỉ tần suất 次 (cì)","formula":"V + 过 + <span>(Số đếm) 次</span> + O","summary":"Thường đặt sau động từ để biểu thị số lần xảy ra hoặc thực hiện một hành động.","note":"<strong>Lưu ý:</strong> Khi tân ngữ (O) là đại từ nhân xưng (我, 你, 他...), thì tân ngữ phải đặt <b>TRƯỚC</b> bổ ngữ tần suất (VD: 找过他三次).","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在教室","titleVi":"Trong lớp học","icon":"🏫","lines":[{"speaker":"A","zh":"你看过那个电影没有？","py":"Nǐ kànguo nàge diànyǐng méiyǒu?","vi":"Cậu đã từng xem phim đó chưa?"},{"speaker":"B","zh":"没看过，听说很有意思。","py":"Méi kànguo, tīngshuō hěn yǒu yìsi.","vi":"Chưa, nghe nói đây là bộ phim rất thú vị."},{"speaker":"A","zh":"那我们下个星期一起去看吧？","py":"Nà wǒmen xià ge xīngqī yìqǐ qù kàn ba?","vi":"Vậy tuần sau chúng ta cùng đi xem nhé?"},{"speaker":"B","zh":"可以，但是我女朋友也想去。","py":"Kěyǐ, dànshì wǒ nǚpéngyou yě xiǎng qù.","vi":"Được, nhưng bạn gái của mình cũng muốn đi nữa."}]},{"titleZh":"在办公室","titleVi":"Trong văn phòng","icon":"🏢","lines":[{"speaker":"A","zh":"听说你去过中国，还想去吗？","py":"Tīngshuō nǐ qùguo Zhōngguó, hái xiǎng qù ma?","vi":"Nghe nói em đã từng đi Trung Quốc. Em có muốn đi nữa không?"},{"speaker":"B","zh":"我虽然去过好几次，但是还想再去玩儿玩儿。","py":"Wǒ suīrán qùguo hǎojǐ cì, dànshì hái xiǎng zài qù wánrwanr.","vi":"Dù đã từng đi nhiều lần rồi nhưng em vẫn muốn đến đó chơi nữa."},{"speaker":"A","zh":"那我们一起去吧。","py":"Nà wǒmen yìqǐ qù ba.","vi":"Vậy chúng ta cùng đi nhé."},{"speaker":"B","zh":"好啊，到时候我给你打电话。","py":"Hǎo a, dào shíhou wǒ gěi nǐ dǎ diànhuà.","vi":"Được rồi, đến lúc ấy em sẽ gọi điện cho anh."}]},{"titleZh":"在房间","titleVi":"Trong phòng","icon":"🛋️","lines":[{"speaker":"A","zh":"明天天气怎么样？","py":"Míngtiān tiānqì zěnmeyàng?","vi":"Ngày mai thời tiết thế nào?"},{"speaker":"B","zh":"虽然是晴天，但是很冷。","py":"Suīrán shì qíngtiān, dànshì hěn lěng.","vi":"Dù là ngày nắng ráo nhưng trời rất lạnh đấy."},{"speaker":"A","zh":"那还能去跑步吗？","py":"Nà hái néng qù pǎo bù ma?","vi":"Vậy thì ra ngoài chạy bộ có được không?"},{"speaker":"B","zh":"可以，但是你自己去吧，我还有很多事情要做。","py":"Kěyǐ, dànshì nǐ zìjǐ qù ba, wǒ hái yǒu hěn duō shìqing yào zuò.","vi":"Được, nhưng anh đi một mình nhé, em còn rất nhiều việc phải làm."}]},{"titleZh":"在商店","titleVi":"Ở cửa hàng","icon":"🛒","lines":[{"speaker":"A","zh":"你在这个商店买过东西没有？","py":"Nǐ zài zhège shāngdiàn mǎiguo dōngxi méiyǒu?","vi":"Anh đã từng mua đồ ở cửa hàng này chưa?"},{"speaker":"B","zh":"买过一次，这儿的东西还可以，就是不便宜。","py":"Mǎiguo yí cì, zhèr de dōngxi hái kěyǐ, jiùshì bù piányi.","vi":"Đã mua một lần rồi, đồ ở đây cũng được nhưng giá không rẻ đâu."},{"speaker":"A","zh":"我喜欢这件衣服，但是觉得有点儿贵。","py":"Wǒ xǐhuan zhè jiàn yīfu, dànshì juéde yǒudiǎnr guì.","vi":"Em thích chiếc áo này nhưng thấy nó hơi đắt."},{"speaker":"B","zh":"两百块还可以，喜欢就买吧。","py":"Liǎng bǎi kuài hái kěyǐ, xǐhuan jiù mǎi ba.","vi":"Hai trăm đồng cũng được mà, nếu em thích thì mua đi."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Nắm vững cách nói về những trải nghiệm trong quá khứ, chỉ số lần thực hiện hành động và cách thể hiện sự nhượng bộ.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Nói về những việc đã từng trải qua</li>\n        <li>Hỏi đáp về số lần thực hiện một hành động</li>\n        <li>Thể hiện sự đối lập, nhượng bộ</li>\n        <li>Biểu đạt ngữ điệu cảm thán</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li>10 từ trọng tâm</li>\n        <li>Nhóm giải trí: <b>电影院, 玩儿, 有意思</b></li>\n        <li>Nhóm liên từ: <b>虽然, 但是</b></li>\n        <li>Lượng từ: <b>次, 百</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Trợ từ động thái <b>过</b> (chỉ kinh nghiệm)</li>\n        <li>Cấu trúc <b>虽然…但是…</b> (mặc dù... nhưng...)</li>\n        <li>Bổ ngữ chỉ tần suất <b>次</b> (lần)</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Cách thể hiện cảm xúc trong tiếng Trung và tìm hiểu về các bộ thủ quan trọng.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Các lỗi điển hình của người Việt khi diễn tả trải nghiệm và tần suất.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng sai dạng phủ định của \"过\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Để nói \"chưa từng làm gì\", ta phải dùng <b>没(有)</b> đứng trước động từ, tuyệt đối không dùng <b>不</b>.</p>\n        <p class=\"strike zh\">我不去过中国。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我没去过中国。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Sai vị trí bổ ngữ tần suất \"次\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khi tân ngữ là <b>đại từ nhân xưng</b> (我, 你, 他...), số lần (次) bắt buộc phải nằm <b>sau</b> tân ngữ.</p>\n        <p class=\"strike zh\">我找过三次他。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我找过他三次。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Thiếu hoặc đặt sai cặp liên từ</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Trong cấu trúc nhượng bộ, \"虽然\" và \"但是\" thường đi thành cặp và đứng ở đầu mỗi phân câu hoặc ngay sau chủ ngữ.</p>\n        <p class=\"strike zh\">但是我没钱，虽然我想买。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">虽然我想买，但是我没钱。<br><span style=\"font-size:0.9em; font-weight:normal\">(hoặc: 我虽然想买，但是没钱。)</span></p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Sơ đồ ngắn gọn, gom toàn bộ bài theo cách dễ nhớ.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">🎯</div>\n      <h3>Chủ đề bài học</h3>\n      <p>Kinh nghiệm trong quá khứ, tần suất hành động và sự nhượng bộ.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Kinh nghiệm<br><span class=\"syn-keyhz\">过</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Số lần<br><span class=\"syn-keyhz\">次</span></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Nhượng bộ<br><span class=\"syn-keyhz\">虽然...但是...</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> Mặc dù (虽然) đã đi chơi hàng trăm (百) lần (次), nhưng (但是) vẫn thấy rạp chiếu phim thú vị (有意思).</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🔑</div>\n      <h3>Cấu trúc vàng: <span class=\"syn-keyhz\">过</span></h3>\n      <p>Nhấn mạnh trải nghiệm đã từng xảy ra (không kéo dài đến hiện tại).</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Khẳng định<br><small>看 <b>过</b> 电影</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Phủ định<br><small><b>没</b> 看 <b>过</b></small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Nghi vấn<br><small>看 <b>过</b> <b>没有？</b></small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Lưu ý:</strong> Phủ định bắt buộc phải dùng 没(有).</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Câu thần chú</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Tình huống</th></tr>\n        <tr><td><span class=\"syn-keyhz\">没看过。</span></td><td>Chưa từng làm gì</td></tr>\n        <tr><td><span class=\"syn-keyhz\">买过一次。</span></td><td>Số lần thực hiện hành động</td></tr>\n        <tr><td><span class=\"syn-keyhz\">虽然...但是...</span></td><td>Mặc dù... nhưng...</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Thuộc các mẫu này là nắm chắc bài.</strong></div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">📦</div>\n      <h3>Từ vựng — chia nhóm</h3>\n      <table class=\"syn-table\">\n        <tr><th>Nhóm</th><th>Từ</th></tr>\n        <tr><td>Giải trí</td><td><span class=\"syn-keyhz\">玩儿, 电影院, 有意思</span></td></tr>\n        <tr><td>Liên từ</td><td><span class=\"syn-keyhz\">虽然, 但是</span></td></tr>\n        <tr><td>Hành động</td><td><span class=\"syn-keyhz\">打电话, 等</span></td></tr>\n        <tr><td>Lượng/Số</td><td><span class=\"syn-keyhz\">次, 百</span></td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mnemonic:</strong> Đợi (等) trời nắng (晴) rồi gọi điện (打电话) rủ đi rạp chiếu phim (电影院).</div>\n    </div>\n  </div>"}],"cssId":"cb7f9621b"},{"id":"k2v2-b15","courseId":"k2v2","order":15,"title":"Năm mới sắp đến rồi","titleZh":"新年就要到了","vocab":[{"stt":1,"hanzi":"日","pinyin":"rì","hanviet":"Nhật","pos":"Danh từ","meaning":"Ngày","comps":"日子 · 几月几日","example":{"zh":"今天是八号也是八日。","py":"Jīntiān shì bā hào yě shì bā rì.","vi":"Hôm nay là mùng 8 cũng là ngày 8."}},{"stt":2,"hanzi":"新年","pinyin":"xīnnián","hanviet":"Tân niên","pos":"Danh từ","meaning":"Năm mới, Tết","comps":"过新年 · 新年好","example":{"zh":"新年你准备做什么？","py":"Xīnnián nǐ zhǔnbèi zuò shénme?","vi":"Năm mới bạn chuẩn bị làm gì?"}},{"stt":3,"hanzi":"票","pinyin":"piào","hanviet":"Phiếu","pos":"Danh từ","meaning":"Vé","comps":"买票 · 车票 · 电影票","example":{"zh":"你买票了吗？","py":"Nǐ mǎi piào le ma?","vi":"Bạn đã mua vé chưa?"}},{"stt":4,"hanzi":"火车站","pinyin":"huǒchēzhàn","hanviet":"Hỏa xa trạm","pos":"Danh từ","meaning":"Ga tàu hỏa","comps":"去火车站","example":{"zh":"明天就去火车站买票。","py":"Míngtiān jiù qù huǒchēzhàn mǎi piào.","vi":"Ngày mai sẽ đi ga tàu hỏa mua vé."}},{"stt":5,"hanzi":"大家","pinyin":"dàjiā","hanviet":"Đại gia","pos":"Đại từ","meaning":"Mọi người","comps":"大家好 · 谢谢大家","example":{"zh":"谢谢大家对我的帮助！","py":"Xièxie dàjiā duì wǒ de bāngzhù!","vi":"Cảm ơn sự giúp đỡ của mọi người đối với tôi!"}},{"stt":6,"hanzi":"更","pinyin":"gèng","hanviet":"Cánh","pos":"Phó từ","meaning":"Càng, hơn nữa","comps":"更好 · 更多","example":{"zh":"希望我们的公司明年更好！","py":"Xīwàng wǒmen de gōngsī míngnián gèng hǎo!","vi":"Hy vọng công ty chúng ta sang năm tốt hơn!"}},{"stt":7,"hanzi":"妹妹","pinyin":"mèimei","hanviet":"Muội muội","pos":"Danh từ","meaning":"Em gái","comps":"小妹妹 · 我妹妹","example":{"zh":"你妹妹怎么还没来？","py":"Nǐ mèimei zěnme hái méi lái?","vi":"Em gái bạn sao còn chưa đến?"}},{"stt":8,"hanzi":"阴","pinyin":"yīn","hanviet":"Âm","pos":"Tính từ","meaning":"U ám, nhiều mây","comps":"阴天","example":{"zh":"天阴了，我要回去了。","py":"Tiān yīn le, wǒ yào huíqù le.","vi":"Trời âm u rồi, tôi phải về đây."}}],"hanzi":[{"char":"日","pinyin":"rì","hanviet":"Nhật","chars":["日"],"story":"Chữ tượng hình, ban đầu vẽ hình mặt trời. Sau dùng để chỉ ngày."},{"char":"新年","pinyin":"xīnnián","hanviet":"Tân niên","chars":["新","年"],"story":"新 (mới) ghép với 年 (năm) -> Năm mới."},{"char":"票","pinyin":"piào","hanviet":"Phiếu","chars":["票"],"story":"Gồm bộ Tây (mũ trùm) ở trên bộ Thị (chỉ). Chỉ tấm vé, phiếu."},{"char":"火车站","pinyin":"huǒchēzhàn","hanviet":"Hỏa xa trạm","chars":["火","车","站"],"story":"火 (lửa) + 车 (xe) = tàu hỏa. Cộng thêm 站 (trạm, bến)."},{"char":"大家","pinyin":"dàjiā","hanviet":"Đại gia","chars":["大","家"],"story":"大 (lớn) + 家 (nhà). Nhà lớn đại diện cho tập thể, mọi người."},{"char":"更","pinyin":"gèng","hanviet":"Cánh","chars":["更"],"story":"Bộ Viết (nói). Biểu thị mức độ tăng thêm của sự vật/sự việc."},{"char":"妹妹","pinyin":"mèimei","hanviet":"Muội muội","chars":["妹","妹"],"story":"Bộ Nữ (phụ nữ) + chữ Vị (chưa tới/nhỏ). Người con gái nhỏ hơn mình là em gái."},{"char":"阴","pinyin":"yīn","hanviet":"Âm","chars":["阴"],"story":"Bộ Phụ (đống đất/núi) + chữ Nguyệt (mặt trăng). Che khuất ánh sáng -> Âm u."}],"grammar":[{"title":"Trạng thái của hành động (Sắp... rồi)","formula":"S + <span>快要 / 就要</span> + V + 了","summary":"Dùng <b>快要 / 快 / 就要 / 要... 了</b> để biểu thị một sự việc sắp xảy ra. Dạng phủ định thường là \"vẫn chưa\" (还没...呢).","note":"<strong>Lưu ý:</strong> Nếu trong câu có trạng ngữ chỉ thời gian (như 明天, 下个月), chỉ được dùng <b>就要...了</b>.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]},{"title":"Cấu trúc \"都...了\" (Đã... rồi)","formula":"S + <span>都</span> + Thời gian/Số lượng + <span>了</span>","summary":"Dùng <b>都...了</b> để diễn đạt ý nghĩa \"đã... rồi\". Cấu trúc này thường mang ngữ khí nhấn mạnh, cảm thán hoặc phàn nàn (như thấy thời gian trôi nhanh, đợi quá lâu...). Dạng phủ định là \"vẫn chưa\" (还没).","note":"<strong>Lưu ý:</strong> Từ 都 (dōu) đứng trước thời gian, số lượng. Bắt buộc phải có chữ <b>了</b> ở cuối câu.","examples":[{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""},{"zh":"","py":"","vi":""}]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"在朋友家","titleVi":"Ở nhà bạn","icon":"🏠","lines":[{"speaker":"A","zh":"今天是12月20日，新年就要到了。","py":"Jīntiān shì shí'èr yuè èrshí rì, xīnnián jiùyào dào le.","vi":"Hôm nay là ngày 20 tháng 12, năm mới sắp đến rồi."},{"speaker":"B","zh":"新年你准备做什么？","py":"Xīnnián nǐ zhǔnbèi zuò shénme?","vi":"Năm mới bạn định làm gì?"},{"speaker":"A","zh":"我想去北京旅游，北京很不错，我去过一次。","py":"Wǒ xiǎng qù Běijīng lǚyóu, Běijīng hěn búcuò, wǒ qùguo yí cì.","vi":"Mình muốn đi du lịch ở Bắc Kinh. Bắc Kinh rất tuyệt, mình từng đến đó một lần."},{"speaker":"B","zh":"你买票了吗？","py":"Nǐ mǎi piào le ma?","vi":"Bạn đã mua vé chưa?"},{"speaker":"A","zh":"还没有呢，明天就去火车站买票。","py":"Hái méiyǒu ne, míngtiān jiù qù huǒchēzhàn mǎi piào.","vi":"Chưa, ngày mai mình sẽ đến ga tàu hỏa để mua."}]},{"titleZh":"在公司","titleVi":"Trong công ty","icon":"🏢","lines":[{"speaker":"A","zh":"时间过得真快，新的一年快要到了！","py":"Shíjiān guò de zhēn kuài, xīn de yì nián kuàiyào dào le!","vi":"Thời gian trôi qua nhanh thật, năm mới sắp đến rồi!"},{"speaker":"B","zh":"是啊，谢谢大家这一年对我的帮助！","py":"Shì a, xièxie dàjiā zhè yì nián duì wǒ de bāngzhù!","vi":"Đúng vậy, cám ơn mọi người vì đã giúp đỡ tôi trong suốt năm nay!"},{"speaker":"C","zh":"希望我们的公司明年更好！","py":"Xīwàng wǒmen de gōngsī míngnián gèng hǎo!","vi":"Hy vọng sang năm công ty của chúng ta sẽ phát triển hơn nữa!"}]},{"titleZh":"在车站","titleVi":"Tại bến xe","icon":"🚉","lines":[{"speaker":"A","zh":"你妹妹怎么还没来？都八点四十了！","py":"Nǐ mèimei zěnme hái méi lái? Dōu bā diǎn sìshí le!","vi":"Em gái của em sao vẫn chưa đến vậy? Đã 8 giờ 40 phút rồi!"},{"speaker":"B","zh":"我们再等她几分钟吧。","py":"Wǒmen zài děng tā jǐ fēnzhōng ba.","vi":"Chúng ta đợi em ấy vài phút nữa đi."},{"speaker":"A","zh":"都等她半个小时了！","py":"Dōu děng tā bàn ge xiǎoshí le!","vi":"Đã đợi nửa giờ đồng hồ rồi!"},{"speaker":"B","zh":"她来了，我听见她说话了。","py":"Tā lái le, wǒ tīngjiàn tā shuō huà le.","vi":"Em ấy đến rồi, em nghe thấy tiếng nói rồi."}]},{"titleZh":"在咖啡馆门口","titleVi":"Trước quán cà phê","icon":"☕","lines":[{"speaker":"A","zh":"天阴了，我要回去了。","py":"Tiān yīn le, wǒ yào huíqù le.","vi":"Trời u ám rồi, anh phải về đây."},{"speaker":"B","zh":"好的。快要下雨了，你路上慢点儿。","py":"Hǎo de. Kuàiyào xià yǔ le, nǐ lùshang màn diǎnr.","vi":"Vâng. Trời sắp mưa rồi đó. Trên đường, anh đi chậm thôi nhé."},{"speaker":"A","zh":"没关系，我坐公共汽车。","py":"Méi guānxi, wǒ zuò gōnggòng qìchē.","vi":"Không sao đâu, anh sẽ đi xe buýt."},{"speaker":"B","zh":"好的。再见。","py":"Hǎo de. Zàijiàn.","vi":"Vậy thì tốt. Tạm biệt."}]}]},"extra":[{"label":"Mục tiêu","html":"<h2 class=\"section-title\">Mục tiêu bài học</h2>\n  <p class=\"section-sub\">Bài 15 giúp học viên nắm vững cách nói về sự việc sắp diễn ra và văn hóa Tết Âm lịch của Trung Quốc.</p>\n  <div class=\"goal-grid\">\n    <div class=\"goal-item\">\n      <div class=\"num\">01</div>\n      <h4>Giao tiếp</h4>\n      <ul>\n        <li>Hỏi đáp về các dự định trong <b>năm mới</b>.</li>\n        <li>Thông báo một sự việc <b>sắp sửa</b> diễn ra.</li>\n        <li>Thể hiện sự <b>ngạc nhiên hoặc than phiền</b> về thời gian đã trôi qua nhanh.</li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">02</div>\n      <h4>Từ vựng</h4>\n      <ul>\n        <li><b>8</b> từ trọng tâm thuộc HSK 2.</li>\n        <li>Nhóm 1: Thời gian <b>(日, 新年)</b></li>\n        <li>Nhóm 2: Phương tiện/Địa điểm <b>(票, 火车站)</b></li>\n        <li>Nhóm 3: Mức độ <b>(更)</b></li>\n      </ul>\n    </div>\n    <div class=\"goal-item\">\n      <div class=\"num\">03</div>\n      <h4>Ngữ pháp</h4>\n      <ul>\n        <li>Cấu trúc thông báo <b>快要 / 就要... 了</b> (sắp... rồi).</li>\n        <li>Sự khác biệt khi có <b>thời gian cụ thể</b>.</li>\n        <li>Cấu trúc nhấn mạnh <b>都... 了</b> (đã... rồi).</li>\n      </ul>\n    </div>\n  </div>"},{"label":"Kiến thức trọng tâm","html":"<h2 class=\"section-title\" id=\"focus-title\">Kiến thức trọng tâm</h2>\n  <p class=\"section-sub\" id=\"focus-sub\">Phân biệt cấu trúc \"Sắp... rồi\" và nét văn hóa Tết Âm Lịch (春节) của người Trung Quốc.</p>\n  <div id=\"focus-container\"></div>"},{"label":"Lỗi sai","html":"<h2 class=\"section-title\">Lỗi sai thường gặp</h2>\n  <p class=\"section-sub\">Những lỗi người học thường mắc phải khi biểu đạt sự việc sắp diễn ra.</p>\n  <div class=\"error-grid\">\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 1 · Dùng sai \"快要...了\" với thời gian cụ thể</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Khi trong câu <b>đã có mốc thời gian cụ thể</b> (như: ngày mai, tháng sau, 8 giờ...), bạn KHÔNG ĐƯỢC dùng \"快要\", mà phải dùng <b>\"就要\"</b>.</p>\n        <p class=\"strike zh\">明天我快要回国了。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">明天我就要回国了。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 2 · Thiếu trợ từ \"了\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Cấu trúc báo hiệu sự thay đổi/sự việc sắp xảy ra là một cụm cố định \"要/快要/就要 ... <b>了</b>\". Thiếu \"了\" ở cuối câu, câu sẽ bị sai ngữ pháp hoàn toàn.</p>\n        <p class=\"strike zh\">电影快要开始。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">电影快要开始了。</p>\n      </div>\n    </div>\n    <div class=\"error-box\">\n      <div class=\"err-head wrong\">Lỗi 3 · Thiếu \"了\" trong cấu trúc \"都...了\"</div>\n      <div class=\"err-body\">\n        <p style=\"margin-bottom:12px\">Tương tự, cấu trúc \"都...了\" (đã... rồi) dùng để nhấn mạnh thời gian hoặc số lượng. Chữ \"了\" đứng cuối để tạo thành cặp hô ứng bắt buộc.</p>\n        <p class=\"strike zh\">我都等她半个小时。</p>\n      </div>\n      <div class=\"err-head correct\">Cách sửa</div>\n      <div class=\"err-body\">\n        <p class=\"correct-text zh\">我都等她半个小时了。</p>\n      </div>\n    </div>\n  </div>"},{"label":"Tổng hợp","html":"<h2 class=\"section-title\">Tổng hợp kiến thức</h2>\n  <p class=\"section-sub\">Tóm tắt các mẫu câu biểu đạt về mặt thời gian nhanh/chậm trong Bài 15.</p>\n\n  <div class=\"syn-grid\">\n    <div class=\"syn-card theme-burgundy\">\n      <div class=\"syn-icon\">⏳</div>\n      <h3>Sự việc sắp xảy ra (Không thời gian)</h3>\n      <p>Dùng để dự báo sự việc diễn ra trong tương lai gần.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Chủ ngữ<br><span class=\"syn-keyhz\">S</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">Sắp...<br><span class=\"syn-keyhz\">快要/快</span></div>\n        <span class=\"arrow\">+</span>\n        <div class=\"step\">V/Adj<br><span class=\"syn-keyhz\">...了</span></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ví dụ:</strong> 火车快要来了。(Tàu hỏa sắp đến rồi.)</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">⏰</div>\n      <h3>Sự việc sắp xảy ra (Có mốc thời gian)</h3>\n      <p>Bắt buộc phải dùng 就要 nếu câu xuất hiện từ chỉ thời gian.</p>\n      <div class=\"syn-flow\">\n        <div class=\"step\">Thời gian<br><small>明天/下周</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Sắp<br><small>就要</small></div>\n        <span class=\"arrow\">→</span>\n        <div class=\"step\">Hành động<br><small>...了</small></div>\n      </div>\n      <div class=\"syn-mnemonic\"><strong>Ghi nhớ:</strong> Có mốc thời gian = <b>就</b>要. KHÔNG dùng 快要.</div>\n    </div>\n\n    <div class=\"syn-card theme-ink\">\n      <div class=\"syn-icon\">⚡</div>\n      <h3>Nhấn mạnh \"Đã... rồi\"</h3>\n      <table class=\"syn-table\">\n        <tr><th>Mẫu câu</th><th>Ý nghĩa</th></tr>\n        <tr><td><span class=\"syn-keyhz\">都</span>八点<span class=\"syn-keyhz\">了</span></td><td>Đã 8 giờ rồi (thời gian trôi nhanh/muộn).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">都</span>半个小时<span class=\"syn-keyhz\">了</span></td><td>Đã nửa tiếng rồi (đợi lâu/sốt ruột).</td></tr>\n        <tr><td><span class=\"syn-keyhz\">都</span>十岁<span class=\"syn-keyhz\">了</span></td><td>Đã 10 tuổi rồi (nhấn mạnh sự trưởng thành).</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Mẹo:</strong> 都...了 mang giọng điệu cảm thán/than phiền/ngạc nhiên.</div>\n    </div>\n\n    <div class=\"syn-card theme-gold\">\n      <div class=\"syn-icon\">🧧</div>\n      <h3>Văn hóa: 春节 (Tết Âm lịch)</h3>\n      <table class=\"syn-table\">\n        <tr><th>Hoạt động</th><th>Tiếng Trung</th></tr>\n        <tr><td>Giao thừa/năm mới</td><td><span class=\"syn-keyhz\">新年</span> (Xīnnián)</td></tr>\n        <tr><td>Tiền mừng tuổi</td><td><span class=\"syn-keyhz\">压岁钱</span> (Yāsuìqián)</td></tr>\n        <tr><td>Ăn sủi cảo</td><td><span class=\"syn-keyhz\">吃饺子</span> (Chī jiǎozi)</td></tr>\n      </table>\n      <div class=\"syn-mnemonic\"><strong>Tết (春节):</strong> Là dịp để \"mọi người\" (大家) đoàn tụ.</div>\n    </div>\n  </div>"}],"cssId":"c4afc6c07"}];